// ===== CONNECTEURS DÉBRANCHÉS (mise en réserve du logiciel, septembre 2026) =====
// Le cockpit ne parle plus à aucun service tiers : ni relais IA (Anthropic), ni Gmail, ni Shopify,
// ni Qonto, ni OpenRouteService, ni La Poste, ni Supabase, ni Clerk. Les fonctions serveur (dossier
// api/) ont été retirées du dépôt ; la version branchée reste dans l'historique Git, commit ef819fc
// (PR #494).
//
// Plutôt que de retoucher chacun des dizaines de points d'appel, TOUT appel vers un relais /api
// passe par « relais() » : elle ne fait aucune requête réseau et répond localement par un 503 au
// format que chaque point d'appel sait déjà lire (res.ok faux, corps JSON { error }). Les boutons
// concernés affichent donc un motif clair au lieu d'échouer sur un 404 muet, et les tâches de fond
// (relève des commandes, synchro Gmail) s'arrêtent d'elles-mêmes sans rien coûter.
const CONNECTEURS_DEBRANCHES_MSG = "Connecteur débranché : MITMIT est mis en réserve, ses services externes ont été coupés (l'outil actif est désormais l'application B2B PEN'UP 3D).";
const CLAUDE_URL = "/api/claude";
async function claudeHeaders() {
  return { "Content-Type": "application/json" };
}
async function relais(url, init) {
  void url; void init;
  return new Response(JSON.stringify({ error: CONNECTEURS_DEBRANCHES_MSG }), { status: 503, headers: { "Content-Type": "application/json" } });
}
// Construit un message d'erreur lisible à partir d'une réponse en échec du relais /api/claude :
// remonte le vrai motif (401 non authentifié, 500 clé manquante, erreur/credits Anthropic…) au lieu
// d'un message générique, pour pouvoir diagnostiquer côté production.
async function claudeErrorText(res) {
  let detail = "";
  try { const j = await res.json(); detail = (j && j.error && (j.error.message || j.error)) || (j && j.message) || ""; } catch (e) {}
  if (typeof detail !== "string") { try { detail = JSON.stringify(detail); } catch (e) { detail = ""; } }
  return "HTTP " + res.status + (detail ? " — " + detail : "");
}

// ===== Voie de secours : le relais serveur /api/state =====
// Le navigateur écrit normalement en direct dans la table partagée, avec la clé anon publique. Dès
// qu'une RLS stricte est posée sur cette table (c'est la recommandation de SECURITE.md §2), cette
// écriture est REFUSÉE : la pastille passe « Hors ligne » et y reste, pour de bon, alors que le
// réseau va très bien. Le relais existe déjà côté serveur, avec la clé service role et le jeton
// vérifié ; il n'était simplement jamais appelé. On l'utilise donc en repli de toute écriture ou
// lecture directe refusée. La condition « depuis » y est reconduite à l'identique : le relais n'est
// pas une porte dérobée par laquelle un appareil resté sur un état ancien pourrait écraser une
// session entière.
async function relaisLireEtat() {
  const r = await relais("/api/state", { headers: await claudeHeaders() });
  if (!r.ok) throw new Error("relais /api/state — " + (await claudeErrorText(r)));
  return await r.json(); // { data, updated_at } | null
}
async function relaisEcrireEtat(payload, depuis) {
  const r = await relais("/api/state", { method: "POST", headers: await claudeHeaders(), body: JSON.stringify({ data: payload, depuis: depuis || undefined }) });
  if (!r.ok) throw new Error("relais /api/state — " + (await claudeErrorText(r)));
  let j = {}; try { j = await r.json(); } catch (e) {}
  return j; // { ok, applied, updated_at }
}

// ===== Suivi global des opérations IA =====
// Registre singleton (hors cycle de vie React) : une opération IA continue même si le composant qui
// l'a lancée est démonté (onglet fermé, modale quittée), et reste visible via un indicateur global.
const aiJobs = {
  jobs: new Map(), // id -> { id, label, done, total, _promise }
  subs: new Set(),
  _n: 0,
  _notify() { this.subs.forEach((f) => { try { f(); } catch (e) {} }); },
  subscribe(f) { this.subs.add(f); return () => this.subs.delete(f); },
  list() { return [...this.jobs.values()]; },
  count() { return this.jobs.size; },
  has(id) { return this.jobs.has(id); },
  get(id) { return this.jobs.get(id) || null; },
  begin(id, label, total) { this.jobs.set(id, { id, label: label || "IA…", done: 0, total: total || 0 }); this._notify(); },
  progress(id, done, total) { const j = this.jobs.get(id); if (j) { if (done != null) j.done = done; if (total != null) j.total = total; this._notify(); } },
  end(id) { if (this.jobs.delete(id)) this._notify(); },
  anon(label) { const id = "ai_" + (++this._n) + "_x"; this.begin(id, label); return id; },
  // Lance une opération IA nommée qui survit au démontage. Si un job du même id tourne déjà, on ne le
  // relance pas (on renvoie sa promesse en cours). Le runner reçoit une fonction de progression (done, total).
  run(id, label, runner, total) {
    const ex = this.jobs.get(id);
    if (ex && ex._promise) return ex._promise;
    this.begin(id, label, total);
    const j = this.jobs.get(id);
    const p = (async () => { try { return await runner((d, t) => this.progress(id, d, t)); } finally { this.end(id); } })();
    if (j) j._promise = p;
    return p;
  },
};
// État de la vague de mailing de prospection, conservé HORS des composants. La génération elle-même
// tourne déjà dans aiJobs, qui survit au démontage : fermer le volet ne l'interrompt pas et les appels
// IA restent facturés. Sans ce magasin, les mails déjà rédigés — et les filtres saisis — étaient
// pourtant perdus à la fermeture. On peut désormais sortir du volet et y revenir sur la même page.
const mailingWave = {
  cards: [],
  form: {}, // valeurs des champs du volet (filtres, consigne, ton, sélection…)
  subs: new Set(),
  sub(f) { this.subs.add(f); return () => this.subs.delete(f); },
  _notify() { this.subs.forEach((f) => { try { f(this.cards); } catch (e) {} }); },
  setCards(next) { this.cards = typeof next === "function" ? next(this.cards) : next; this._notify(); },
  reset() { this.cards = []; this.form = {}; this._notify(); },
};
// Mémoire de travail des fenêtres IA : tout ce qui a été saisi ou généré survit à leur fermeture, si
// bien qu'on peut sortir d'un volet pendant un traitement et le retrouver à l'identique. Le magasin est
// la source de vérité : un traitement en arrière-plan continue de l'alimenter même fenêtre fermée (un
// setState sur un composant démonté serait sans effet). Cloisonné par « scope » (le dossier concerné),
// pour ne jamais restituer dans une fiche le brouillon d'une autre.
const aiPanels = {
  vals: new Map(), // "scope|clé" -> valeur
  subs: new Map(), // "scope|clé" -> Set de callbacks
  k(scope, key) { return scope + "|" + key; },
  has(scope, key) { return this.vals.has(this.k(scope, key)); },
  get(scope, key) { return this.vals.get(this.k(scope, key)); },
  set(scope, key, upd) {
    const kk = this.k(scope, key);
    const next = typeof upd === "function" ? upd(this.vals.get(kk)) : upd;
    this.vals.set(kk, next);
    const s = this.subs.get(kk); if (s) s.forEach((f) => { try { f(next); } catch (e) {} });
    return next;
  },
  sub(scope, key, f) { const kk = this.k(scope, key); if (!this.subs.has(kk)) this.subs.set(kk, new Set()); this.subs.get(kk).add(f); return () => { const s = this.subs.get(kk); if (s) s.delete(f); }; },
  // Oublie tout ce qui concerne un dossier (ex. « recommencer » dans le volet).
  clear(scope) { const pre = scope + "|"; [...this.vals.keys()].filter((k) => k.startsWith(pre)).forEach((k) => { this.vals.delete(k); const s = this.subs.get(k); if (s) s.forEach((f) => { try { f(undefined); } catch (e) {} }); }); },
};
// Réglages d'affichage d'un onglet — filtres, recherche, tri, sélection — conservés d'un passage à
// l'autre. Changer d'onglet DÉMONTE le précédent : sans cela, on retrouvait la carte vierge de ses
// filtres au retour, et il fallait tout recocher. S'utilise exactement comme useState.
//
// Ne conviennent PAS à ce traitement : les fenêtres modales, les indicateurs d'activité et les
// messages passagers. Rouvrir une modale que l'utilisateur croyait fermée serait déroutant, et un
// « chargement en cours » figé mentirait sur l'état réel.
const useVue = (vue, cle, initial) => useKept("vue:" + vue, cle, initial);
// useState dont la valeur survit à la fermeture de la fenêtre, et que peut alimenter un traitement en
// cours même fenêtre fermée. S'utilise exactement comme useState.
function useKept(scope, key, initial) {
  const [v, setV] = useState(() => aiPanels.has(scope, key) ? aiPanels.get(scope, key) : (aiPanels.set(scope, key, typeof initial === "function" ? initial() : initial)));
  useEffect(() => {
    if (!aiPanels.has(scope, key)) aiPanels.set(scope, key, typeof initial === "function" ? initial() : initial);
    setV(aiPanels.get(scope, key));
    return aiPanels.sub(scope, key, setV);
  }, [scope, key]);
  return [v, useCallback((upd) => aiPanels.set(scope, key, upd), [scope, key])];
}
// Cartes de la vague : le magasin est la source de vérité, si bien que la génération continue de les
// alimenter même quand le volet est fermé (un setState sur un composant démonté serait sans effet).
function useWaveCards() {
  const [cards, set] = useState(mailingWave.cards);
  useEffect(() => mailingWave.sub(set), []);
  return [cards, (n) => mailingWave.setCards(n)];
}
// useState dont la valeur survit à la fermeture du volet (mémorisée dans mailingWave.form).
function useWaveState(key, initial) {
  const [v, setV] = useState(() => (key in mailingWave.form ? mailingWave.form[key] : (typeof initial === "function" ? initial() : initial)));
  return [v, (upd) => setV((prev) => { const next = typeof upd === "function" ? upd(prev) : upd; mailingWave.form[key] = next; return next; })];
}
function useAiJobs() {
  const [, force] = useState(0);
  useEffect(() => aiJobs.subscribe(() => force((x) => x + 1)), []);
  return aiJobs;
}
// Indicateur global « IA en cours » affiché dans la barre du haut, visible sur tous les onglets.
function AiJobsBadge() {
  const jobs = useAiJobs();
  const list = jobs.list();
  if (!list.length) return null;
  const withProg = list.find((j) => j.total > 0);
  const label = list.length === 1 ? list[0].label : list.length + " opérations IA";
  const prog = withProg && withProg.total ? " " + withProg.done + "/" + withProg.total : "";
  return (<span title={list.map((j) => j.label + (j.total ? " (" + j.done + "/" + j.total + ")" : "")).join("\n")} style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11.5, fontWeight: 700, color: "#fff", background: "#7c5cf0", border: "1px solid #7c5cf0", borderRadius: 20, padding: "5px 11px", whiteSpace: "nowrap" }}><Sparkles size={13} className="spin" />{label}{prog}</span>);
}

// Lecture du stock Shopify via le relais serveur /api/shopify (token Admin protege cote serveur).
// action « test » : verifie la connexion. action « sync » : renvoie les variantes (SKU + quantite).
async function shopifyApi(action, creds) {
  const payload = { action };
  if (creds && creds.domain) payload.domain = String(creds.domain).trim();
  if (creds && creds.token) payload.token = String(creds.token).trim();
  const res = await relais("/api/shopify", { method: "POST", headers: await claudeHeaders(), body: JSON.stringify(payload) });
  let dt = {}; try { dt = await res.json(); } catch (e) {}
  if (!res.ok) throw new Error((dt && dt.error) ? dt.error : ("Erreur Shopify (" + res.status + ")"));
  return dt;
}

// Lecture de la banque Qonto via le relais serveur /api/outils (action « qonto »). Les identifiants
// vivent UNIQUEMENT dans les variables d'environnement Vercel : rien ne transite par le navigateur,
// rien n'est enregistré dans la base partagée. La lecture est seule permise, aucune écriture bancaire.
async function qontoApi(quoi, params) {
  const res = await relais("/api/outils", { method: "POST", headers: await claudeHeaders(), body: JSON.stringify({ action: "qonto", quoi, ...(params || {}) }) });
  let dt = {}; try { dt = await res.json(); } catch (e) {}
  if (!res.ok) throw new Error((dt && dt.error) ? dt.error : ("Erreur Qonto (" + res.status + ")"));
  return dt;
}

// Rapproche les variantes Shopify (par SKU) avec le catalogue MITMIT (par code).
// Renvoie un patch { code: dispo } et le nombre de references appariees.
function shopifyStockPatch(products, variants) {
  const bySku = {};
  (variants || []).forEach((v) => { if (v && v.sku) bySku[String(v.sku).trim().toLowerCase()] = v; });
  const patch = {}; let matched = 0;
  (products || []).forEach((p) => {
    const v = bySku[String(p.code || "").trim().toLowerCase()];
    if (v && v.dispo != null && !isNaN(v.dispo)) { patch[p.code] = Math.max(0, Math.round(v.dispo)); matched++; }
  });
  return { patch, matched };
}

/* ===== PEN'UP 3D — Poste de pilotage B2B + Logistique (v5) ===== */
// Logo Pen'Up 3D : dans lib/logoPenUp.js, partagé avec le bon de commande en ligne.
const MASCOT_URI = "data:image/png;base64,";
// Vignettes produits : dans lib/productImages.js, partagées avec le bon de commande en ligne.


const KEY = "penup_cockpit_v3";
// Curseur de synchronisation : updated_at de la dernière version serveur ACQUITTÉE par cet appareil.
// Persisté pour qu'au rechargement on sache si le cache local contient une fin de session jamais
// poussée (curseur égal au serveur → le local est au moins aussi récent) ou s'il est en retard.
const SYNC_KEY = KEY + ":syncAt";
const lireCurseurSync = () => { try { return localStorage.getItem(SYNC_KEY) || null; } catch (e) { return null; } };
const ecrireCurseurSync = (ts) => { try { if (ts) localStorage.setItem(SYNC_KEY, ts); } catch (e) { } };
// ===== Fusion à trois versions (base commune / local / distant) =====
// Le stockage partagé est une seule ligne JSON : sans fusion, deux appareils qui écrivent chacun leur
// état COMPLET s'écrasent mutuellement (« dernier écrivain gagne ») — un téléphone resté ouvert sur un
// état ancien pouvait effacer toute une session faite sur l'ordinateur. Ici, en cas de conflit détecté,
// on repart de la dernière version que les deux appareils avaient en commun (la base) : ce que CHAQUE
// côté a changé par rapport à elle est conservé ; si les deux ont modifié la même chose, le local
// (la saisie active de l'utilisateur) l'emporte.
const jsonEgal = (a, b) => { try { return JSON.stringify(a) === JSON.stringify(b); } catch (e) { return false; } };
function fusionValeur(b, l, r, prof) {
  if (jsonEgal(l, r)) return l;
  const listeId = (v) => Array.isArray(v) && v.every((x) => x && typeof x === "object" && x.id != null);
  if ((Array.isArray(l) || Array.isArray(r)) && listeId(l || []) && listeId(r || []) && ((l && l.length) || (r && r.length))) {
    const bM = new Map((Array.isArray(b) ? b : []).filter((x) => x && x.id != null).map((x) => [x.id, x]));
    const lM = new Map((l || []).map((x) => [x.id, x]));
    const rM = new Map((r || []).map((x) => [x.id, x]));
    const res = [];
    rM.forEach((rv, id) => {
      if (lM.has(id)) { res.push(jsonEgal(lM.get(id), bM.get(id)) ? rv : lM.get(id)); return; } // inchangé ici → version distante ; modifié ici → la nôtre
      const bv = bM.get(id);
      if (bv && jsonEgal(rv, bv)) return; // supprimé ici, intact là-bas → la suppression tient
      res.push(rv); // nouveau là-bas, ou supprimé ici mais modifié là-bas → on le garde (ne jamais perdre une modification)
    });
    lM.forEach((lv, id) => {
      if (rM.has(id)) return;
      const bv = bM.get(id);
      if (!bv || !jsonEgal(lv, bv)) res.push(lv); // créé ici, ou supprimé là-bas mais modifié ici → on le garde
    });
    return res;
  }
  const objSimple = (v) => v && typeof v === "object" && !Array.isArray(v);
  if (objSimple(l) && objSimple(r) && prof < 2) {
    const out = {}; const bO = objSimple(b) ? b : {};
    new Set([...Object.keys(l), ...Object.keys(r)]).forEach((k) => {
      const v = fusionValeur(bO[k], l[k], r[k], prof + 1);
      if (v !== undefined) out[k] = v;
    });
    // Clé supprimée d'un côté et intacte de l'autre : la suppression tient (sinon la clé restait via l'autre côté).
    Object.keys(out).forEach((k) => { if (!(k in l) && jsonEgal(out[k], bO[k])) delete out[k]; });
    return out;
  }
  return jsonEgal(l, b) ? r : l; // scalaire ou structure opaque : celui qui a changé l'emporte, le local en cas de double changement
}
function fusionEtats(base, local, distant) {
  if (!local) return distant; if (!distant) return local;
  return fusionValeur(base || {}, local, distant, 0);
}
// ===== Cache local en IndexedDB =====
// localStorage plafonne vers 5 Mo et déborde SILENCIEUSEMENT (photos volumineuses) : le cache local
// devenait incomplet sans prévenir. IndexedDB accepte des centaines de Mo et stocke l'objet tel quel
// (clonage structuré, pas de sérialisation JSON). localStorage reste le repli si IndexedDB est
// indisponible, et la source de migration au premier lancement après cette version.
let _idbPromesse = null;
const idbBase = () => {
  if (_idbPromesse) return _idbPromesse;
  _idbPromesse = new Promise((res, rej) => {
    if (typeof indexedDB === "undefined") { rej(new Error("indexedDB indisponible")); return; }
    const rq = indexedDB.open("penup_cockpit_cache", 1);
    rq.onupgradeneeded = () => { try { rq.result.createObjectStore("kv"); } catch (e) { } };
    rq.onsuccess = () => res(rq.result);
    rq.onerror = () => rej(rq.error || new Error("ouverture IndexedDB refusée"));
  }).catch((e) => { _idbPromesse = null; throw e; });
  return _idbPromesse;
};
const idbLire = async (k) => { const db = await idbBase(); return new Promise((res, rej) => { const rq = db.transaction("kv").objectStore("kv").get(k); rq.onsuccess = () => res(rq.result); rq.onerror = () => rej(rq.error); }); };
const idbEcrire = async (k, v) => { const db = await idbBase(); return new Promise((res, rej) => { const tx = db.transaction("kv", "readwrite"); tx.objectStore("kv").put(v, k); tx.oncomplete = () => res(); tx.onerror = () => rej(tx.error); tx.onabort = () => rej(tx.error); }); };
async function lireCacheLocal() {
  try { const v = await idbLire(KEY); if (v) return v; } catch (e) { }
  try { const raw = localStorage.getItem(KEY); if (raw) return JSON.parse(raw); } catch (e) { }
  return null;
}
// Base commune PERSISTÉE : dernière version serveur acquittée par cet appareil. Sans elle, un
// rechargement qui trouve le serveur plus avancé que son curseur ne peut que choisir — garder le
// serveur et perdre la fin de session locale jamais poussée, ou garder le local et perdre le travail
// de l'autre appareil. Avec elle, les deux se fusionnent comme lors d'un conflit d'écriture.
const BASE_KEY = KEY + ":base";
const lireBaseLocale = async () => { try { return (await idbLire(BASE_KEY)) || null; } catch (e) { return null; } };
// Cache local mis de côté faute de base commune : jamais jeté en silence, restaurable depuis
// « Historique & corbeille ».
const ECARTE_KEY = KEY + ":ecarte";
const lireEcarte = async () => { try { return (await idbLire(ECARTE_KEY)) || null; } catch (e) { return null; } };
// ===== Corbeille (30 jours) =====
// Toute fiche supprimée passe par data.trash au lieu de disparaître : récupérable pendant 30 jours
// depuis « Historique & corbeille ». La capture est automatique et centrale (différence avant/après
// dans persist) : aucun point de suppression de l'app n'a besoin d'y penser. La corbeille fait partie
// des données synchronisées, donc partagée entre appareils et fusionnée comme le reste.
const CORBEILLE_COLLECTIONS = { accounts: "Groupe / compte", sites: "Établissement", contacts: "Contact", interactions: "Échange", events: "Événement", deals: "Document", prospects: "Prospect", tickets: "Ticket SAV" };
const CORBEILLE_JOURS = 30;
// Copie allégée pour la corbeille : les champs texte énormes (photos base64) sont vidés pour ne pas
// tripler le poids des données synchronisées.
const corbeilleAllege = (it) => { const o = {}; Object.keys(it || {}).forEach((k) => { const v = it[k]; o[k] = (typeof v === "string" && v.length > 20000) ? "" : v; }); return o; };
function corbeilleLibelle(kind, it) {
  if (!it) return "—";
  return it.enseigne || it.label || [it.prenom, it.nom].filter(Boolean).join(" ") || it.titre || it.sujet || it.ref || (it.adresse ? String(it.adresse).slice(0, 40) : "") || it.id || "—";
}
const TODAY = () => new Date().toISOString().slice(0, 10);
const SIEGE = { lat: 44.0177, lng: 1.3550, ville: "Montauban" };

// Entonnoir commercial. Les 5 étapes sont déterminées AUTOMATIQUEMENT selon l'avancement de la
// relation (voir deriveStage) : enregistré-non-contacté → démarché → RDV découverte → 1re commande
// → commandes récurrentes. L'utilisateur peut figer une étape à la main (stageAuto=false).
const STAGES = [
  { id: "prospect", label: "Prospect", color: "#9aa6bd" }, { id: "contact", label: "Contacté", color: "#5b8def" },
  { id: "rdv", label: "RDV découverte", color: "#7c5cf0" }, { id: "referencement", label: "Client", color: "#2bb673" },
];
// L'étape « Client fidèle » (actif) a été SUPPRIMÉE : sans recul suffisant, la distinction n'avait
// pas de sens. « Client » est l'étape terminale ; les anciens comptes « actif » y sont migrés au
// chargement (voir normalize) et l'historique stageLog conserve la trace telle quelle.
const STAGE_ORDER = ["prospect", "contact", "rdv", "referencement"];
const DEAL_STATUS = { brouillon: { label: "Brouillon", color: "#9aa6bd" }, envoye: { label: "Envoyé", color: "#5b8def" }, accepte: { label: "Accepté / Signé", color: "#2bb673" }, expediee: { label: "En cours de livraison", color: "#F8B133" }, refuse: { label: "Refusé", color: "#FF5A45" }, livre: { label: "Livré", color: "#3F60AA" }, paye: { label: "Livré et payé", color: "#128C6E" } };
// Délais de paiement proposés sur un devis, une commande ou une facture. Les plafonds légaux entre
// professionnels (art. L441-10 du code de commerce) sont 60 jours date de facture, ou 45 jours fin
// de mois : rien au-delà n'est proposé ici.
const PAIEMENT_DEFAUT = "30j";
const PAIEMENT_TERMES = [
  { id: "comptant", label: "Paiement comptant", court: "comptant", jours: 0 },
  { id: "livraison", label: "Paiement à la livraison", court: "à la livraison", jours: 0 },
  { id: "reception", label: "Paiement à réception de facture", court: "à réception", jours: 0 },
  { id: "acompte30", label: "Acompte de 30 % à la commande, solde à la livraison", court: "acompte 30 %", jours: 0 },
  { id: "15j", label: "Paiement à 15 jours date de facturation", court: "15 j", jours: 15 },
  { id: "30j", label: "Paiement à 30 jours date de facturation", court: "30 j", jours: 30 },
  { id: "30jfm", label: "Paiement à 30 jours fin de mois", court: "30 j fdm", jours: 30, fdm: true },
  { id: "45j", label: "Paiement à 45 jours date de facturation", court: "45 j", jours: 45 },
  { id: "45jfm", label: "Paiement à 45 jours fin de mois", court: "45 j fdm", jours: 45, fdm: true },
  { id: "60j", label: "Paiement à 60 jours date de facturation", court: "60 j", jours: 60 },
];
const paiementTerme = (id) => PAIEMENT_TERMES.find((t) => t.id === id) || null;
// Échéance d'une facture : date + N jours, reportée en fin de mois pour les termes « fin de mois ».
function echeancePaiement(dateStr, id) {
  const t = paiementTerme(id); if (!t || !dateStr || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return "";
  const d = new Date(dateStr + "T00:00:00"); if (isNaN(d)) return "";
  if (!t.jours) return "";
  d.setDate(d.getDate() + t.jours);
  if (t.fdm) d.setDate(new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate());
  return isoLocal(d);
}
// « Livré » et « Livré et payé » sont deux fins de course : la marchandise est partie dans les deux
// cas, seul l'encaissement les sépare. Tout ce qui distingue « en cours » de « terminé » doit donc
// traiter les deux ensemble, sans quoi un document payé retomberait dans le pipeline ouvert.
const DEAL_LIVRE = (s) => s === "livre" || s === "paye";
// Définition métier (appliquée partout) : le « CA HT en attente » = les DEVIS (documents non encore
// facturés), le « CA HT signé » = les FACTURES. Un devis refusé ou déjà converti ne compte plus en
// attente ; les avoirs ne comptent pas comme CA signé.
const isDevisEnAttente = (d) => d && d.type === "Devis" && d.statut !== "refuse" && !d.converti;
const isCaSigne = (d) => d && d.type === "Facture" && d.statut !== "refuse";
const sumMontant = (arr) => (arr || []).reduce((s, d) => s + (d.montant || 0), 0);
const escapeHtml = (s) => String(s == null ? "" : s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
// Décode les entités HTML (ex. &#39; → '), pour afficher proprement les courriels importés de Gmail
// (le snippet et les corps HTML arrivent échappés). Idempotent côté affichage.
const decodeEntities = (s) => String(s == null ? "" : s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => { try { return String.fromCodePoint(parseInt(h, 16)); } catch { return _; } })
  .replace(/&#(\d+);/g, (_, n) => { try { return String.fromCodePoint(parseInt(n, 10)); } catch { return _; } })
  .replace(/&nbsp;/gi, " ").replace(/&apos;/gi, "'").replace(/&quot;/gi, '"')
  .replace(/&lt;/gi, "<").replace(/&gt;/gi, ">").replace(/&amp;/gi, "&");
// Ouvre une fenêtre d'impression (PDF) avec un document HTML mis en forme.
function openPrint(title, bodyHtml) {
  const w = window.open("", "_blank");
  if (!w) { alert("Autorisez les fenêtres pop-up de ce site pour générer le PDF."); return; }
  w.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><style>body{font-family:'Segoe UI',Arial,sans-serif;color:#16203a;padding:30px;max-width:800px;margin:auto;line-height:1.45;}h1{font-size:23px;margin:0 0 2px;}h2{font-size:14px;color:#16203a;border-bottom:2px solid #FF5A45;padding-bottom:4px;margin:24px 0 8px;}table{width:100%;border-collapse:collapse;font-size:12px;margin-top:4px;}th,td{text-align:left;padding:6px 8px;border-bottom:1px solid #eaeef5;}th{color:#5b6478;font-weight:600;font-size:11px;text-transform:uppercase;}.muted{color:#5b6478;font-size:12px;}.stat{display:inline-block;margin:0 22px 6px 0;font-size:12px;}.stat b{display:block;font-size:16px;}.tag{display:inline-block;font-size:11px;background:#eef2fb;border-radius:6px;padding:2px 8px;margin:0 6px 4px 0;}.foot{margin-top:30px;color:#9aa6bd;font-size:10.5px;border-top:1px solid #eaeef5;padding-top:8px;}</style></head><body>${bodyHtml}<div class="foot">PEN'UP 3D · MITMIT · export du ${new Date().toLocaleDateString("fr-FR")}</div><script>window.onload=function(){setTimeout(function(){window.print();},250);}<\/script></body></html>`);
  w.document.close();
}
// Catalogue partageable : corps HTML de la gamme (produits vendables), groupé par famille, prêt à
// exporter en PDF (via openPrint) et à envoyer au prospect.
function buildCatalogueHtml(products) {
  const vend = (products || []).filter((p) => p.vendable !== false);
  const byFam = {}; vend.forEach((p) => { const f = p.famille || "Autre"; (byFam[f] = byFam[f] || []).push(p); });
  const fams = Object.keys(byFam).sort((a, b) => a.localeCompare(b, "fr"));
  let html = `<h1>Catalogue PEN'UP 3D</h1><div class="muted">Gamme · ${vend.length} référence(s) · prix public conseillé (PVC) TTC indicatif.</div>`;
  fams.forEach((f) => {
    const rows = byFam[f].slice().sort((a, b) => (a.designation || "").localeCompare(b.designation || "", "fr")).map((p) => `<tr><td><strong>${escapeHtml(p.designation || p.code || "")}</strong></td><td class="muted">${escapeHtml(p.code || "")}</td><td style="text-align:right">${escapeHtml(p.pvc != null ? eur(p.pvc) : "—")}</td></tr>`).join("");
    html += `<h2>${escapeHtml(f)}</h2><table><thead><tr><th>Désignation</th><th>Référence</th><th style="text-align:right">PVC TTC</th></tr></thead><tbody>${rows}</tbody></table>`;
  });
  return html;
}
// Construit le corps HTML d'une fiche (groupe ou établissement) pour l'export PDF.
function ficheBody(title, subtitle, tags, stats, conts, deals, ints, acc, data) {
  const stat = (stats || []).map((s) => `<span class="stat"><b>${escapeHtml(s.v)}</b>${escapeHtml(s.l)}</span>`).join("");
  const tagH = (tags || []).filter(Boolean).map((t) => `<span class="tag">${escapeHtml(t)}</span>`).join("");
  const cH = conts.length ? `<table><thead><tr><th>Nom</th><th>Fonction</th><th>Rôle</th><th>Courriel</th><th>Téléphone</th></tr></thead><tbody>${conts.map((c) => `<tr><td>${escapeHtml(fullName(c))}${c.principal ? " ★" : ""}</td><td>${escapeHtml(c.fonction)}</td><td>${escapeHtml((ROLE_META[c.role] || {}).label || "")}</td><td>${escapeHtml(c.email)}</td><td>${escapeHtml(c.mobile || c.fixe || "")}</td></tr>`).join("")}</tbody></table>` : `<div class="muted">Aucun contact.</div>`;
  const dH = deals.length ? `<table><thead><tr><th>Réf.</th><th>Type</th><th>Date</th><th>Statut</th><th style="text-align:right">Montant HT</th></tr></thead><tbody>${deals.map((d) => `<tr><td>${escapeHtml(data ? docRef(d, { code: dealDocCode(data, d) }) : docRef(d, acc))}</td><td>${escapeHtml(d.type)}</td><td>${escapeHtml(d.date)}</td><td>${escapeHtml((DEAL_STATUS[d.statut] || {}).label || d.statut)}</td><td style="text-align:right">${escapeHtml(eur(d.montant))}</td></tr>`).join("")}</tbody></table>` : `<div class="muted">Aucun document.</div>`;
  const iH = ints.length ? `<table><thead><tr><th>Date</th><th>Type</th><th>Sujet</th><th>Résumé</th></tr></thead><tbody>${ints.slice(0, 50).map((i) => `<tr><td>${escapeHtml(i.date)}</td><td>${escapeHtml((INT_META[i.type] || {}).label || i.type)}</td><td>${escapeHtml(i.sujet)}</td><td>${escapeHtml(i.resume || "")}</td></tr>`).join("")}</tbody></table>` : `<div class="muted">Aucun échange.</div>`;
  return `<h1>${escapeHtml(title)}</h1><div class="muted">${escapeHtml(subtitle)}</div><div style="margin-top:8px">${tagH}</div><div style="margin-top:14px">${stat}</div><h2>Contacts</h2>${cH}<h2>Devis, commandes &amp; factures</h2>${dH}<h2>Échanges</h2>${iH}`;
}
// Nombre de jours depuis le dernier échange d'un compte (null si jamais).
function daysSinceLastExchange(accId, data) {
  const ds = (data.interactions || []).filter((i) => i.accountId === accId && i.date).map((i) => i.date).sort();
  if (!ds.length) return null;
  const n = daysFromToday(ds[ds.length - 1]);
  return n == null ? null : Math.max(0, -n);
}
// Score de priorité 0-100 : argent en attente (devis non validés), ancienneté du dernier contact, étape.
function priorityScore(account, data) {
  const caAtt = sumMontant((data.deals || []).filter((d) => d.accountId === account.id && isDevisEnAttente(d)));
  const days = daysSinceLastExchange(account.id, data);
  const stageW = { prospect: 6, contact: 14, rdv: 22, referencement: 28, actif: 10 }[account.stage] || 8;
  let s = Math.min(40, (caAtt / 1000) * 4) + Math.min(35, (days == null ? 30 : days) * 0.6) + stageW;
  s = Math.round(Math.min(100, s));
  const lvl = s >= 60 ? { l: "Élevée", c: "#FF5A45" } : s >= 35 ? { l: "Moyenne", c: "#F8B133" } : { l: "Faible", c: "#9aa6bd" };
  return { score: s, level: lvl.l, color: lvl.c, caAtt, days };
}
// Programme de fidélité revendeur : palier (Bronze / Argent / Or) selon le CA HT signé sur 12 mois
// glissants, avec la distance au palier suivant — utilisable comme argument de vente (« encore X € »).
const LOYALTY_TIERS = [{ id: "or", label: "Or", color: "#F8B133", min: 6000 }, { id: "argent", label: "Argent", color: "#9aa6bd", min: 2000 }, { id: "bronze", label: "Bronze", color: "#b87333", min: 0 }];
function loyaltyTier(deals) {
  const since = Date.now() - 365 * 86400000;
  const ca12 = sumMontant((deals || []).filter((d) => isCaSigne(d) && d.date && new Date(d.date).getTime() >= since));
  const tier = LOYALTY_TIERS.find((t) => ca12 >= t.min) || LOYALTY_TIERS[LOYALTY_TIERS.length - 1];
  const idx = LOYALTY_TIERS.indexOf(tier); const next = idx > 0 ? LOYALTY_TIERS[idx - 1] : null;
  return { ca12, tier, next, toNext: next ? Math.max(0, next.min - ca12) : 0 };
}
// Carte de visite vCard 3.0 d'un contact (téléchargeable / encodable en QR).
function contactVCard(c, account) {
  const org = account ? account.enseigne : "";
  return ["BEGIN:VCARD", "VERSION:3.0", "N:" + (c.nom || "") + ";" + (c.prenom || ""), "FN:" + fullName(c), org ? ("ORG:" + org) : "", c.fonction ? ("TITLE:" + c.fonction) : "", c.email ? ("EMAIL;TYPE=WORK:" + c.email) : "", c.mobile ? ("TEL;TYPE=CELL:" + c.mobile) : "", c.fixe ? ("TEL;TYPE=WORK:" + c.fixe) : "", c.linkedin ? ("URL:" + c.linkedin) : "", c.naissance ? ("BDAY:" + c.naissance) : "", "END:VCARD"].filter(Boolean).join("\r\n");
}
// Carte de visite vCard 3.0 d'une société / enseigne (téléchargeable / encodable en QR).
function companyVCard(account, data) {
  if (!account) return "";
  const name = account.enseigne || "Société";
  const adr = (account.adressePostale || account.adresseLivraison || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
  const loc = parseLocality(adr);
  const ville = account.ville || loc.ville || "";
  // Si on a une adresse complète, on la met dans le champ « rue » ; sinon on retombe sur la ville seule.
  const adrLine = adr ? ("ADR;TYPE=WORK:;;" + adr + ";;;;France") : (ville ? ("ADR;TYPE=WORK:;;;" + ville + ";;;France") : "");
  const noteParts = [];
  if (account.siren) noteParts.push("SIREN " + account.siren);
  if (account.formeJuridique) noteParts.push(account.formeJuridique);
  return ["BEGIN:VCARD", "VERSION:3.0", "N:" + name + ";;;;", "FN:" + name, "ORG:" + name, adrLine, noteParts.length ? ("NOTE:" + noteParts.join(" · ")) : "", "X-ABShowAs:COMPANY", "END:VCARD"].filter(Boolean).join("\r\n");
}
