      const rel = deals.filter((d) => d.type === "Devis" && d.statut === "envoye" && d.date).map((d) => ({ d, age: Math.floor((Date.now() - new Date(d.date).getTime()) / 86400000) })).filter((x) => x.age >= 5).sort((a, b) => b.age - a.age).slice(0, 6);
      if (rel.length === 0) return null;
      const relMailDeal = (d) => { const a = accounts.find((x) => x.id === d.accountId); const cs = contacts.filter((c) => c.accountId === d.accountId); const pc = cs.find((c) => c.principal) || cs[0]; const to = pc && pc.email ? pc.email : ""; const subj = encodeURIComponent("Relance devis " + (d.ref || "") + (a ? " · " + a.enseigne : "")); const body = encodeURIComponent("Bonjour" + (pc && pc.prenom ? " " + pc.prenom : "") + ",\n\nJe reviens vers vous au sujet de notre devis " + (d.ref || "") + (a ? " pour " + a.enseigne : "") + " (" + eur(d.montant) + " HT). Avez-vous pu l'étudier ?\n\nBien à vous,\n"); return "mailto:" + to + "?subject=" + subj + "&body=" + body; };
      return (<div className="card" style={{ marginBottom: 18, borderLeft: "4px solid var(--amber)" }}><div className="sec-h"><h3 className="pu-display" style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><FileText size={16} style={{ color: "var(--amber)" }} /> Devis en attente à relancer</h3><span>envoyés sans réponse</span></div>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>{rel.map(({ d, age }) => { const a = accounts.find((x) => x.id === d.accountId); const cs = contacts.filter((c) => c.accountId === d.accountId); const pc = cs.find((c) => c.principal) || cs[0]; return (<div key={d.id} className="hrow" style={{ display: "flex", alignItems: "center", gap: 11, padding: "8px 0", borderBottom: "1px solid #f0f3f9", flexWrap: "wrap" }}><div style={{ flex: 1, minWidth: 180 }}><div className="lnk" style={{ fontWeight: 700, fontSize: 13.5 }} onClick={() => go("accounts", d.accountId)}>{d.ref || "Devis"} <span style={{ color: "var(--muted)", fontWeight: 500 }}>· {a ? a.enseigne : ""}</span></div><div style={{ fontSize: 11.5, color: "var(--muted)" }}>{eur(d.montant)} HT · envoyé il y a <strong style={{ color: age >= 14 ? "var(--red)" : "var(--amber)" }}>{age} j</strong></div></div>{pc && pc.email ? <a className="btn btn-g btn-s" href={relMailDeal(d)}><Mail size={14} /> Relancer</a> : <button className="btn btn-g btn-s" onClick={() => go("accounts", d.accountId)}><ChevronRight size={14} /> Ouvrir</button>}</div>); })}</div>
      </div>);
