    `${an}-01-01`, `${an}-05-01`, `${an}-05-08`, `${an}-07-14`,
    `${an}-08-15`, `${an}-11-01`, `${an}-11-11`, `${an}-12-25`,
    iso(plus(1)), iso(plus(39)), iso(plus(50))
