  const acc = (accounts || []).find((a) => a.id === contact.accountId) || null;
  if (!site && acc && !isGroupe(acc)) site = (sites || []).find((s) => s.accountId === acc.id && (s.type === "pdv" || s.type === "decision")) || null;
