  const SKIP = /^\s*(?:#PENUP|--LIGNES|#END|CLIENT:|ENSEIGNE:|CONTACT:|EMAIL:|TEL:|SIRET:|ADRESSE:|NOTE:|r[ée]f[ée]rence\b|designation\b|d[ée]signation\b|quantit)/i;
