  const add = (code, des, qte, pu, assumed) => { const k = code; if (idx[k] != null) { const ex = lines[idx[k]]; ex.qte += qte; if (!assumed) ex.assumed = false; } else { idx[k] = lines.length; lines.push({ code, designation: des, qte, pu, assumed: !!assumed }); } };
