    <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 8 }}>{list.length} ticket{list.length > 1 ? "s" : ""} {hasFilter ? "filtré" + (list.length > 1 ? "s" : "") : ""}</div>
