    const exDir = (refusesDir ? " " + refusesDir + " résultat(s) refusé(s) : dirigeant exclu de la prospection (achats en centrale, ou magasin détenu par sa tête de réseau)." : "")
      + (horsCible ? " " + horsCible + " hors cible « " + CIBLE_LABEL[kind] + " »." : "");
