  const distNote = coef < coefTarget ? `Sous le plancher du jouet (×${coefTarget.toFixed(2)}) : peu attractif, risque de non-référencement` : coef < coefMax ? `Bas de la fourchette jouet : acceptable mais peu incitatif pour l'acheteur` : `Dans les standards du jouet (×${coefMax.toFixed(2)} et plus) : attractif pour l'enseigne`;
  const anchors = [{ id: "pvcttc", l: "PVC TTC" }, { id: "pvcht", l: "PVC HT" }, { id: "pvd", l: "Prix de cession HT" }, { id: "marge", l: "Marge Pen'Up %" }];
