const NAV_GROUPS = ["Pilotage", "Commercial", "Logistique", "Support", "Outils"];
// Dernière localisation (onglet + fiche ouverte) mémorisée entre deux sessions / rechargements,
// pour rouvrir l'app là où l'utilisateur l'avait laissée plutôt que sur le tableau de bord.
const NAV_STATE_KEY = "penup_nav";
function readSavedNav() { try { const o = JSON.parse(localStorage.getItem(NAV_STATE_KEY) || "null"); return o && o.tab && TABS.some((x) => x.id === o.tab) ? { tab: o.tab, focus: o.focus || null } : null; } catch (e) { return null; } }
const clone = (x) => typeof structuredClone !== "undefined" ? structuredClone(x) : JSON.parse(JSON.stringify(x));

// ============== FLÈCHES DE DÉFILEMENT (haut / bas de page) ==============
// Les listings de MITMIT (prospects, contacts, documents) tiennent sur plusieurs écrans : revenir en
// tête après avoir déroulé demandait jusqu'ici un long geste de molette.
// Le composant est posé HORS de .main : sur un fond à motif, .main force le texte en blanc, et les
// flèches y deviendraient invisibles sur leur pastille claire.
function ScrollArrows() {
  const [pos, setPos] = useState({ scrollable: false, haut: true, bas: false });
  useEffect(() => {
    const mesurer = () => {
      const doc = document.documentElement;
      const y = window.scrollY || doc.scrollTop || 0;
      const total = Math.max(doc.scrollHeight, document.body.scrollHeight);
      const vue = window.innerHeight;
      // Marge de 4 px : les hauteurs sous-pixel d'un zoom navigateur laissent sinon les deux flèches
      // actives en permanence, y compris sur une page qui ne défile pas.
      setPos({ scrollable: total - vue > 4, haut: y <= 4, bas: y + vue >= total - 4 });
    };
    mesurer();
    window.addEventListener("scroll", mesurer, { passive: true });
    window.addEventListener("resize", mesurer);
    // Le contenu change de hauteur sans défilement ni redimensionnement (filtre appliqué, fiche
    // dépliée, recherche terminée) : sans observation, les flèches resteraient dans un état faux.
    let ro = null;
    try { ro = new ResizeObserver(mesurer); ro.observe(document.body); } catch (e) {}
    return () => { window.removeEventListener("scroll", mesurer); window.removeEventListener("resize", mesurer); if (ro) ro.disconnect(); };
  }, []);
  if (!pos.scrollable) return null;
  const doux = (() => { try { return !window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) { return true; } })();
  const aller = (y) => { try { window.scrollTo({ top: y, behavior: doux ? "smooth" : "auto" }); } catch (e) { window.scrollTo(0, y); } };
  return (<div className="scrollarrows no-print" aria-hidden={false}>
    <button type="button" onClick={() => aller(0)} disabled={pos.haut} title="Remonter en haut de la page" aria-label="Remonter en haut de la page"><ArrowUp size={17} /></button>
    <button type="button" onClick={() => aller(Math.max(document.documentElement.scrollHeight, document.body.scrollHeight))} disabled={pos.bas} title="Descendre en bas de la page" aria-label="Descendre en bas de la page"><ArrowDown size={17} /></button>
  </div>);
}

// ============== PIPELINE KANBAN (deals par étape) ==============
// Corps d'une colonne du pipeline : au-delà de TROIS fiches, la colonne défile sur place au lieu
// de s'allonger. La hauteur est mesurée sur la 3e fiche réellement rendue, jamais devinée : les
// cartes n'ont pas toutes la même taille (référence sur une ou deux lignes).
// La barre de droite est dessinée par nous : les barres natives sont flottantes sur macOS comme
// sous Linux et disparaissent au repos, alors qu'on veut un repère visible en permanence.
function KanColumn({ children }) {
  const bodyRef = useRef(null);
  const dragRef = useRef(null);
  const [thumb, setThumb] = useState(null);
  const sync = useCallback(() => {
    const el = bodyRef.current; if (!el) return;
    const cards = el.querySelectorAll(".deal-card");
    if (cards.length > 3) { const t = cards[2]; el.style.maxHeight = Math.round(t.offsetTop + t.offsetHeight - cards[0].offsetTop + 2) + "px"; }
    else el.style.maxHeight = "";
    const ch = el.clientHeight, sh = el.scrollHeight, st = el.scrollTop;
    if (sh <= ch + 1) { setThumb((p) => p ? null : p); return; }
    const h = Math.max(30, Math.round(ch * ch / sh));
    const top = Math.round((ch - h) * (st / (sh - ch)));
    setThumb((p) => (p && p.top === top && p.h === h) ? p : { top, h });
  }, []);
  useEffect(() => { sync(); });
  useEffect(() => { const h = () => sync(); window.addEventListener("resize", h); return () => window.removeEventListener("resize", h); }, [sync]);
  const onThumbDown = (e) => {
    const el = bodyRef.current; if (!el) return;
    e.preventDefault(); e.stopPropagation();
    dragRef.current = { y: e.clientY, st: el.scrollTop };
    const move = (ev) => {
      const b = bodyRef.current, d = dragRef.current; if (!b || !d) return;
      const ch = b.clientHeight, sh = b.scrollHeight;
      const range = ch - Math.max(30, ch * ch / sh);
      if (range > 0) b.scrollTop = d.st + (ev.clientY - d.y) * (sh - ch) / range;
    };
    const up = () => { dragRef.current = null; document.removeEventListener("pointermove", move); document.removeEventListener("pointerup", up); };
    document.addEventListener("pointermove", move); document.addEventListener("pointerup", up);
  };
  const onTrackDown = (e) => {
    const el = bodyRef.current; if (!el || !thumb) return;
    const r = e.currentTarget.getBoundingClientRect();
    const y = e.clientY - r.top;
    el.scrollTop += (y < thumb.top ? -1 : y > thumb.top + thumb.h ? 1 : 0) * el.clientHeight * 0.9;
  };
  return (<div className="col-scroll">
    <div className="col-body" ref={bodyRef} onScroll={sync}>{children}</div>
    {thumb && <div className="col-sb" onPointerDown={onTrackDown}><div className="col-sb-th" style={{ top: thumb.top, height: thumb.h }} onPointerDown={onThumbDown} /></div>}
  </div>);
}
function PipelineKanban({ data, persist, go, embedded }) {
  const STAGES_K = [
    { id: "brouillon", label: "Brouillon", color: "#9aa6bd" },
    { id: "envoye", label: "Envoyé", color: "#5b8def" },
    { id: "accepte", label: "Accepté", color: "#2bb673" },
    { id: "expediee", label: "En cours de livraison", color: "#F8B133" },
    { id: "livre", label: "Livré", color: "#3F60AA" },
    { id: "paye", label: "Livré et payé", color: "#128C6E" },
  ];
  // « Refusé » n'a pas de colonne : le pipeline montre ce qui avance, et un document refusé n'avance
  // plus. Le statut existe toujours — il se pose depuis la fiche du document, et le listing garde son
  // filtre « Refusé » pour les retrouver.
  const accOf = (id) => data.accounts.find((a) => a.id === id);
  // Libellé client d'un document : nom de l'ÉTABLISSEMENT (site lié au document / à la livraison) en
  // priorité, sinon l'enseigne du compte, sinon l'établissement d'un indépendant sans enseigne.
  const findS = (id) => id ? (data.sites || []).find((s) => s.id === id) : null;
  const dealClient = (d) => {
    const site = findS(d.siteId) || findS(d.livraisonSiteId);
    if (site && site.label) return site.label;
    const a = accOf(d.accountId);
    if (a && a.enseigne) return a.enseigne;
    if (a && !isGroupe(a)) { const s = (data.sites || []).find((x) => x.accountId === a.id && (x.type === "pdv" || x.type === "decision")); if (s && s.label) return s.label; }
    return "—";
  };
  const moveDeal = (dealId, newStatut) => persist((p) => ({ ...p, deals: p.deals.map((d) => d.id === dealId ? { ...d, statut: newStatut } : d) }));
  const totalBy = (st) => data.deals.filter((d) => d.statut === st).reduce((s, d) => s + (d.montant || 0), 0);
  const cntBy = (st) => data.deals.filter((d) => d.statut === st).length;
  const [dragId, setDragId] = useState(null); const [dragCol, setDragCol] = useState(null);
  const dwell = useDwellPreview();
  const onDragStart = (e, id) => { e.dataTransfer.setData("text/plain", id); e.dataTransfer.effectAllowed = "move"; setDragId(id); };
  const onDragEnd = () => { setDragId(null); setDragCol(null); };
  const onDragOver = (e, st) => { e.preventDefault(); e.dataTransfer.dropEffect = "move"; if (st && st !== dragCol) setDragCol(st); };
  const onDrop = (e, st) => { e.preventDefault(); const id = e.dataTransfer.getData("text/plain") || dragId; setDragId(null); setDragCol(null); if (id) moveDeal(id, st); };

  return (<div className={embedded ? "" : "fade"}>
    {!embedded && <div className="card" style={{ marginBottom: 14, borderLeft: "4px solid var(--blue)", fontSize: 13, lineHeight: 1.55 }}>Glissez les fiches deals entre les colonnes pour faire évoluer l'étape. Pipeline total visible en haut de chaque colonne.</div>}
    <div className="kan kan-deals">
      {STAGES_K.map((s) => (<div key={s.id} className="col" onDragOver={(e) => onDragOver(e, s.id)} onDrop={(e) => onDrop(e, s.id)} style={dragCol === s.id && dragId ? { background: s.color + "1f", outline: `2px dashed ${s.color}`, outlineOffset: -2 } : undefined}>
        <div className="col-h"><i className="dot" style={{ background: s.color }} />{s.label}<span className="cnt">{cntBy(s.id)} · {eur(totalBy(s.id))}</span></div>
        <KanColumn>
        {data.deals.filter((d) => d.statut === s.id).sort((a, b) => (b.date || "").localeCompare(a.date || "")).map((d) => { const cli = dealClient(d); const dref = docRef(d, { code: dealDocCode(data, d) }); return (
          <div key={d.id} className="deal-card" draggable onDragStart={(e) => { dwell.hide(); onDragStart(e, d.id); }} onDragEnd={onDragEnd} onClick={() => go("deals", d.id)} {...dwell.bind(() => { const ds = DEAL_STATUS[d.statut] || DEAL_STATUS.brouillon; return { title: dref || d.ref || d.type, subtitle: cli, badge: ds.label, badgeColor: ds.color, accent: s.color, rows: [{ label: "Type", value: d.type }, { label: "Date", value: d.date }, { label: "Montant", value: eur(d.montant) }, { label: "Statut", value: ds.label }] }; })} style={{ borderLeft: `4px solid ${s.color}`, opacity: dragId === d.id ? 0.4 : 1, cursor: "grab" }}>
            <h5>{dref || d.ref || d.type}</h5>
            <div className="deal-meta"><Building2 size={11} />{cli}</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 6 }}>
              <span className="deal-meta">{d.date || "—"}</span>
              <span className="deal-amount">{eur(d.montant)}</span>
            </div>
          </div>
        ); })}
        {data.deals.filter((d) => d.statut === s.id).length === 0 && <div style={{ fontSize: 11.5, color: "var(--muted)", padding: "8px 4px", textAlign: "center" }}>Vide</div>}
        </KanColumn>
      </div>))}
    </div>
    {dwell.node}
  </div>);
}

// Types d'événements personnalisés du calendrier (couleur dérivée du type, surchargeable)
// Un événement rattaché à une fiche ARCHIVÉE (établissement, ou compte/groupe — y compris le compte
// parent de l'établissement) sort du calendrier, d'Aujourd'hui et des compteurs : masqué tant que la
// fiche est archivée, il RÉAPPARAÎT tel quel si elle est réactivée (rien n'est supprimé).
function evAncreArchivee(e, data) {
  if (!e) return false;
  if (e.siteId) {
    const s = (data.sites || []).find((x) => x.id === e.siteId);
    if (s) {
      if (s.archived) return true;
      const a = (data.accounts || []).find((x) => x.id === s.accountId);
      if (a && a.archived) return true;
    }
  }
  if (e.accountId) { const a = (data.accounts || []).find((x) => x.id === e.accountId); if (a && a.archived) return true; }
  return false;
}
const EVENT_TYPES = {
  rdv: { label: "RDV / Rencontre", color: "#3F60AA", icon: "🤝" },
  appel: { label: "Appel téléphonique", color: "#0EA5A4", icon: "📞" },
  visio: { label: "Visioconférence", color: "#2563EB", icon: "💻" },
  relance: { label: "Relance commerciale", color: "#F59E0B", icon: "🔔" },
  salon: { label: "Salon / Événement pro", color: "#A855F7", icon: "🎪" },
  preparation: { label: "Préparation", color: "#0891B2", icon: "📋" },
  tache: { label: "Tâche perso", color: "#22C55E", icon: "✅" },
  sav: { label: "SAV / Réclamation", color: "#EC4899", icon: "🛠️" },
  echeance: { label: "Échéance / Deadline", color: "#EF4444", icon: "⏰" },
  livraison: { label: "Livraison attendue", color: "#475569", icon: "📦" },
  autre: { label: "Autre", color: "#94A3B8", icon: "•" },
};

// ====== Export du calendrier au format .ics (iCalendar) ======
// Fichier standard importable dans Google Agenda, Samsung Calendar, Apple Calendar ou Outlook,
// en attendant une synchronisation directe via l'API Google. Sont inclus : les événements de
// l'agenda, les prochaines actions des comptes et les anniversaires (récurrents chaque année).
const icsEscape = (s) => String(s == null ? "" : s).replace(/\\/g, "\\\\").replace(/[;,]/g, (m) => "\\" + m).replace(/\r?\n/g, "\\n");
const icsFold = (line) => { if (line.length <= 73) return line; let out = "", r = line; while (r.length > 73) { out += r.slice(0, 73) + "\r\n "; r = r.slice(73); } return out + r; };
const icsDay = (ymd) => (ymd || "").replace(/-/g, "");
const icsNextDay = (ymd) => { const d = new Date(ymd + "T00:00:00"); d.setDate(d.getDate() + 1); const p = (n) => String(n).padStart(2, "0"); return "" + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()); };
const icsStamp = () => { const d = new Date(), p = (n) => String(n).padStart(2, "0"); return "" + d.getUTCFullYear() + p(d.getUTCMonth() + 1) + p(d.getUTCDate()) + "T" + p(d.getUTCHours()) + p(d.getUTCMinutes()) + p(d.getUTCSeconds()) + "Z"; };
function calendarEventsCount(data) {
  const ev = (data.events || []).filter((e) => e.date).length;
  const act = (data.accounts || []).filter((a) => a.dateAction && a.prochaineAction).length;
  const anniv = (data.contacts || []).filter((c) => c.naissance && /^\d{4}-\d{2}-\d{2}$/.test(c.naissance)).length;
  return { ev, act, anniv, total: ev + act + anniv };
}
function buildCalendarICS(data) {
  const stamp = icsStamp();
  const acc = (id) => (data.accounts || []).find((a) => a.id === id);
  const raw = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//PEN'UP 3D//MITMIT Cockpit//FR", "CALSCALE:GREGORIAN", "METHOD:PUBLISH", "X-WR-CALNAME:MITMIT — PEN'UP 3D", "X-WR-TIMEZONE:Europe/Paris"];
  (data.events || []).forEach((e) => {
    if (!e.date || evAncreArchivee(e, data)) return;
    const a = e.accountId ? acc(e.accountId) : null;
    const tm = EVENT_TYPES[e.type] || EVENT_TYPES.autre;
    const desc = [a ? a.enseigne : "", e.notes || ""].filter(Boolean).join(" — ");
    raw.push("BEGIN:VEVENT", "UID:" + e.id + "@mitmit.penup3d", "DTSTAMP:" + stamp);
    if (e.heure && /^\d{1,2}:\d{2}$/.test(e.heure)) {
      const [hh, mm] = e.heure.split(":"); const p = (n) => String(n).padStart(2, "0");
      const end = new Date(e.date + "T" + p(hh) + ":" + mm + ":00"); end.setHours(end.getHours() + 1);
      raw.push("DTSTART:" + icsDay(e.date) + "T" + p(hh) + mm + "00");
      raw.push("DTEND:" + icsDay(e.date) + "T" + p(end.getHours()) + p(end.getMinutes()) + "00");
    } else {
      raw.push("DTSTART;VALUE=DATE:" + icsDay(e.date), "DTEND;VALUE=DATE:" + icsNextDay(e.date));
    }
    raw.push("SUMMARY:" + icsEscape((tm.icon ? tm.icon + " " : "") + (e.titre || "Événement")));
    if (desc) raw.push("DESCRIPTION:" + icsEscape(desc));
    raw.push("END:VEVENT");
  });
  (data.accounts || []).filter((a) => a.dateAction && a.prochaineAction && !a.archived).forEach((a) => {
    raw.push("BEGIN:VEVENT", "UID:action_" + a.id + "@mitmit.penup3d", "DTSTAMP:" + stamp, "DTSTART;VALUE=DATE:" + icsDay(a.dateAction), "DTEND;VALUE=DATE:" + icsNextDay(a.dateAction), "SUMMARY:" + icsEscape("🔔 " + a.prochaineAction + (a.enseigne ? " — " + a.enseigne : "")), "END:VEVENT");
  });
  (data.contacts || []).filter((c) => c.naissance && /^\d{4}-\d{2}-\d{2}$/.test(c.naissance)).forEach((c) => {
    const a = acc(c.accountId);
    raw.push("BEGIN:VEVENT", "UID:anniv_" + c.id + "@mitmit.penup3d", "DTSTAMP:" + stamp, "DTSTART;VALUE=DATE:" + icsDay(c.naissance), "DTEND;VALUE=DATE:" + icsNextDay(c.naissance), "RRULE:FREQ=YEARLY", "SUMMARY:" + icsEscape("🎂 Anniversaire " + fullName(c) + (a ? " (" + a.enseigne + ")" : "")), "END:VEVENT");
  });
  raw.push("END:VCALENDAR");
  return raw.map(icsFold).join("\r\n");
}
function downloadICS(data) {
  const blob = new Blob([buildCalendarICS(data)], { type: "text/calendar;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = "penup3d-calendrier-" + new Date().toISOString().slice(0, 10) + ".ics";
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}
// Fenêtre « Connecter le calendrier » : abonnement automatique (lien privé que Google Agenda relit
// tout seul, répercuté sur Samsung Calendar via le compte Google) + export ponctuel .ics.
function CalendarExportModal({ data, persist, onClose }) {
  const c = calendarEventsCount(data);
  const token = (data.settings && data.settings.calendarToken) || "";
  const origin = (typeof window !== "undefined" && window.location && window.location.origin) || "";
  const subUrl = token ? origin + "/api/calendar?token=" + token : "";
  const [copied, setCopied] = useState(false);
  const genToken = () => { const t = "cal_" + ((typeof crypto !== "undefined" && crypto.randomUUID) ? crypto.randomUUID().replace(/-/g, "") : (Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2))); persist((p) => ({ ...p, settings: { ...p.settings, calendarToken: t } })); };
  const revoke = () => { appConfirm("Régénérer le lien ? L'ancien lien d'abonnement cessera de fonctionner et devra être remplacé dans Google Agenda.", { title: "Régénérer le lien d'abonnement ?", confirmLabel: "Régénérer" }).then((ok) => { if (ok) genToken(); }); };
  const copy = () => { try { navigator.clipboard.writeText(subUrl); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch (e) { } };
  return (<Modal title="Connecter le calendrier" onClose={onClose} wide>
    <div style={{ border: "1px solid var(--line)", borderRadius: 12, padding: 14, marginBottom: 14, background: "var(--blue-l)" }}>
      <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 4, display: "flex", alignItems: "center", gap: 7 }}>🔄 Abonnement automatique <span style={{ fontSize: 11, fontWeight: 700, color: "#fff", background: "var(--green)", borderRadius: 20, padding: "2px 8px" }}>recommandé</span></div>
      <p style={{ fontSize: 12.5, lineHeight: 1.55, color: "var(--muted)", margin: "0 0 10px" }}>Un lien privé que <strong>Google Agenda relit tout seul</strong> (toutes les quelques heures). Vos événements MITMIT apparaissent dans Google Agenda — et dans <strong>Samsung Calendar</strong> via la synchronisation de votre compte Google. Lecture seule, sans ré-export.</p>
      {!token ? (
        <button className="btn btn-p btn-s" onClick={genToken}><Link2 size={14} /> Générer le lien d'abonnement</button>
      ) : (<>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}><input readOnly value={subUrl} onFocus={(e) => e.target.select()} style={{ flex: 1, minWidth: 220, fontSize: 12, fontFamily: "monospace", padding: "8px 10px", border: "1px solid var(--line)", borderRadius: 8, background: "#fff" }} /><button className="btn btn-p btn-s" onClick={copy}><Copy size={14} /> {copied ? "Copié !" : "Copier"}</button></div>
        <ol style={{ margin: "10px 0 0", paddingLeft: 18, fontSize: 12.5, lineHeight: 1.6, color: "var(--muted)" }}><li>Sur ordinateur, ouvrez <strong>calendar.google.com</strong>.</li><li>À gauche, « Autres agendas » → <strong>+</strong> → <strong>À partir d'une URL</strong>.</li><li>Collez le lien ci-dessus, puis <strong>Ajouter l'agenda</strong>. (Apparaîtra sur votre téléphone via votre compte Google.)</li></ol>
        <button className="btn btn-ghost btn-s" style={{ marginTop: 8, color: "var(--red)" }} onClick={revoke}><RefreshCw size={13} /> Régénérer le lien</button>
      </>)}
      <p style={{ fontSize: 11, color: "var(--muted)", marginTop: 10, marginBottom: 0 }}>⚙️ Prérequis serveur : Supabase configuré et la variable <code>SUPABASE_SERVICE_ROLE_KEY</code> définie sur Vercel. Si le lien renvoie une erreur de configuration, ajoutez cette variable (Project Settings → API → service_role).</p>
    </div>
    <div style={{ border: "1px solid var(--line)", borderRadius: 12, padding: 14 }}>
      <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 4 }}>📄 Export ponctuel (.ics)</div>
      <p style={{ fontSize: 12.5, color: "var(--muted)", margin: "0 0 4px" }}>Télécharge un fichier à importer manuellement. Inclus : <strong>{c.ev}</strong> événement{c.ev > 1 ? "s" : ""} · <strong>{c.act}</strong> action{c.act > 1 ? "s" : ""} de compte · <strong>{c.anniv}</strong> anniversaire{c.anniv > 1 ? "s" : ""}.</p>
      <div style={{ margin: "10px 0" }}><button className="btn btn-g btn-s" onClick={() => downloadICS(data)} disabled={c.total === 0}><Download size={14} /> Télécharger le fichier .ics</button></div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))", gap: 12 }}>
        <div><div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 4 }}>📅 Google Agenda</div><div style={{ fontSize: 12, lineHeight: 1.5, color: "var(--muted)" }}>Paramètres → Importer/Exporter → choisir le .ics → Importer.</div></div>
        <div><div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 4 }}>📱 Samsung Calendar</div><div style={{ fontSize: 12, lineHeight: 1.5, color: "var(--muted)" }}>Enregistrer le .ics → Calendrier → ☰ → Gérer les calendriers → Importer.</div></div>
      </div>
    </div>
  </Modal>);
}

// ============== AGENDA / CALENDRIER ==============
// ============== TEMPS DE PRÉSENCE / POINTAGE (gamifié) ==============
// Suivi quotidien des heures au local : arrivée, départ, pause méridienne.
// Base contractuelle 7 h/jour du lundi au vendredi ; décompte des heures supplémentaires.
const PRESENCE_TARGET = 420; // 7 h en minutes
const PRESENCE_LEVELS = ["Pointeur débutant", "Assidu", "Régulier", "Confirmé", "Chevronné", "Expert du temps", "Maître des horaires", "Légende du pointage"];
// Motifs de journée : « presence » = saisie des horaires (arrivée/départ/pause) ; les autres valent
// un forfait d'heures fixe (7 h = objectif, donc journée neutre) sans avoir à saisir d'horaires.
const PRESENCE_MOTIFS = {
  presence:    { label: "Présence au local",     hours: null,           color: "#3F60AA", emoji: "🏢" },
  cours:       { label: "Journée de cours",      hours: PRESENCE_TARGET, color: "#7c5cf0", emoji: "🎓" },
  teletravail: { label: "Télétravail",           hours: PRESENCE_TARGET, color: "#3F60AA", emoji: "🏠" },
  rdv:         { label: "Rendez-vous",            hours: null,           color: "#A855F7", emoji: "🤝" },
  conges:      { label: "Congés",                hours: PRESENCE_TARGET, color: "#2bb673", emoji: "🌴" },
  rtt:         { label: "RTT",                    hours: PRESENCE_TARGET, color: "#2bb673", emoji: "🗓️" },
  ferie:       { label: "Jour férié",            hours: PRESENCE_TARGET, color: "#F8B133", emoji: "🎉" },
  maladie:     { label: "Congé maladie",         hours: PRESENCE_TARGET, color: "#FF5A45", emoji: "🤒" },
  absence:     { label: "Absence non rémunérée", hours: 0,               color: "#9aa6bd", emoji: "➖" },
};
const MOTIF_ORDER = ["presence", "cours", "teletravail", "rdv", "conges", "rtt", "ferie", "maladie", "absence"];
// Motif « chrono » = saisie des horaires (arrivée/départ/pause) plutôt qu'un forfait d'heures.
// « Présence au local » et « Rendez-vous » se remplissent ainsi ; les autres valent un forfait.
const isChronoMotif = (m) => !!(PRESENCE_MOTIFS[m] && PRESENCE_MOTIFS[m].hours === null);
const pMin = (t) => { if (!t || !/^\d{1,2}:\d{2}$/.test(t)) return null; const [h, m] = t.split(":").map(Number); return h * 60 + m; };
const fmtDur = (min, opts = {}) => { const v = Math.round(min || 0); const sign = v < 0 ? "−" : (opts.plus && v > 0 ? "+" : ""); const a = Math.abs(v); const h = Math.floor(a / 60), m = a % 60; return sign + (m ? `${h} h ${String(m).padStart(2, "0")}` : `${h} h`); };
const isoLocal = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
const isWeekendDs = (ds) => { const wd = new Date(ds + "T00:00:00").getDay(); return wd === 0 || wd === 6; };
// Excédent d'une journée sur l'objectif contractuel, en minutes. Définition UNIQUE, partagée par
// l'écran RH et l'export : les deux la calculaient séparément et divergeaient. Un jour de week-end
// n'a pas d'objectif, tout ce qui y est travaillé est donc de l'heure supplémentaire ; un forfait
// (congés, cours, férié) vaut 7 h et ne produit rien, sauf si des heures ont été saisies au-dessus.
// ===== Détermination des heures supplémentaires par SEMAINE (règle RH, bulletin de juillet 2026) =====
// Le décompte ne se fait plus jour par jour (> 7 h) mais par semaine civile sur un seuil de 35 h :
// - comptent pour ATTEINDRE le seuil : les heures réellement travaillées (présence, rendez-vous,
//   samedi compris), les journées assimilées (cours, télétravail) et les CONGÉS (CP / RTT) — la RH
//   intègre désormais les heures non effectuées en congé dans la détermination des HS ;
// - les jours CHÔMÉS payés (férié, maladie) ne créent JAMAIS de majoration : les heures au-delà de
//   35 h qu'ils recouvrent sont dues en HEURES NORMALES (taux de base, en plus des 151,67 h) ;
// - au-delà de 35 h comptées (hors chômé) : 8 premières heures à +25 %, puis +50 %.
// Exemple vérifié (semaine du 13/07/2026) : CP 7 h + 27,5 h réelles = 34,5 h → aucune HS ; férié
// 7 h en plus → 41,5 h, soit 6,5 h payées en heures normales. C'est le bulletin de juillet 2026.
const MOTIFS_CHOMES = new Set(["ferie", "maladie"]);
const SAL_SEUIL_HEBDO = 35 * 60; // 35 h/semaine, en minutes
function semaineSalaireBreakdown(pointages, monthPrefix) {
  const byWeek = {};
  Object.entries(pointages || {}).filter(([ds]) => !monthPrefix || ds.startsWith(monthPrefix)).forEach(([ds, rec]) => {
    const st = presenceDay(rec); if (!st || st.invalid) return;
    const d = new Date(ds + "T00:00:00"); const mo = new Date(d); mo.setDate(d.getDate() - ((d.getDay() + 6) % 7));
    const k = isoLocal(mo);
    const w = byWeek[k] = byWeek[k] || { compte: 0, chome: 0 };
    if (MOTIFS_CHOMES.has(st.motif)) w.chome += st.worked; else w.compte += st.worked;
  });
  let m25 = 0, m50 = 0, mNorm = 0;
  Object.values(byWeek).forEach((w) => {
    const hs = Math.max(0, w.compte - SAL_SEUIL_HEBDO);
    m25 += Math.min(hs, SAL_SEUIL_50_MIN); m50 += Math.max(0, hs - SAL_SEUIL_50_MIN);
    mNorm += Math.max(0, w.compte + w.chome - SAL_SEUIL_HEBDO) - hs;
  });
  const rh = (m) => Math.round((m / 60) * 100) / 100;
  return { h25: rh(m25), h50: rh(m50), hNorm: rh(mNorm), m25, m50, mNorm };
}
// Décompte d'une journée à partir d'un enregistrement { arrivee, depart, pause, pauseMin }.
function presenceDay(rec) {
  if (!rec) return null;
  const motif = (rec.motif && PRESENCE_MOTIFS[rec.motif]) ? rec.motif : "presence";
  if (!isChronoMotif(motif)) {
    const forfait = PRESENCE_MOTIFS[motif].hours || 0;
    const worked = (rec.heures != null && rec.heures !== "") ? Math.max(0, Number(rec.heures) || 0) : forfait;
    return { worked, pause: false, motif, invalid: false };
  }
  if (!rec.arrivee || !rec.depart) return null;
  const a = pMin(rec.arrivee), d = pMin(rec.depart);
  if (a == null || d == null) return null;
  if (d <= a) return { worked: 0, invalid: true, arrivee: rec.arrivee, depart: rec.depart, pause: !!rec.pause, motif };
  const pause = rec.pause ? (Number(rec.pauseMin) || 0) : 0;
  const worked = Math.max(0, d - a - pause);
  return { worked, pause, arrivee: rec.arrivee, depart: rec.depart, invalid: false, motif };
}
// Sélecteur d'heure au pas de 5 min (2 menus heures/minutes) : le champ natif <input type="time">
// ignore step="300" sur plusieurs navigateurs et propose les minutes 1 par 1. Ici c'est garanti.
function TimeSelect({ value, onChange }) {
  const ok = /^\d{1,2}:\d{2}$/.test(value || "");
  const h = ok ? Number(value.split(":")[0]) : null;
  const m = ok ? Number(value.split(":")[1]) : null;
  const pad = (n) => String(n).padStart(2, "0");
  const mins = Array.from({ length: 12 }, (_, i) => i * 5);
  if (m != null && !mins.includes(m)) { mins.push(m); mins.sort((a, b) => a - b); }
  const set = (nh, nm) => onChange(pad(nh) + ":" + pad(nm));
  return (<div style={{ display: "flex", gap: 6, alignItems: "center" }}>
    <select style={{ flex: 1 }} value={h == null ? "" : String(h)} onChange={(e) => set(Number(e.target.value), m == null ? 0 : m)}>
      {h == null && <option value="">– h</option>}
      {Array.from({ length: 24 }, (_, i) => <option key={i} value={i}>{pad(i)} h</option>)}
    </select>
    <select style={{ flex: 1 }} value={m == null ? "" : String(m)} onChange={(e) => set(h == null ? 0 : h, Number(e.target.value))}>
      {m == null && <option value="">– min</option>}
      {mins.map((mm) => <option key={mm} value={mm}>{pad(mm)} min</option>)}
    </select>
  </div>);
}
// ===== Estimation du salaire (apprenti) =====
// Modèle calibré sur 3 bulletins de paie réels (avril/mai/juin 2026). L'apprenti est exonéré de
// cotisations salariales sur la part de rémunération ≤ 79 % du SMIC ; au-delà, ~12,5 % de cotisations
// s'appliquent. S'ajoute la mutuelle santé (montant fixe : 4005 € PMSS × 0,565 % = 22,63 €). La base
// mensuelle est de 151,67 h. Les indemnités kilométriques sont versées en prime (soumise au même calcul).
// Vérif : avril net 1513,85 / mai 1550,95 / juin 1678,88 — le modèle recolle à moins d'1 € près.
const SAL_BASE_HOURS = 151.67;      // heures mensuelles contractuelles (35 h/semaine)
const PRIME_KM_RATE = 0.5;          // la prime versée = 50 % des frais kilométriques réels
const SAL_COTIS_EXCESS = 0.125;     // taux moyen de cotisations salariales sur la part > 79 % du SMIC
const SAL_MUTUELLE = 22.63;         // mutuelle santé salariale (fixe)
const SAL_PART = 78;                // rémunération apprenti = 78 % du SMIC (base)
// Majoration légale des heures supplémentaires : les 8 premières heures sup. de la SEMAINE
// (36ᵉ→43ᵉ h) sont payées +25 %, au-delà (44ᵉ h et plus) +50 %. Le taux HS 25 % = taux de base × 1,25
// (vérifié : 9,6018 × 1,25 = 12,0023, exactement le taux du bulletin de juin).
const SAL_MAJ_25 = 1.25, SAL_MAJ_50 = 1.5, SAL_SEUIL_50_MIN = 480; // 8 h/semaine = 480 min à +25 % avant +50 %
// Régularisation des congés payés, calquée sur le bulletin de juillet 2026 : un jour de CP pris
// donne lieu à une RETENUE d'un 26e de la base mensuelle (bulletin : 1 456,31 / 26 = 56,0119 €/j,
// donc dérivable du taux horaire) et au versement d'une INDEMNITÉ de congés payés par jour, issue
// de la règle du dixième. Cette indemnité dépend de l'historique de rémunération : on retient la
// dernière valeur relevée sur le bulletin (176,28 € / 3 j = 58,76 €/j), réglable et mémorisable.
const SAL_CP_DIVISEUR = 26;        // jours ouvrables retenus par mois pour la retenue CP
const SAL_INDEM_CP_JOUR = 58.76;   // indemnité CP par jour (dixième), relevée sur le bulletin de juillet 2026
// Taux horaire de base retenu tant qu'aucun n'a été mémorisé dans l'onglet « Salaire estimé ».
// Constante partagée : l'écran retombait dessus, l'export retombait sur zéro, et l'export affichait
// donc une paie nulle tant que le bouton « Mémoriser mon taux horaire » n'avait jamais été utilisé.
const SAL_TAUX_DEFAUT = 9.6018;
function estimateSalaire({ tauxBase, h25, h50, hNorm = 0, prime, commission = 0, part = SAL_PART, mutuelle = SAL_MUTUELLE, joursCp = 0, indemCpJour = SAL_INDEM_CP_JOUR }) {
  const tb = Number(tauxBase) || 0;
  const base = tb * SAL_BASE_HOURS;
  const t25 = tb * SAL_MAJ_25, t50 = tb * SAL_MAJ_50;
  const hs25 = (Number(h25) || 0) * t25;
  const hs50 = (Number(h50) || 0) * t50;
  // Heures NORMALES au-delà des 151,67 h (semaine dépassant 35 h à cause d'un férié / arrêt chômé) :
  // payées au taux de base, sans majoration — cf. règle RH du bulletin de juillet 2026.
  const hsn = (Number(hNorm) || 0) * tb;
  const hs = hs25 + hs50 + hsn;
  const pr = Number(prime) || 0;
  // La commission commerciale n'entre PAS dans l'estimation : elle n'est ni acquise ni versée avec le
  // salaire du mois (elle dépend du règlement des factures). Elle reste renvoyée, pour être affichée
  // à titre indicatif, mais ne pèse ni sur le brut, ni sur les cotisations, ni sur le net.
  const comm = Number(commission) || 0;
  // Régularisation CP du mois : retenue d'un 26e de la base par jour pris, indemnité au dixième
  // (dernière valeur du bulletin) versée en face. L'écart entre les deux est en général minime.
  const jcp = Number(joursCp) || 0;
  const retenueCpJour = base / SAL_CP_DIVISEUR;
  const retenueCp = jcp * retenueCpJour;
  const indemCp = jcp * (Number(indemCpJour) || 0);
  const brut = base + hs + pr - retenueCp + indemCp;
  const seuil = part > 0 ? base * (79 / part) : base; // 79 % du SMIC (la base vaut « part » % du SMIC)
  const excess = Math.max(0, brut - seuil);
  const cotisVar = SAL_COTIS_EXCESS * excess;
  const mut = Number(mutuelle) || 0;
  const cotis = mut + cotisVar;
  return { base, t25, t50, hs25, hs50, hsn, hs, prime: pr, commission: comm, joursCp: jcp, retenueCpJour, retenueCp, indemCp, brut, seuil, excess, mutuelle: mut, cotisVar, cotis, net: brut - cotis };
}
// Commission commerciale par facture (partagée entre l'onglet Commissions et le salaire estimé) :
// 1re facture d'un établissement = référencement (taux1), suivantes = réassort (tauxN). Un indépendant
// est regroupé par compte, un groupe multi-PDV par site de livraison. Retourne la liste chronologique.
function computeCommissionRows(data) {
  const accounts = data.accounts || [];
  const accOf = (id) => accounts.find((a) => a.id === id);
  const s = data.settings || {};
  const r1 = (s.commTaux1 != null ? s.commTaux1 : 4) / 100;
  const rN = (s.commTauxN != null ? s.commTauxN : 2) / 100;
  const estabKey = (d) => isGroupe(accOf(d.accountId)) ? "site:" + (d.livraisonSiteId || d.siteId || d.accountId || "") : "acc:" + (d.accountId || d.livraisonSiteId || d.siteId || "");
  const factures = (data.deals || []).filter((d) => d.type === "Facture").slice()
    .sort((a, b) => (a.date || "").localeCompare(b.date || "") || (a.id || "").localeCompare(b.id || ""));
  const seen = new Set();
  return factures.map((d) => {
    const key = estabKey(d); const first = !seen.has(key); seen.add(key);
    const rate = first ? r1 : rN; const ca = d.montant || 0;
    return { d, first, rate, ca, comm: ca * rate };
  });
}
// Estimateur de salaire de fin de mois : taux horaire (base + heures sup.), heures sup. reprises du
// pointage, indemnités kilométriques du mois versées en prime. Tout reste ajustable manuellement.
function SalaireRH({ data, persist }) {
  const s = data.settings || {};
  const [tauxBase, setTauxBase] = useState(s.salaireTauxBase != null ? s.salaireTauxBase : SAL_TAUX_DEFAUT);
  const part = s.salairePart != null ? s.salairePart : SAL_PART;
  const mutuelle = s.salaireMutuelle != null ? s.salaireMutuelle : SAL_MUTUELLE;
  const monthPrefix = new Date().toISOString().slice(0, 7);
  const monthName = new Date().toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
  // Heures pointées ce mois, décomptées par SEMAINE CIVILE (seuil 35 h, congés comptés, jours chômés
  // en heures normales — voir semaineSalaireBreakdown) : HS +25 % / +50 % et heures normales au-delà
  // des 151,67 h.
  const autoOT = useMemo(() => semaineSalaireBreakdown(data.pointages, monthPrefix), [data.pointages, monthPrefix]);
  // Jours de congés payés pris ce mois (pointage) : déclenchent la retenue (base/26 par jour) et
  // l'indemnité CP au dixième (dernière valeur du bulletin, réglable ci-dessous).
  const autoCp = useMemo(() => Object.entries(data.pointages || {}).filter(([ds, r]) => ds.startsWith(monthPrefix) && r && r.motif === "conges").length, [data.pointages, monthPrefix]);
  // Frais kilométriques du mois (coût réel domicile-travail). La PRIME versée en paie correspond à
  // 50 % de ces frais (PRIME_KM_RATE).
  const coutJour = (Number(s.fraisEssence != null ? s.fraisEssence : 8) + Number(s.fraisPeage != null ? s.fraisPeage : 3.2)) * (s.fraisAR !== false ? 2 : 1);
  const presDays = useMemo(() => Object.entries(data.pointages || {}).filter(([ds, r]) => ds.startsWith(monthPrefix) && r && (!r.motif || r.motif === "presence") && r.arrivee && r.depart).length, [data.pointages, monthPrefix]);
  const fraisKmMois = Math.round(coutJour * presDays * 100) / 100;
  // Deux natures de frais de trajet : domicile-travail remboursé à 50 %, déplacements ponctuels à 100 %.
  const deplTotalMois = useMemo(() => (data.deplacements || []).filter((d) => (d.date || "").startsWith(monthPrefix)).reduce((s, d) => s + ((Number(d.essence) || 0) + (Number(d.peage) || 0) + (Number(d.autre) || 0)), 0), [data.deplacements, monthPrefix]);
  const domicilePrime = Math.round(fraisKmMois * PRIME_KM_RATE * 100) / 100;
  const autoKm = Math.round((domicilePrime + deplTotalMois) * 100) / 100;
  const [h25, setH25] = useState(autoOT.h25);
  const [h50, setH50] = useState(autoOT.h50);
  const [hNorm, setHNorm] = useState(autoOT.hNorm);
  const [joursCp, setJoursCp] = useState(autoCp);
  const [cpTouched, setCpTouched] = useState(false);
  const [indemCpJour, setIndemCpJour] = useState(s.salaireIndemCpJour != null ? s.salaireIndemCpJour : SAL_INDEM_CP_JOUR);
  const [prime, setPrime] = useState(autoKm);
  // Automatisation : tant que l'utilisateur n'a pas saisi de valeur manuelle, les heures sup. (réparties
  // 25/50 % par semaine), les heures normales au-delà de 151,67 h et la prime km suivent le pointage.
  const [otTouched, setOtTouched] = useState(false);
  const [kmTouched, setKmTouched] = useState(false);
  useEffect(() => { if (!otTouched) { setH25(autoOT.h25); setH50(autoOT.h50); setHNorm(autoOT.hNorm); } }, [autoOT.h25, autoOT.h50, autoOT.hNorm, otTouched]);
  useEffect(() => { if (!cpTouched) setJoursCp(autoCp); }, [autoCp, cpTouched]);
  useEffect(() => { if (!kmTouched) setPrime(autoKm); }, [autoKm, kmTouched]);
  // Commission commerciale du mois : factures facturées ce mois (1re facture d'un établissement à 4 %,
  // réassort à 2 %). Elle s'ajoute au brut et suit les mêmes taux paramétrés dans l'onglet Commissions.
  const commRows = useMemo(() => computeCommissionRows(data).filter((x) => (x.d.date || "").startsWith(monthPrefix)), [data.deals, data.accounts, data.settings, monthPrefix]);
  const autoComm = Math.round(commRows.reduce((a, x) => a + x.comm, 0) * 100) / 100;
  const [comm, setComm] = useState(autoComm);
  const [commTouched, setCommTouched] = useState(false);
  useEffect(() => { if (!commTouched) setComm(autoComm); }, [autoComm, commTouched]);
  const r = estimateSalaire({ tauxBase, h25, h50, hNorm, prime, commission: comm, part, mutuelle, joursCp, indemCpJour });
  const memoriser = () => persist((p) => ({ ...p, settings: { ...p.settings, salaireTauxBase: Number(tauxBase) || 0, salaireIndemCpJour: Number(indemCpJour) || SAL_INDEM_CP_JOUR } }));
  const Line = ({ l, v, strong, color, sub }) => (<div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", fontSize: strong ? 13.5 : 12.5, fontWeight: strong ? 800 : 500, color: color || "inherit", padding: "3px 0" }}><span>{l}{sub && <span style={{ color: "var(--muted)", fontWeight: 500 }}> {sub}</span>}</span><span className="tnum">{v}</span></div>);
  const totHS = (Number(h25) || 0) + (Number(h50) || 0);
  return (<div>
    <div className="card" style={{ marginBottom: 16, borderLeft: "4px solid var(--blue)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 14, flexWrap: "wrap" }}>
      <div>
        <div style={{ fontSize: 11.5, fontWeight: 800, color: "var(--muted)", textTransform: "uppercase", letterSpacing: .3 }}>Estimation du net à payer · <span style={{ textTransform: "capitalize" }}>{monthName}</span></div>
        <div style={{ fontSize: 12.5, color: "var(--muted)", marginTop: 3, lineHeight: 1.5 }}>Base {SAL_BASE_HOURS} h + {totHS} h sup. ({h25} h à +25 % · {h50} h à +50 %){(Number(hNorm) || 0) > 0 ? " + " + hNorm + " h normales (férié/chômé)" : ""} + prime (indemnités km) {eur2(prime)}, cotisations apprenti déduites.{(Number(comm) || 0) > 0 ? " Commission commerciale de " + eur2(comm) + " affichée à part, non comprise dans ce montant." : ""}</div>
      </div>
      <div className="pu-display tnum" style={{ fontSize: 34, color: "var(--blue)", fontWeight: 900 }}>{eur2(r.net)}</div>
    </div>
    <div className="grid" style={{ gridTemplateColumns: "1fr 1fr", alignItems: "start" }}>
      <div className="card"><div className="sec-h"><h3 className="pu-display">Paramètres de paie</h3></div>
        <div className="fld" style={{ marginBottom: 8 }}><label>Taux horaire de base (€ / h)</label><input type="number" step="0.0001" value={tauxBase} onChange={(e) => setTauxBase(e.target.value)} /></div>
        <div style={{ fontSize: 11.5, color: "var(--muted)", margin: "0 0 10px", lineHeight: 1.5, background: "var(--bg)", border: "1px solid var(--line)", borderRadius: 8, padding: "7px 9px" }}>Majoration heures sup. : <strong>+25 %</strong> = {eur2(r.t25)}/h (8 premières h/semaine) · <strong>+50 %</strong> = {eur2(r.t50)}/h (au-delà de 8 h/semaine).</div>
        <div className="row2" style={{ marginBottom: 8 }}>
          <div className="fld"><label>H. sup. à +25 % (h)</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="0.25" min="0" value={h25} onChange={(e) => { setOtTouched(true); setH25(e.target.value); }} /></div></div>
          <div className="fld"><label>H. sup. à +50 % (h)</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="0.25" min="0" value={h50} onChange={(e) => { setOtTouched(true); setH50(e.target.value); }} /></div></div>
        </div>
        <div className="fld" style={{ marginBottom: 8 }}><label>H. normales au-delà de 151,67 h (h)</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="0.25" min="0" value={hNorm} onChange={(e) => { setOtTouched(true); setHNorm(e.target.value); }} /></div><span style={{ fontSize: 11, color: "var(--muted)" }}>Heures d'une semaine dépassant 35 h uniquement grâce à un jour férié / arrêt chômé : payées au taux de base, sans majoration.</span></div>
        <div className="row2" style={{ marginBottom: 8 }}>
          <div className="fld"><label>Jours de CP pris ce mois</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="1" min="0" value={joursCp} onChange={(e) => { setCpTouched(true); setJoursCp(e.target.value); }} />{cpTouched && <button className="btn btn-g btn-s" onClick={() => setCpTouched(false)} title="Reprendre le nombre de jours de congés du pointage">↻ {autoCp}</button>}</div></div>
          <div className="fld"><label>Indemnité CP par jour (€)</label><input type="number" step="0.01" min="0" value={indemCpJour} onChange={(e) => setIndemCpJour(e.target.value)} /></div>
        </div>
        {(Number(joursCp) || 0) > 0 && <div style={{ fontSize: 11, color: "var(--muted)", margin: "-2px 0 8px", lineHeight: 1.5 }}>Chaque jour de CP : retenue de {eur2(r.retenueCpJour)} (base ÷ {SAL_CP_DIVISEUR}) et indemnité de {eur2(Number(indemCpJour) || 0)} (règle du dixième, dernière valeur du bulletin — « Mémoriser » l'enregistre).</div>}
        <div style={{ marginBottom: 8, fontSize: 11.5, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}><span style={{ color: otTouched ? "var(--muted)" : "var(--green)", fontWeight: 700 }}>{otTouched ? "Valeurs saisies manuellement" : "↻ Décompte hebdomadaire automatique du pointage (" + autoOT.h25 + " h à +25 % · " + autoOT.h50 + " h à +50 % · " + autoOT.hNorm + " h normales)"}</span>{otTouched && <button className="btn btn-g btn-s" onClick={() => setOtTouched(false)} title="Reprendre le décompte automatique du pointage">↻ Auto</button>}</div>
        <div className="fld"><label style={{ textTransform: "capitalize" }}>Prime — indemnités kilométriques · {monthName} (€)</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="0.01" min="0" value={prime} onChange={(e) => { setKmTouched(true); setPrime(e.target.value); }} />{kmTouched && <button className="btn btn-g btn-s" style={{ whiteSpace: "nowrap" }} onClick={() => setKmTouched(false)} title="Reprendre la prime (50 % des frais kilométriques du mois)">↻ {eur2(autoKm)}</button>}</div><span style={{ fontSize: 11, color: "var(--muted)" }}>Domicile-travail : 50 % de {eur2(fraisKmMois)} = {eur2(domicilePrime)}{deplTotalMois > 0 ? " · Déplacements ponctuels remboursés à 100 % = " + eur2(deplTotalMois) : ""}. Total prime : {eur2(autoKm)}.</span></div>
        <div className="fld" style={{ marginTop: 8 }}><label style={{ textTransform: "capitalize" }}>Commission commerciale · {monthName} (€)</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="0.01" min="0" value={comm} onChange={(e) => { setCommTouched(true); setComm(e.target.value); }} />{commTouched && <button className="btn btn-g btn-s" style={{ whiteSpace: "nowrap" }} onClick={() => setCommTouched(false)} title="Reprendre la commission calculée sur les factures du mois">↻ {eur2(autoComm)}</button>}</div><span style={{ fontSize: 11, color: "var(--muted)" }}>Calculée sur les factures du mois : 4 % sur la 1re facture d'un établissement (référencement), 2 % en réassort. {num(commRows.length)} facture{commRows.length > 1 ? "s" : ""} ce mois. <strong>Affichée pour information : elle n'entre pas dans le salaire estimé.</strong></span></div>
        <div style={{ marginTop: 10 }}><button className="btn btn-g btn-s" onClick={memoriser}><Save size={13} /> Mémoriser mon taux horaire</button></div>
        <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 10, lineHeight: 1.5 }}>Statut apprenti : rémunération à {part} % du SMIC, exonération de cotisations salariales jusqu'à 79 % du SMIC, mutuelle {eur2(mutuelle)}. Heures sup. déterminées par SEMAINE CIVILE (seuil 35 h, congés comptés pour l'atteindre ; férié / arrêt chômé payé en heures normales au-delà de 35 h) puis réparties 8 h à +25 % et au-delà à +50 %. Estimation calibrée sur vos bulletins (~1 € près).</div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <div className="card" style={{ borderTop: "3px solid var(--blue)" }}><div className="sec-h"><h3 className="pu-display">Détail du bulletin estimé</h3></div>
          <Line l="Salaire de base" sub={"(" + SAL_BASE_HOURS + " h × " + eur2(Number(tauxBase) || 0) + ")"} v={eur2(r.base)} />
          <Line l="Heures sup. +25 %" sub={"(" + h25 + " h × " + eur2(r.t25) + ")"} v={eur2(r.hs25)} color="var(--green)" />
          <Line l="Heures sup. +50 %" sub={"(" + h50 + " h × " + eur2(r.t50) + ")"} v={eur2(r.hs50)} color="var(--green)" />
          {(Number(hNorm) || 0) > 0 && <Line l="Heures normales > 151,67 h" sub={"(" + hNorm + " h × " + eur2(Number(tauxBase) || 0) + ", férié/chômé)"} v={eur2(r.hsn)} color="var(--green)" />}
          {r.joursCp > 0 && <Line l="Retenue congés payés" sub={"(" + r.joursCp + " j × " + eur2(r.retenueCpJour) + ")"} v={"− " + eur2(r.retenueCp)} color="var(--muted)" />}
          {r.joursCp > 0 && <Line l="Indemnité congés payés" sub={"(" + r.joursCp + " j × " + eur2(Number(indemCpJour) || 0) + ", dixième)"} v={eur2(r.indemCp)} color="var(--green)" />}
          {(!kmTouched && deplTotalMois > 0) ? <Line l="Prime domicile-travail (50 %)" v={eur2(domicilePrime)} color="var(--green)" /> : <Line l="Prime (indemnités km)" v={eur2(r.prime)} color="var(--green)" />}
          {(Number(comm) || 0) > 0 && <Line l="Commission commerciale" sub="(4 % référencement / 2 % réassort · hors estimation)" v={eur2(r.commission)} color="var(--muted)" />}
          <div style={{ borderTop: "1px solid var(--line)", margin: "6px 0" }} />
          <Line l="Salaire brut" v={eur2(r.brut)} strong />
          <Line l="Mutuelle santé" v={"− " + eur2(r.mutuelle)} color="var(--muted)" />
          <Line l="Cotisations salariales" sub={r.excess > 0 ? "(sur part > 79 % SMIC)" : ""} v={"− " + eur2(r.cotisVar)} color="var(--muted)" />
          {(!kmTouched && deplTotalMois > 0) && <Line l="Remboursement de frais professionnels – non soumis à cotisations" v={eur2(deplTotalMois)} color="var(--orange)" />}
        </div>
        <div className="card" style={{ borderTop: "3px solid var(--blue)" }}>
          <div className="calc-out" style={{ background: "#eef2fb" }}><span className="l">Net à payer estimé</span><span className="b pu-display tnum" style={{ color: "var(--blue)" }}>{eur2(r.net)}</span></div>
          <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 8, lineHeight: 1.5 }}>Avant impôt sur le revenu (prélèvement à la source à 0 % pour un apprenti sous le seuil), hors acomptes déjà versés et <strong>hors commission commerciale</strong>.</div>
        </div>
      </div>
    </div>
  </div>);
}
// Calculateur de commission commerciale : 4 % du CA HT sur la 1re facture d'un établissement
// (référencement / ouverture, « en cours de livraison ») et 2 % sur chaque facture suivante du
// même établissement (réassort). Le classement 1re vente / réassort est établi sur tout l'historique
// des factures ; le sélecteur de période ne filtre que ce qui est affiché et totalisé.
function CommissionsRH({ data, persist, go }) {
  const { accounts, sites } = data;
  const s = data.settings || {};
  const accOf = (id) => accounts.find((a) => a.id === id);
  const accName = (id) => accOf(id)?.enseigne || "—";
  const siteName = (id) => (sites || []).find((x) => x.id === id)?.label || null;
  const [taux1, setTaux1] = useState(s.commTaux1 != null ? s.commTaux1 : 4);
  const [tauxN, setTauxN] = useState(s.commTauxN != null ? s.commTauxN : 2);
  const [touched, setTouched] = useState(false);
  useEffect(() => { if (touched) return; if (s.commTaux1 != null) setTaux1(s.commTaux1); if (s.commTauxN != null) setTauxN(s.commTauxN); }, [s.commTaux1, s.commTauxN, touched]);
  const monthPrefix = new Date().toISOString().slice(0, 7);
  const [periode, setPeriode] = useState("all");
  // Identité de l'« établissement » d'une facture, pour distinguer 1re vente (référencement) et réassort.
  // Un indépendant = un seul établissement : on regroupe toujours par compte, car le site de livraison
  // n'est pas renseigné de façon homogène d'une facture à l'autre (sinon deux factures du même magasin
  // seraient comptées deux fois en référencement). Un groupe multi-PDV : chaque magasin (site de livraison)
  // est un établissement distinct, avec repli sur le compte si le site n'est pas précisé.
  // Libellé affiché : pour un groupe multi-PDV, le magasin (site) ; sinon l'enseigne du compte, à défaut
  // le site (cas d'un indépendant sans compte rattaché). accName renvoie « — » quand le compte manque, on
  // ne l'utilise donc que si le compte existe vraiment, pour éviter d'écraser un nom de site valable.
  const estabLabel = (d) => {
    const site = siteName(d.livraisonSiteId) || siteName(d.siteId);
    const a = accOf(d.accountId);
    if (isGroupe(a)) return site || (a && a.enseigne) || "—";
    return (a && a.enseigne) || site || "—";
  };
  // Toutes les factures, chronologiques : la 1re de chaque établissement = référencement (taux1), les
  // suivantes = réassort (tauxN). Les taux appliqués suivent les taux saisis (aperçu en direct).
  const rows = useMemo(() => computeCommissionRows({ ...data, settings: { ...data.settings, commTaux1: Number(taux1) || 0, commTauxN: Number(tauxN) || 0 } }), [data.deals, data.accounts, taux1, tauxN]);
  // Périodes disponibles (années présentes dans les factures) + « mois en cours » + « total ».
  const annees = useMemo(() => Array.from(new Set(rows.map((x) => (x.d.date || "").slice(0, 4)).filter(Boolean))).sort((a, b) => b.localeCompare(a)), [rows]);
  const inPeriode = (d) => { const dt = d.date || ""; if (periode === "all") return true; if (periode === "month") return dt.startsWith(monthPrefix); return dt.startsWith(periode); };
  const shown = rows.filter((x) => inPeriode(x.d));
  const tot = shown.reduce((a, x) => a + x.comm, 0);
  const totCA = shown.reduce((a, x) => a + x.ca, 0);
  const nFirst = shown.filter((x) => x.first).length; const nReassort = shown.length - nFirst;
  const commFirst = shown.filter((x) => x.first).reduce((a, x) => a + x.comm, 0);
  const commReassort = tot - commFirst;
  const memoriser = () => { setTouched(false); persist((p) => ({ ...p, settings: { ...p.settings, commTaux1: Number(taux1) || 0, commTauxN: Number(tauxN) || 0 } })); };
  const periodLabel = periode === "all" ? "toutes périodes" : periode === "month" ? new Date().toLocaleDateString("fr-FR", { month: "long", year: "numeric" }) : "année " + periode;
  const Tile = ({ l, v, sub, color }) => (<div className="card" style={{ padding: "12px 14px", borderTop: "3px solid " + (color || "var(--line)") }}><div style={{ fontSize: 11, fontWeight: 800, color: "var(--muted)", textTransform: "uppercase", letterSpacing: .3 }}>{l}</div><div className="tnum pu-display" style={{ fontSize: 24, fontWeight: 900, color: color || "inherit", marginTop: 2 }}>{v}</div>{sub && <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 2 }}>{sub}</div>}</div>);
  return (<div>
    <div className="card" style={{ marginBottom: 16, borderLeft: "4px solid var(--green)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 14, flexWrap: "wrap" }}>
      <div>
        <div style={{ fontSize: 11.5, fontWeight: 800, color: "var(--muted)", textTransform: "uppercase", letterSpacing: .3 }}>Commission commerciale · <span style={{ textTransform: "capitalize" }}>{periodLabel}</span></div>
        <div style={{ fontSize: 12.5, color: "var(--muted)", marginTop: 3, lineHeight: 1.5 }}>{num(taux1)} % sur la 1re facture de chaque établissement (référencement) · {num(tauxN)} % sur les factures de réassort. Calculé sur le CA HT.</div>
      </div>
      <div className="pu-display tnum" style={{ fontSize: 34, color: "var(--green)", fontWeight: 900 }}>{eur2(tot)}</div>
    </div>
    <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
      <span style={{ fontSize: 11.5, fontWeight: 700, color: "var(--muted)" }}>Période</span>
      <button className={cx("chip", periode === "all" && "on")} onClick={() => setPeriode("all")}>Total</button>
      <button className={cx("chip", periode === "month" && "on")} onClick={() => setPeriode("month")}>Mois en cours</button>
      {annees.map((y) => <button key={y} className={cx("chip", periode === y && "on")} onClick={() => setPeriode(y)}>{y}</button>)}
    </div>
    <div className="grid" style={{ gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 12, marginBottom: 16 }}>
      <Tile l="Commission totale" v={eur2(tot)} sub={num(shown.length) + " facture" + (shown.length > 1 ? "s" : "")} color="var(--green)" />
      <Tile l={"Référencement (" + num(taux1) + " %)"} v={eur2(commFirst)} sub={num(nFirst) + " 1re vente" + (nFirst > 1 ? "s" : "")} color="#2bb673" />
      <Tile l={"Réassort (" + num(tauxN) + " %)"} v={eur2(commReassort)} sub={num(nReassort) + " réassort" + (nReassort > 1 ? "s" : "")} color="#5b8def" />
      <Tile l="CA HT facturé" v={eur2(totCA)} sub="assiette de commission" />
    </div>
    <div className="grid" style={{ gridTemplateColumns: "1.1fr 1.9fr", alignItems: "start" }}>
      <div className="card"><div className="sec-h"><h3 className="pu-display">Taux de commission</h3></div>
        <div className="row2" style={{ marginBottom: 8 }}>
          <div className="fld"><label>1re facture — référencement (%)</label><input type="number" step="0.1" min="0" value={taux1} onChange={(e) => { setTouched(true); setTaux1(e.target.value); }} /></div>
          <div className="fld"><label>Factures suivantes — réassort (%)</label><input type="number" step="0.1" min="0" value={tauxN} onChange={(e) => { setTouched(true); setTauxN(e.target.value); }} /></div>
        </div>
        <div style={{ marginTop: 6 }}><button className="btn btn-g btn-s" onClick={memoriser}><Save size={13} /> Mémoriser les taux</button></div>
        <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 10, lineHeight: 1.5 }}>Un « établissement » est identifié par son site de livraison (à défaut le site de facturation, sinon le compte). La toute première facture d'un établissement rémunère l'ouverture / le référencement ; chaque facture ultérieure vers ce même établissement est traitée en réassort.</div>
      </div>
      <div className="card" style={{ borderTop: "3px solid var(--green)" }}><div className="sec-h"><h3 className="pu-display">Détail des factures · <span style={{ textTransform: "capitalize" }}>{periodLabel}</span></h3></div>
        {shown.length === 0 ? <div style={{ fontSize: 12.5, color: "var(--muted)", padding: "10px 2px" }}>Aucune facture sur cette période.</div> : (
          <div style={{ overflowX: "auto" }}><table className="tbl" style={{ width: "100%", fontSize: 12.5 }}>
            <thead><tr><th style={{ textAlign: "left" }}>Date</th><th style={{ textAlign: "left" }}>Établissement</th><th style={{ textAlign: "left" }}>Type</th><th style={{ textAlign: "right" }}>CA HT</th><th style={{ textAlign: "right" }}>Taux</th><th style={{ textAlign: "right" }}>Commission</th></tr></thead>
            <tbody>{shown.slice().sort((a, b) => (b.d.date || "").localeCompare(a.d.date || "")).map((x) => (
              <tr key={x.d.id}>
                <td>{x.d.date || "—"}</td>
                <td><span className="lnk" style={{ fontWeight: 600 }} onClick={() => go && go("deals", x.d.id)} title="Ouvrir le document">{estabLabel(x.d)}</span>{x.d.ref ? <span className="lnk" style={{ color: "var(--muted)" }} onClick={() => go && go("deals", x.d.id)} title="Ouvrir le document"> · {x.d.ref}</span> : null}</td>
                <td><span className="badge" style={{ background: (x.first ? "#2bb673" : "#5b8def") + "22", color: x.first ? "#2bb673" : "#5b8def", fontWeight: 700 }}>{x.first ? "Référencement" : "Réassort"}</span></td>
                <td style={{ textAlign: "right" }} className="tnum">{eur2(x.ca)}</td>
                <td style={{ textAlign: "right" }} className="tnum">{num(Math.round(x.rate * 1000) / 10)} %</td>
                <td style={{ textAlign: "right", fontWeight: 800 }} className="tnum">{eur2(x.comm)}</td>
              </tr>))}</tbody>
            <tfoot><tr style={{ borderTop: "2px solid var(--line)", fontWeight: 800 }}><td colSpan={3}>Total · {periodLabel}</td><td style={{ textAlign: "right" }} className="tnum">{eur2(totCA)}</td><td></td><td style={{ textAlign: "right", color: "var(--green)" }} className="tnum">{eur2(tot)}</td></tr></tfoot>
          </table></div>
        )}
      </div>
    </div>
  </div>);
}
// Export Excel des données RH en un seul classeur, une feuille par nature : heures pointées,
// trajets domicile-travail et déplacements ponctuels (frais professionnels), sous forme de tableaux
// Markdown à coller directement dans Notion (le tableau s'y convertit automatiquement).
function buildRHNotion(data, monthPrefix) {
  const jour = (ds) => new Date(ds + "T00:00:00").toLocaleDateString("fr-FR", { weekday: "short" });
  const dateFr = (ds) => new Date(ds + "T00:00:00").toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" });
  const hd = (min) => (min / 60).toFixed(2).replace(".", ",");
  const cell = (v) => String(v == null ? "" : v).replace(/\|/g, "/");
  // Période exportée : par défaut le mois affiché à l'écran, sinon tout l'historique. Sans ce filtre,
  // l'export couvrait plusieurs mois alors que les écrans RH en montrent un seul, et les totaux ne
  // pouvaient pas coïncider.
  const pgs = Object.entries(data.pointages || {}).filter(([ds]) => !monthPrefix || ds.startsWith(monthPrefix)).sort((a, b) => a[0].localeCompare(b[0]));
  const L = [];
  // Tableau 1 — Heures pointées
  L.push("### Heures pointées" + (monthPrefix ? (" — " + new Date(monthPrefix + "-01T00:00:00").toLocaleDateString("fr-FR", { month: "long", year: "numeric" })) : " — tout l'historique"));
  L.push("");
  // Détermination HEBDOMADAIRE des heures supplémentaires (règle RH du bulletin de juillet 2026,
  // cf. semaineSalaireBreakdown) : seuil de 35 h par semaine civile, congés comptés pour l'atteindre,
  // jours chômés (férié, maladie) payés en heures normales au-delà de 35 h. L'attribution au fil des
  // jours est chronologique : un jour porte les heures sup. qu'il fait franchir au cumul de la
  // semaine, réparties 8 h à +25 % puis +50 %.
  // AUCUN « salaire du jour » : le salaire normal est MENSUALISÉ (151,67 h × taux quel que soit le
  // nombre de jours ouvrés du mois). Additionner 7 h × taux par journée gonflait le salaire des mois
  // longs (161 h en juillet) : la valorisation se fait dans le récapitulatif mensualisé ci-dessous.
  const taux = Number((data.settings || {}).salaireTauxBase) || SAL_TAUX_DEFAUT;
  const lundiDe = (ds) => { const d = new Date(ds + "T00:00:00"); const mo = new Date(d); mo.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return isoLocal(mo); };
  const semaines = {};
  L.push("| Date | Jour | Type | Arrivée | Départ | Pause | Heures | Heures sup. | Heures sup. (€) |");
  L.push("| --- | --- | --- | --- | --- | --- | --- | --- | --- |");
  let totH = 0, totOT = 0, totSup = 0, totNorm = 0, tot25 = 0, tot50 = 0;
  pgs.forEach(([ds, rec]) => {
    const st = presenceDay(rec); if (!st || st.invalid) return;
    const mot = st.motif && st.motif !== "presence" ? PRESENCE_MOTIFS[st.motif] : null;
    const k = lundiDe(ds); const w = semaines[k] = semaines[k] || { cpt: 0, tot: 0, hs: 0 };
    // Heures sup. du jour = ce que ce jour fait franchir au cumul HEBDOMADAIRE compté (hors chômé).
    const chome = MOTIFS_CHOMES.has(st.motif);
    let ot = 0;
    if (!chome) { const avant = Math.max(0, w.cpt - SAL_SEUIL_HEBDO); w.cpt += st.worked; ot = Math.max(0, w.cpt - SAL_SEUIL_HEBDO) - avant; }
    // Heures normales au-delà de 35 h couvertes par un jour chômé : payées au taux de base.
    const normAvant = Math.max(0, w.tot - SAL_SEUIL_HEBDO) - Math.max(0, (w.cpt - (chome ? 0 : st.worked)) - SAL_SEUIL_HEBDO);
    w.tot += st.worked;
    const normApres = Math.max(0, w.tot - SAL_SEUIL_HEBDO) - Math.max(0, w.cpt - SAL_SEUIL_HEBDO);
    const norm = Math.max(0, normApres - normAvant);
    totNorm += norm;
    const min25 = Math.max(0, Math.min(ot, SAL_SEUIL_50_MIN - w.hs));
    const min50 = ot - min25; w.hs += ot;
    tot25 += min25; tot50 += min50;
    const sup = ((min25 / 60) * taux * SAL_MAJ_25) + ((min50 / 60) * taux * SAL_MAJ_50);
    totH += st.worked; totOT += ot; totSup += sup;
    L.push("| " + [dateFr(ds), jour(ds), cell(mot ? mot.label : "Présence"), mot ? "" : (st.arrivee || ""), mot ? "" : (st.depart || ""), mot ? "" : ((st.pause || 0) + " min"), hd(st.worked), hd(ot), eur2(sup)].join(" | ") + " |");
  });
  L.push("| **Total** |  |  |  |  |  | **" + hd(totH) + "** | **" + hd(totOT) + "** | **" + eur2(totSup) + "** |");
  L.push("");
  // Récapitulatif MENSUALISÉ, aligné sur la structure du bulletin : base 151,67 h quel que soit le
  // mois, régularisation des congés pris (retenue base/26 + indemnité au dixième), heures normales
  // au-delà (férié/chômé), puis heures supplémentaires majorées.
  const brutBase = SAL_BASE_HOURS * taux;
  const brutNorm = (totNorm / 60) * taux;
  const joursCp = pgs.filter(([, r]) => r && r.motif === "conges").length;
  const indemCpJour = Number((data.settings || {}).salaireIndemCpJour) || SAL_INDEM_CP_JOUR;
  const retenueCp = joursCp * (brutBase / SAL_CP_DIVISEUR);
  const indemCp = joursCp * indemCpJour;
  const brutEstime = brutBase + brutNorm + totSup - retenueCp + indemCp;
  L.push("#### Valorisation mensualisée (structure du bulletin)");
  L.push("");
  L.push("| Élément | Heures / jours | Montant brut |");
  L.push("| --- | --- | --- |");
  L.push("| Salaire de base mensualisé (lissé, indépendant du nombre de jours ouvrés) | " + String(SAL_BASE_HOURS).replace(".", ",") + " h | " + eur2(brutBase) + " |");
  if (joursCp > 0) L.push("| Retenue congés payés pris (base ÷ " + SAL_CP_DIVISEUR + " par jour) | − " + joursCp + " j | − " + eur2(retenueCp) + " |");
  if (joursCp > 0) L.push("| Indemnité congés payés (dixième, " + eur2(indemCpJour) + "/j relevé sur le dernier bulletin) | " + joursCp + " j | " + eur2(indemCp) + " |");
  if (totNorm > 0) L.push("| Heures normales au-delà de 151,67 h (semaine > 35 h par férié / arrêt chômé, taux de base) | " + hd(totNorm) + " h | " + eur2(brutNorm) + " |");
  L.push("| Heures supplémentaires à +25 % | " + hd(tot25) + " h | " + eur2((tot25 / 60) * taux * SAL_MAJ_25) + " |");
  L.push("| Heures supplémentaires à +50 % | " + hd(tot50) + " h | " + eur2((tot50 / 60) * taux * SAL_MAJ_50) + " |");
  L.push("| **Total (hors primes et transport)** | **" + hd(SAL_BASE_HOURS * 60 + totNorm + totOT) + " h** | **" + eur2(brutEstime) + "** |");
  L.push("");
  L.push("_Valorisation au taux horaire de base de " + eur2(taux) + ((data.settings || {}).salaireTauxBase != null ? " (réglage mémorisé dans l'onglet Salaire estimé)." : " (valeur par défaut : mémorisez votre taux dans l'onglet Salaire estimé pour l'ajuster).") + " Heures supplémentaires déterminées par SEMAINE CIVILE : seuil de 35 h, congés comptés pour l'atteindre ; les heures au-delà de 35 h couvertes par un jour férié ou un arrêt chômé sont payées en heures normales, sans majoration, en plus des 151,67 h mensuelles ; au-delà, +25 % pour les 8 premières heures de la semaine puis +50 %. L'indemnité de congés payés (règle du dixième) est reprise du dernier bulletin — ajustez-la dans l'onglet Salaire estimé quand un nouveau bulletin en donne une plus récente. Montants bruts, avant cotisations._");
  L.push("");
  // Tableau 2 — Trajet domicile-travail (un jour de présence pointé = un aller-retour)
  const s = data.settings || {};
  const ess = Number(s.fraisEssence != null ? s.fraisEssence : 8), pea = Number(s.fraisPeage != null ? s.fraisPeage : 3.2), ar = s.fraisAR !== false; const mult = ar ? 2 : 1; const coutJour = (ess + pea) * mult;
  const dom = pgs.filter(([, r]) => r && (!r.motif || r.motif === "presence") && r.arrivee && r.depart);
  L.push("### Trajet domicile-travail");
  L.push("");
  L.push("| Date | Jour | A/R | Coût du jour | Prime 50 % |");
  L.push("| --- | --- | --- | --- | --- |");
  dom.forEach(([ds]) => L.push("| " + [dateFr(ds), jour(ds), ar ? "A/R" : "Aller", eur2(coutJour), eur2(coutJour * PRIME_KM_RATE)].join(" | ") + " |"));
  L.push("| **Total** |  | **" + dom.length + " j** | **" + eur2(coutJour * dom.length) + "** | **" + eur2(coutJour * dom.length * PRIME_KM_RATE) + "** |");
  L.push("");
  // Tableau 3 — Déplacements ponctuels (frais professionnels remboursés à 100 %)
  const dep = (data.deplacements || []).slice().sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  L.push("### Déplacements ponctuels (frais professionnels — remboursés 100 %)");
  L.push("");
  L.push("| Date | Destination / motif | Km | Essence | Péage | Autres | Frais réels |");
  L.push("| --- | --- | --- | --- | --- | --- | --- |");
  let tt = 0;
  dep.forEach((d) => { const e = Number(d.essence) || 0, p = Number(d.peage) || 0, au = Number(d.autre) || 0; const t = e + p + au; tt += t; L.push("| " + [d.date || "", cell(d.dest), cell(d.km || ""), eur2(e), eur2(p), eur2(au), eur2(t)].join(" | ") + " |"); });
  L.push("| **Total** |  |  |  |  |  | **" + eur2(tt) + "** |");
  return L.join("\n");
}
// Onglet RH : sous-navigation entre le temps de présence (pointage), les frais kilométriques, le salaire et les commissions.
function RH({ data, persist, go }) {
  const [sub, setSub] = useState("presence");
  const [exportOpen, setExportOpen] = useState(false); const [copied, setCopied] = useState(false);
  // Période de l'export : le mois en cours par défaut, pour coïncider avec ce qu'affichent les écrans.
  const [expMois, setExpMois] = useState(() => isoLocal(new Date()).slice(0, 7));
  const moisDispo = useMemo(() => [...new Set(Object.keys(data.pointages || {}).map((ds) => ds.slice(0, 7)))].sort().reverse(), [data.pointages]);
  const subs = [{ id: "presence", label: "Temps de présence", icon: Clock }, { id: "frais", label: "Frais kilométriques", icon: Navigation }, { id: "salaire", label: "Salaire estimé", icon: Calculator }, { id: "commission", label: "Commissions", icon: Percent }];
  return (<div className="fade">
    <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap", alignItems: "center" }}>{subs.map((x) => { const Ic = x.icon; return <button key={x.id} className={cx("chip", sub === x.id && "on")} onClick={() => setSub(x.id)} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Ic size={14} />{x.label}</button>; })}<button className="btn btn-g btn-s" style={{ marginLeft: "auto" }} onClick={() => { setCopied(false); setExportOpen(true); }} title="Exporter (copier-coller Notion) : heures, trajets domicile-travail et déplacements ponctuels"><Copy size={14} /> Exporter (Notion)</button></div>
    <div style={{ display: sub === "presence" ? "block" : "none" }}><Pointage data={data} persist={persist} /></div>
    <div style={{ display: sub === "frais" ? "block" : "none" }}><FraisKm data={data} persist={persist} /></div>
    <div style={{ display: sub === "salaire" ? "block" : "none" }}><SalaireRH data={data} persist={persist} /></div>
    <div style={{ display: sub === "commission" ? "block" : "none" }}><CommissionsRH data={data} persist={persist} go={go} /></div>
    {exportOpen && (() => { const txt = buildRHNotion(data, expMois || null); const copy = async () => { try { await navigator.clipboard.writeText(txt); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch (e) { const ta = document.getElementById("rh-export-ta"); if (ta) { ta.focus(); ta.select(); try { document.execCommand("copy"); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch (e2) { } } } }; return (<Modal title="Exporter (copier-coller Notion)" onClose={() => setExportOpen(false)} wide>
      <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 10, lineHeight: 1.5 }}>Trois tableaux : heures pointées, trajets domicile-travail et déplacements ponctuels (frais professionnels). Cliquez sur <strong>Copier</strong>, puis collez dans Notion : chaque tableau s'y convertit automatiquement.</div>
      <div className="fld" style={{ marginBottom: 10, maxWidth: 340 }}><label>Période exportée</label><select value={expMois} onChange={(e) => setExpMois(e.target.value)}>{moisDispo.map((m) => <option key={m} value={m}>{new Date(m + "-01T00:00:00").toLocaleDateString("fr-FR", { month: "long", year: "numeric" })}</option>)}<option value="">Tout l'historique</option></select><span style={{ fontSize: 11, color: "var(--muted)" }}>Un mois donne exactement le même relevé que l'onglet « Temps de présence ».</span></div>
      <textarea id="rh-export-ta" readOnly value={txt} onFocus={(e) => e.target.select()} rows={Math.min(24, txt.split("\n").length + 1)} style={{ width: "100%", fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12, lineHeight: 1.5, whiteSpace: "pre", overflowX: "auto" }} />
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 12 }}><button className="btn btn-p" onClick={copy}>{copied ? <><CheckCircle2 size={15} /> Copié !</> : <><Copy size={15} /> Copier</>}</button></div>
    </Modal>); })()}
  </div>);
}
// Simulateur de frais kilométriques : trajet quotidien domicile-travail (essence + péage, aller-retour)
// ou déplacement ponctuel saisi librement. Les montants par défaut sont mémorisables dans les réglages.
function FraisKm({ data, persist }) {
  const s = data.settings || {};
  const [mode, setMode] = useState("domicile");
  const [essence, setEssence] = useState(s.fraisEssence != null ? s.fraisEssence : 8);
  const [peage, setPeage] = useState(s.fraisPeage != null ? s.fraisPeage : 3.2);
  const [ar, setAr] = useState(s.fraisAR !== false);
  // Ré-synchronise les montants avec les réglages mémorisés dès que ceux-ci arrivent (le chargement des
  // données peut se produire après le premier rendu). Tant que l'utilisateur n'a rien saisi (fraisTouched),
  // les champs suivent la valeur enregistrée — sinon l'affichage restait bloqué sur la valeur par défaut.
  const [fraisTouched, setFraisTouched] = useState(false);
  useEffect(() => {
    if (fraisTouched) return;
    if (s.fraisEssence != null) setEssence(s.fraisEssence);
    if (s.fraisPeage != null) setPeage(s.fraisPeage);
    setAr(s.fraisAR !== false);
  }, [s.fraisEssence, s.fraisPeage, s.fraisAR, fraisTouched]);
  // Jours de trajet = jours de présence au local pointés ce mois. Chaque jour au bureau incrémente
  // automatiquement le compteur (sauf si l'utilisateur a saisi un nombre à la main via joursTouched).
  const presDays = useMemo(() => { const pre = new Date().toISOString().slice(0, 7); return Object.entries(data.pointages || {}).filter(([ds, r]) => ds.startsWith(pre) && r && (!r.motif || r.motif === "presence") && r.arrivee && r.depart).length; }, [data.pointages]);
  const [jours, setJours] = useState(presDays);
  const [joursTouched, setJoursTouched] = useState(false);
  useEffect(() => { if (!joursTouched) setJours(presDays); }, [presDays, joursTouched]);
  const [pDate, setPDate] = useState(TODAY()); const [pDest, setPDest] = useState(""); const [pKm, setPKm] = useState(""); const [pEss, setPEss] = useState(0); const [pPea, setPPea] = useState(0); const [pAutre, setPAutre] = useState(0);
  const [editDeplId, setEditDeplId] = useState(null);
  const [fraisExportOpen, setFraisExportOpen] = useState(false); const [fraisCopied, setFraisCopied] = useState(false);
  const e = Number(essence) || 0, p = Number(peage) || 0, mult = ar ? 2 : 1;
  const coutJour = (e + p) * mult; const totalMois = coutJour * (Number(jours) || 0);
  const pTotal = (Number(pEss) || 0) + (Number(pPea) || 0) + (Number(pAutre) || 0);
  const memoriser = () => persist((pp) => ({ ...pp, settings: { ...pp.settings, fraisEssence: e, fraisPeage: p, fraisAR: ar } }));
  const monthName = new Date().toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
  // Déplacements ponctuels enregistrés (RDV, salons…) : liste persistée, cumulée par mois.
  const monthPref = new Date().toISOString().slice(0, 7);
  const deplAll = data.deplacements || [];
  const deplMois = deplAll.filter((d) => (d.date || "").startsWith(monthPref)).sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const deplTotalMois = deplMois.reduce((s, d) => s + ((Number(d.essence) || 0) + (Number(d.peage) || 0) + (Number(d.autre) || 0)), 0);
  const resetDeplForm = () => { setPDest(""); setPKm(""); setPEss(0); setPPea(0); setPAutre(0); setPDate(TODAY()); setEditDeplId(null); };
  const enregistrerDepl = () => {
    if (pTotal <= 0 && !pKm && !pDest.trim()) return;
    const champs = { date: pDate || TODAY(), dest: pDest.trim(), km: Number(pKm) || 0, essence: Number(pEss) || 0, peage: Number(pPea) || 0, autre: Number(pAutre) || 0 };
    if (editDeplId) persist((pp) => ({ ...pp, deplacements: (pp.deplacements || []).map((d) => d.id === editDeplId ? { ...d, ...champs } : d) }));
    else persist((pp) => ({ ...pp, deplacements: [{ id: "dp_" + Date.now(), ...champs }, ...(pp.deplacements || [])] }));
    resetDeplForm();
  };
  const modifierDepl = (d) => { setEditDeplId(d.id); setPDate(d.date || TODAY()); setPDest(d.dest || ""); setPKm(d.km || ""); setPEss(d.essence || 0); setPPea(d.peage || 0); setPAutre(d.autre || 0); };
  const supprimerDepl = (id) => persist((pp) => ({ ...pp, deplacements: (pp.deplacements || []).filter((d) => d.id !== id) }));
  // Export des frais professionnels (déplacements ponctuels remboursés à 100 %) en tableau Markdown
  // collable dans Notion — tout l'historique trié par date, format « note de frais ».
  const fraisProNotion = () => {
    const cell = (v) => String(v == null ? "" : v).replace(/\|/g, "/");
    const L = ["### Frais professionnels — déplacements ponctuels (remboursés 100 %)", "", "| Date | Destination / motif | Km | Essence | Péage | Autres | Frais réels |", "| --- | --- | --- | --- | --- | --- | --- |"];
    let tt = 0;
    deplAll.slice().sort((a, b) => (a.date || "").localeCompare(b.date || "")).forEach((d) => { const es = Number(d.essence) || 0, pe = Number(d.peage) || 0, au = Number(d.autre) || 0; const t = es + pe + au; tt += t; L.push("| " + [d.date || "", cell(d.dest), cell(d.km || ""), eur2(es), eur2(pe), eur2(au), eur2(t)].join(" | ") + " |"); });
    L.push("| **Total** |  |  |  |  |  | **" + eur2(tt) + "** |");
    return L.join("\n");
  };
  const fraisDomicile = coutJour * presDays;
  const grandFrais = fraisDomicile + deplTotalMois;
  // Domicile-travail : prime = 50 % des frais. Déplacements ponctuels : remboursés à 100 %.
  const grandPrime = fraisDomicile * PRIME_KM_RATE + deplTotalMois;
  return (<div>
    {/* Synthèse liée au pointage : chaque journée de présence pointée = 1 aller-retour domicile-travail. */}
    <div className="card" style={{ marginBottom: 16, borderLeft: "4px solid var(--green)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 14, flexWrap: "wrap" }}>
      <div>
        <div style={{ fontSize: 11.5, fontWeight: 800, color: "var(--muted)", textTransform: "uppercase", letterSpacing: .3 }}>Frais kilométriques · <span style={{ textTransform: "capitalize" }}>{monthName}</span></div>
        <div style={{ fontSize: 12.5, color: "var(--muted)", marginTop: 3, lineHeight: 1.5 }}>Domicile-travail : {presDays} journée(s) × {eur2(coutJour)}{ar ? " (A/R)" : ""} = <strong>{eur2(fraisDomicile)}</strong> <span style={{ color: "var(--blue)" }}>(prime 50 %)</span>{deplTotalMois > 0 ? <> · Déplacements ponctuels ({deplMois.length}) : <strong>{eur2(deplTotalMois)}</strong> <span style={{ color: "var(--blue)" }}>(remboursés 100 %)</span></> : null}.</div>
      </div>
      <div style={{ textAlign: "right" }}>
        <div style={{ fontSize: 10.5, fontWeight: 800, color: "var(--muted)", textTransform: "uppercase", letterSpacing: .3 }}>Frais</div>
        <div className="pu-display tnum" style={{ fontSize: 28, color: "var(--green)", fontWeight: 900, lineHeight: 1 }}>{eur2(grandFrais)}</div>
        <div style={{ fontSize: 12.5, color: "var(--blue)", fontWeight: 800, marginTop: 3 }}>Prime versée : {eur2(grandPrime)}</div>
      </div>
    </div>
    <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
      <button className={cx("chip", mode === "domicile" && "on")} onClick={() => setMode("domicile")} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Home size={14} /> Domicile ↔ Travail</button>
      <button className={cx("chip", mode === "ponctuel" && "on")} onClick={() => setMode("ponctuel")} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Navigation size={14} /> Déplacement ponctuel</button>
    </div>
    {mode === "domicile" ? (
      <div className="grid" style={{ gridTemplateColumns: "1fr 1fr", alignItems: "start" }}>
        <div className="card"><div className="sec-h"><h3 className="pu-display">Trajet quotidien domicile ↔ travail</h3></div>
          <div className="row2" style={{ marginBottom: 8 }}><div className="fld"><label>⛽ Essence (€ / trajet)</label><input type="number" step="0.01" value={essence} onChange={(ev) => { setFraisTouched(true); setEssence(ev.target.value); }} /></div><div className="fld"><label>🛣️ Péage (€ / trajet)</label><input type="number" step="0.01" value={peage} onChange={(ev) => { setFraisTouched(true); setPeage(ev.target.value); }} /></div></div>
          <div className="fld" style={{ marginBottom: 8 }}><label style={{ display: "inline-flex", alignItems: "center", gap: 8, cursor: "pointer", fontWeight: 600 }}><input type="checkbox" checked={ar} onChange={(ev) => { setFraisTouched(true); setAr(ev.target.checked); }} style={{ width: 16, height: 16, accentColor: "var(--blue)" }} /> Aller-retour (× 2)</label></div>
          <div className="fld"><label style={{ textTransform: "capitalize" }}>Nombre de jours de trajet · {monthName}</label><div style={{ display: "flex", gap: 6, alignItems: "center" }}><input type="number" step="1" min="0" value={jours} onChange={(ev) => { setJoursTouched(true); setJours(ev.target.value); }} /><button className={cx("btn", "btn-s", joursTouched ? "btn-g" : "btn-p")} style={{ whiteSpace: "nowrap" }} onClick={() => { setJoursTouched(false); setJours(presDays); }} title="Suivre automatiquement les jours de présence pointés ce mois">↻ {presDays} pointé(s)</button></div><span style={{ fontSize: 11, color: joursTouched ? "var(--muted)" : "var(--green)", fontWeight: 600 }}>{joursTouched ? "Nombre saisi manuellement" : "↻ Suit automatiquement les jours de présence pointés"}</span></div>
          <div style={{ marginTop: 10 }}><button className="btn btn-g btn-s" onClick={() => { memoriser(); setFraisTouched(false); }}><Save size={13} /> Mémoriser ces montants par défaut</button></div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <div className="card" style={{ borderTop: "3px solid var(--blue)" }}><div className="sec-h"><h3 className="pu-display">Coût par jour</h3></div>
            <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 10 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5 }}><span>Essence{ar ? " × 2" : ""}</span><span className="tnum">{eur2(e * mult)}</span></div>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5 }}><span>Péage{ar ? " × 2" : ""}</span><span className="tnum">{eur2(p * mult)}</span></div>
            </div>
            <div className="calc-out" style={{ background: "#eef2fb" }}><span className="l">Coût du trajet quotidien{ar ? " (aller-retour)" : ""}</span><span className="b pu-display tnum">{eur2(coutJour)}</span></div>
          </div>
          <div className="card" style={{ borderTop: "3px solid var(--green)" }}><div className="sec-h"><h3 className="pu-display" style={{ textTransform: "capitalize" }}>Total · {monthName}</h3></div>
            <div className="calc-out" style={{ background: "#e7f7ef" }}><span className="l">Frais réels · {Number(jours) || 0} jour(s) × {eur2(coutJour)}</span><span className="b pu-display tnum" style={{ color: "var(--green)" }}>{eur2(totalMois)}</span></div>
            <div className="calc-out" style={{ background: "#eef2fb", marginTop: 8 }}><span className="l">Prime versée (50 % des frais)</span><span className="b pu-display tnum" style={{ color: "var(--blue)" }}>{eur2(totalMois * PRIME_KM_RATE)}</span></div>
            <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 8, lineHeight: 1.5 }}>Frais de trajet domicile-travail sur le mois (jours de présence pointés). La prime effectivement versée en paie correspond à 50 % de ces frais.</div>
          </div>
        </div>
      </div>
    ) : (
      <><div className="grid" style={{ gridTemplateColumns: "1fr 1fr", alignItems: "start" }}>
        <div className="card"><div className="sec-h"><h3 className="pu-display">Déplacement ponctuel</h3></div>
          <div className="row2" style={{ marginBottom: 8 }}><div className="fld"><label>Date</label><input type="date" value={pDate} onChange={(ev) => setPDate(ev.target.value)} /></div><div className="fld"><label>Destination / motif (facultatif)</label><input value={pDest} onChange={(ev) => setPDest(ev.target.value)} placeholder="RDV client, salon…" /></div></div>
          <div className="row2" style={{ marginBottom: 8 }}><div className="fld"><label>Distance (km, facultatif)</label><input type="number" step="1" value={pKm} onChange={(ev) => setPKm(ev.target.value)} /></div><div className="fld"><label>⛽ Essence (€)</label><input type="number" step="0.01" value={pEss} onChange={(ev) => setPEss(ev.target.value)} /></div></div>
          <div className="row2"><div className="fld"><label>🛣️ Péage (€)</label><input type="number" step="0.01" value={pPea} onChange={(ev) => setPPea(ev.target.value)} /></div><div className="fld"><label>Autres frais (€)</label><input type="number" step="0.01" value={pAutre} onChange={(ev) => setPAutre(ev.target.value)} /></div></div>
          <div style={{ marginTop: 12, display: "flex", gap: 8, flexWrap: "wrap" }}><button className="btn btn-p" onClick={enregistrerDepl} disabled={pTotal <= 0 && !pKm && !pDest.trim()}><Save size={14} /> {editDeplId ? "Mettre à jour le déplacement" : "Enregistrer ce déplacement"}</button>{editDeplId && <button className="btn btn-g" onClick={resetDeplForm}><X size={14} /> Annuler</button>}</div>
        </div>
        <div className="card" style={{ borderTop: "3px solid var(--blue)" }}><div className="sec-h"><h3 className="pu-display">Total du déplacement</h3></div>
          <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 10 }}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5 }}><span>Essence</span><span className="tnum">{eur2(Number(pEss) || 0)}</span></div>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5 }}><span>Péage</span><span className="tnum">{eur2(Number(pPea) || 0)}</span></div>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5 }}><span>Autres frais</span><span className="tnum">{eur2(Number(pAutre) || 0)}</span></div>
          </div>
          <div className="calc-out" style={{ background: "#e7f7ef" }}><span className="l">Frais réels{pDest ? " · " + pDest : ""}{pKm ? " · " + pKm + " km" : ""}</span><span className="b pu-display tnum" style={{ color: "var(--green)" }}>{eur2(pTotal)}</span></div>
          <div className="calc-out" style={{ background: "#eef2fb", marginTop: 8 }}><span className="l">Remboursé (100 % des frais)</span><span className="b pu-display tnum" style={{ color: "var(--blue)" }}>{eur2(pTotal)}</span></div>
        </div>
      </div>
      <div className="card" style={{ marginTop: 14 }}><div className="sec-h"><h3 className="pu-display" style={{ textTransform: "capitalize" }}>Déplacements enregistrés · {monthName}</h3><div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>{deplTotalMois > 0 && <span style={{ fontSize: 12.5, fontWeight: 800 }}><span style={{ color: "var(--green)" }}>{eur2(deplTotalMois)}</span> · remboursé <span style={{ color: "var(--blue)" }}>{eur2(deplTotalMois)}</span></span>}<button className="btn btn-g btn-s" onClick={() => { setFraisCopied(false); setFraisExportOpen(true); }} disabled={deplAll.length === 0} title="Exporter tous les frais professionnels (copier-coller Notion)"><Copy size={14} /> Exporter (Notion)</button></div></div>
        {deplMois.length === 0 ? <div className="empty">Aucun déplacement ponctuel enregistré ce mois. Renseignez-en un ci-dessus puis « Enregistrer ».</div> : <div style={{ overflowX: "auto" }}><table className="tbl"><thead><tr><th>Date</th><th>Destination / motif</th><th style={{ textAlign: "right" }}>Km</th><th style={{ textAlign: "right" }}>⛽ Essence</th><th style={{ textAlign: "right" }}>🛣️ Péage</th><th style={{ textAlign: "right" }}>Autres</th><th style={{ textAlign: "right" }}>Frais réels</th><th style={{ textAlign: "right" }}>Remboursé (100 %)</th><th></th></tr></thead><tbody>{deplMois.map((d) => { const ess = Number(d.essence) || 0, pea = Number(d.peage) || 0, aut = Number(d.autre) || 0; const t = ess + pea + aut; return (<tr key={d.id}><td className="tnum">{d.date}</td><td>{d.dest || "—"}</td><td style={{ textAlign: "right" }} className="tnum">{d.km ? d.km : "—"}</td><td style={{ textAlign: "right" }} className="tnum">{ess ? eur2(ess) : "—"}</td><td style={{ textAlign: "right" }} className="tnum">{pea ? eur2(pea) : "—"}</td><td style={{ textAlign: "right" }} className="tnum">{aut ? eur2(aut) : "—"}</td><td style={{ textAlign: "right", fontWeight: 700, color: "var(--green)" }} className="tnum">{eur2(t)}</td><td style={{ textAlign: "right", color: "var(--blue)", fontWeight: 700 }} className="tnum">{eur2(t)}</td><td style={{ textAlign: "right", whiteSpace: "nowrap" }}><button className="iconbtn" title="Modifier" onClick={() => modifierDepl(d)}><Pencil size={14} /></button> <button className="iconbtn" title="Supprimer" onClick={() => supprimerDepl(d.id)}><Trash2 size={14} /></button></td></tr>); })}{deplMois.length > 1 && (() => { const tE = deplMois.reduce((s, d) => s + (Number(d.essence) || 0), 0), tP = deplMois.reduce((s, d) => s + (Number(d.peage) || 0), 0), tA = deplMois.reduce((s, d) => s + (Number(d.autre) || 0), 0); return (<tr style={{ borderTop: "2px solid var(--line)", fontWeight: 800 }}><td>Total</td><td></td><td></td><td style={{ textAlign: "right" }} className="tnum">{eur2(tE)}</td><td style={{ textAlign: "right" }} className="tnum">{eur2(tP)}</td><td style={{ textAlign: "right" }} className="tnum">{eur2(tA)}</td><td style={{ textAlign: "right", color: "var(--green)" }} className="tnum">{eur2(deplTotalMois)}</td><td style={{ textAlign: "right", color: "var(--blue)" }} className="tnum">{eur2(deplTotalMois)}</td><td></td></tr>); })()}</tbody></table></div>}
      </div></>
    )}
    {fraisExportOpen && (() => { const txt = fraisProNotion(); const copy = async () => { try { await navigator.clipboard.writeText(txt); setFraisCopied(true); setTimeout(() => setFraisCopied(false), 1600); } catch (e) { const ta = document.getElementById("frais-export-ta"); if (ta) { ta.focus(); ta.select(); try { document.execCommand("copy"); setFraisCopied(true); setTimeout(() => setFraisCopied(false), 1600); } catch (e2) { } } } }; return (<Modal title="Exporter les frais professionnels (Notion)" onClose={() => setFraisExportOpen(false)} wide>
      <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 10, lineHeight: 1.5 }}>Tous les déplacements ponctuels enregistrés (frais professionnels remboursés à 100 %). Cliquez sur <strong>Copier</strong>, puis collez dans Notion : le tableau s'y convertit automatiquement.</div>
      <textarea id="frais-export-ta" readOnly value={txt} onFocus={(e) => e.target.select()} rows={Math.min(22, txt.split("\n").length + 1)} style={{ width: "100%", fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12, lineHeight: 1.5, whiteSpace: "pre", overflowX: "auto" }} />
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 12 }}><button className="btn btn-p" onClick={copy}>{fraisCopied ? <><CheckCircle2 size={15} /> Copié !</> : <><Copy size={15} /> Copier</>}</button></div>
    </Modal>); })()}
  </div>);
}
function PointageEditor({ ds, rec, onSave, onDelete, onClose }) {
  const [motif, setMotif] = useState((rec && rec.motif && PRESENCE_MOTIFS[rec.motif]) ? rec.motif : "presence");
  const [arrivee, setArrivee] = useState((rec && rec.arrivee) || "10:00");
  const [depart, setDepart] = useState((rec && rec.depart) || "17:30");
  const [pause, setPause] = useState(rec ? rec.pause !== false : true);
  const [pauseMin, setPauseMin] = useState((rec && rec.pauseMin != null) ? rec.pauseMin : 30);
  const [heures, setHeures] = useState((rec && rec.heures != null) ? rec.heures : (PRESENCE_MOTIFS[(rec && rec.motif && PRESENCE_MOTIFS[rec.motif]) ? rec.motif : "presence"].hours || 0));
  const we = isWeekendDs(ds);
  const isChrono = isChronoMotif(motif);
  const st = presenceDay(isChrono ? { motif, arrivee, depart, pause, pauseMin } : { motif, heures });
  const target = we ? 0 : PRESENCE_TARGET;
  const over = st && !st.invalid ? st.worked - target : null;
  const dLabel = new Date(ds + "T00:00:00").toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  const col = over == null ? "var(--muted)" : over >= 0 ? "var(--green)" : "var(--amber)";
  const save = () => onSave(isChrono ? { motif, arrivee, depart, pause, pauseMin: pause ? (Number(pauseMin) || 0) : 0 } : { motif, heures });
  return (<Modal title={"Pointage — " + dLabel} onClose={onClose}>
    <div className="fld"><label>Type de journée</label>
      <select value={motif} onChange={(e) => { const k = e.target.value; setMotif(k); if (!isChronoMotif(k)) setHeures(PRESENCE_MOTIFS[k].hours || 0); }}>{MOTIF_ORDER.map((k) => { const m = PRESENCE_MOTIFS[k]; return <option key={k} value={k}>{m.emoji + " " + m.label}</option>; })}</select>
    </div>
    {isChrono ? (<>
      <div className="row2">
        <div className="fld"><label>Heure d'arrivée</label><TimeSelect value={arrivee} onChange={setArrivee} /></div>
        <div className="fld"><label>Heure de départ</label><TimeSelect value={depart} onChange={setDepart} /></div>
      </div>
      <div className="fld" style={{ marginTop: 2, marginBottom: pause ? 8 : 0 }}>
        <label style={{ display: "inline-flex", alignItems: "center", gap: 8, cursor: "pointer", fontWeight: 600 }}>
          <input type="checkbox" checked={pause} onChange={(e) => setPause(e.target.checked)} style={{ width: 16, height: 16, accentColor: "var(--blue)" }} />
          <Coffee size={15} /> J'ai pris une pause méridienne
        </label>
      </div>
      {pause && <div className="fld"><label>Durée de la pause (minutes)</label><input type="number" min="0" step="5" value={pauseMin} onChange={(e) => setPauseMin(Math.max(0, +e.target.value))} /></div>}
    </>) : (
      <div className="fld">
        <label>Heures comptées ce jour</label>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
          <button type="button" className={cx("btn", "btn-s", heures === PRESENCE_TARGET ? "btn-p" : "btn-g")} onClick={() => setHeures(PRESENCE_TARGET)}>Journée ({fmtDur(PRESENCE_TARGET)})</button>
          <button type="button" className={cx("btn", "btn-s", heures === Math.round(PRESENCE_TARGET / 2) ? "btn-p" : "btn-g")} onClick={() => setHeures(Math.round(PRESENCE_TARGET / 2))}>Demi-journée</button>
          <button type="button" className={cx("btn", "btn-s", heures === 0 ? "btn-p" : "btn-g")} onClick={() => setHeures(0)}>Aucune (0 h)</button>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input type="number" min="0" max="12" step="0.25" value={+(heures / 60).toFixed(2)} onChange={(e) => setHeures(Math.max(0, Math.round((+e.target.value || 0) * 60)))} style={{ maxWidth: 130 }} />
          <span style={{ color: "var(--muted)", fontSize: 12.5 }}>heures</span>
        </div>
        <div style={{ fontSize: 11.5, color: "var(--muted)", marginTop: 6, lineHeight: 1.5 }}>Journée « {PRESENCE_MOTIFS[motif].label} » comptée pour {fmtDur(heures)}. Ajustez pour un rendez-vous plus court, une demi-journée d'absence ou de congé, etc.</div>
      </div>
    )}
    <div className="calc-out" style={{ marginTop: 10, background: (over == null ? "#9aa6bd" : over >= 0 ? "#2bb673" : "#F8B133") + "18" }}>
      <span className="l">Temps compté{we ? " (week-end)" : " · objectif " + fmtDur(target)}</span>
      <span className="b pu-display tnum" style={{ color: col }}>{st && !st.invalid ? fmtDur(st.worked) : "—"}{over != null && over !== 0 ? "  (" + fmtDur(over, { plus: true }) + ")" : ""}</span>
    </div>
    {st && st.invalid && <div style={{ color: "var(--red)", fontSize: 12, marginTop: 8 }}>L'heure de départ doit être postérieure à l'heure d'arrivée.</div>}
    <div style={{ display: "flex", justifyContent: "space-between", marginTop: 14, gap: 8 }}>
      <button className="btn btn-d btn-s" onClick={onDelete} disabled={!rec}><Trash2 size={14} /> Effacer</button>
      <button className="btn btn-p" onClick={save} disabled={!st || st.invalid}><CheckCircle2 size={15} /> Enregistrer</button>
    </div>
  </Modal>);
}
function Pointage({ data, persist }) {
  const pointages = data.pointages || {};
  const [cursor, setCursor] = useState(() => { const d = new Date(); return { y: d.getFullYear(), m: d.getMonth() }; });
  const [editDs, setEditDs] = useState(null);
  const [exportOpen, setExportOpen] = useState(false); const [copied, setCopied] = useState(false);
  const todayStr = isoLocal(new Date());
  // Coût d'un aller-retour domicile-travail (mêmes réglages que l'outil Frais kilométriques).
  const _s = data.settings || {}; const coutJour = (Number(_s.fraisEssence != null ? _s.fraisEssence : 8) + Number(_s.fraisPeage != null ? _s.fraisPeage : 3.2)) * (_s.fraisAR !== false ? 2 : 1);
  const save = (ds, rec) => persist((p) => ({ ...p, pointages: { ...(p.pointages || {}), [ds]: rec } }));
  const remove = (ds) => persist((p) => { const np = { ...(p.pointages || {}) }; delete np[ds]; return { ...p, pointages: np }; });
  const targetOf = (ds) => isWeekendDs(ds) ? 0 : PRESENCE_TARGET;

  // ---- Statistiques du MOIS AFFICHÉ pour la gamification ----
  // Les compteurs (jours pointés, série, heures sup.), le niveau, l'XP et les badges suivent le mois
  // sélectionné dans le calendrier : passer à un autre mois remet les compteurs de ce mois-là.
  const allEntries = useMemo(() => Object.entries(pointages).map(([ds, rec]) => ({ ds, rec, st: presenceDay(rec) })).filter((x) => x.st && !x.st.invalid), [pointages]);
  const gamePrefix = `${cursor.y}-${String(cursor.m + 1).padStart(2, "0")}`;
  const gameEntries = useMemo(() => allEntries.filter((x) => x.ds.startsWith(gamePrefix)), [allEntries, gamePrefix]);
  const daysLogged = gameEntries.length;
  // Heures sup. du mois : même règle que la paie (détermination hebdomadaire, seuil 35 h).
  const mSalaire = useMemo(() => semaineSalaireBreakdown(pointages, gamePrefix), [pointages, gamePrefix]);
  const supMois = mSalaire.m25 + mSalaire.m50;
  const xp = daysLogged * 12 + Math.round(supMois / 60) * 8;
  const level = Math.min(PRESENCE_LEVELS.length, Math.floor(xp / 100) + 1);
  const levelName = PRESENCE_LEVELS[level - 1];
  const xpInLevel = level >= PRESENCE_LEVELS.length ? 100 : xp % 100;

  // Série du mois affiché : la plus longue suite de jours OUVRÉS pointés consécutifs dans le mois
  // (le week-end ne casse pas la série). Une série ancrée sur « aujourd'hui » n'aurait aucun sens
  // en consultant un autre mois.
  const streak = useMemo(() => {
    const ok = (ds) => { const s = presenceDay(pointages[ds]); return s && !s.invalid && s.worked > 0; };
    const last = new Date(cursor.y, cursor.m + 1, 0).getDate();
    let best = 0, cur = 0;
    for (let day = 1; day <= last; day++) {
      const d = new Date(cursor.y, cursor.m, day);
      const wd = d.getDay(); if (wd === 0 || wd === 6) continue;
      if (ok(isoLocal(d))) { cur++; if (cur > best) best = cur; } else cur = 0;
    }
    return best;
  }, [pointages, cursor.y, cursor.m]);

  const badges = useMemo(() => {
    // On ne considère que les journées avec un vrai horaire d'arrivée : pMin renvoie null pour les motifs
    // au forfait (congés, férié…) et « null <= 510 » vaut true en JS — sinon le badge était attribué à tort.
    const anyEarly = gameEntries.some((x) => { const m = pMin(x.st.arrivee); return m != null && m <= 8 * 60 + 30; });
    const anyLate = gameEntries.some((x) => { const m = pMin(x.st.depart); return m != null && m >= 20 * 60; });
    const anyMarathon = gameEntries.some((x) => x.st.worked >= 9 * 60);
    const byWeek = {};
    gameEntries.forEach((x) => { if (isWeekendDs(x.ds)) return; const d = new Date(x.ds + "T00:00:00"); const mon = new Date(d); mon.setDate(d.getDate() - ((d.getDay() + 6) % 7)); const key = isoLocal(mon); (byWeek[key] = byWeek[key] || new Set()).add(x.ds); });
    const perfectWeek = Object.values(byWeek).some((set) => set.size >= 5);
    return [
      { id: "first", label: "Premier pointage", icon: CheckCircle2, color: "#3F60AA", got: daysLogged >= 1, desc: "Enregistrer une première journée ce mois." },
      { id: "streak5", label: "Assiduité", icon: Flame, color: "#FF5A45", got: streak >= 5, desc: "5 jours ouvrés d'affilée ce mois." },
      { id: "perfect", label: "Semaine parfaite", icon: Award, color: "#7c5cf0", got: perfectWeek, desc: "Une semaine complète (lun-ven) pointée ce mois." },
      { id: "early", label: "Lève-tôt", icon: Sun, color: "#F8B133", got: anyEarly, desc: "Arriver à 8 h 30 ou avant ce mois." },
      { id: "late", label: "Couche-tard", icon: Moon, color: "#5b54c9", got: anyLate, desc: "Partir à 20 h ou après ce mois." },
      { id: "marathon", label: "Marathonien", icon: Zap, color: "#2bb673", got: anyMarathon, desc: "Une journée de 9 h ou plus ce mois." },
      { id: "sup10", label: "+10 h sup.", icon: Trophy, color: "#F8B133", got: supMois >= 600, desc: "Cumuler 10 h supplémentaires ce mois." },
    ];
  }, [gameEntries, streak, daysLogged, supMois]);
  const gotBadges = badges.filter((b) => b.got).length;

  // ---- Calendrier du mois affiché ----
  const monthName = new Date(cursor.y, cursor.m, 1).toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
  const first = new Date(cursor.y, cursor.m, 1);
  const offset = (first.getDay() + 6) % 7; // lundi = 0
  const daysInMonth = new Date(cursor.y, cursor.m + 1, 0).getDate();
  const daysPrev = new Date(cursor.y, cursor.m, 0).getDate();
  const cells = [];
  for (let i = 0; i < offset; i++) cells.push({ day: daysPrev - offset + 1 + i, out: true, y: cursor.m === 0 ? cursor.y - 1 : cursor.y, m: cursor.m === 0 ? 11 : cursor.m - 1 });
  for (let i = 1; i <= daysInMonth; i++) cells.push({ day: i, out: false, y: cursor.y, m: cursor.m });
  while (cells.length % 7 !== 0 || cells.length < 42) { const next = cells.length - offset - daysInMonth + 1; cells.push({ day: next, out: true, y: cursor.m === 11 ? cursor.y + 1 : cursor.y, m: cursor.m === 11 ? 0 : cursor.m + 1 }); if (cells.length >= 42) break; }
  const fmtDate = (y, m, d) => `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;

  // ---- Décompte du mois affiché ----
  const monthPrefix = gamePrefix;
  const monthEntries = gameEntries;
  const mWorked = monthEntries.reduce((s, x) => s + x.st.worked, 0);
  const mTarget = monthEntries.reduce((s, x) => s + targetOf(x.ds), 0);
  // Heures sup. du mois selon la règle de paie (détermination hebdomadaire, seuil 35 h), déjà
  // calculées pour le bandeau gamifié (mSalaire / supMois).
  const mSup = supMois;
  const mDef = monthEntries.reduce((s, x) => s + Math.max(0, targetOf(x.ds) - x.st.worked), 0);
  const mBalance = mWorked - mTarget;
  const mDays = monthEntries.length;
  const weeks = useMemo(() => {
    const map = {};
    monthEntries.forEach((x) => { const d = new Date(x.ds + "T00:00:00"); const mon = new Date(d); mon.setDate(d.getDate() - ((d.getDay() + 6) % 7)); const key = isoLocal(mon); const w = map[key] || (map[key] = { start: key, worked: 0, target: 0, days: 0 }); w.worked += x.st.worked; w.target += targetOf(x.ds); w.days++; });
    return Object.values(map).sort((a, b) => a.start.localeCompare(b.start));
  }, [monthEntries]);

  // Export « jour après jour » (tableau Markdown collable dans Notion) : heures et trajet domicile-travail.
  const buildExport = () => {
    const rows = Object.keys(pointages).filter((ds) => ds.startsWith(monthPrefix)).sort();
    const hd = (min) => (min / 60).toFixed(2).replace(".", ",");
    const L = [];
    L.push("### Temps de présence & trajets — " + monthName);
    L.push("");
    L.push("| Date | Jour | Type | Arrivée | Départ | Pause | Heures | Heures sup. | Trajet A/R | Frais |");
    L.push("| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |");
    let totMin = 0, totSup = 0, totFrais = 0, totAR = 0;
    // Même règle hebdomadaire que la paie (cf. semaineSalaireBreakdown) : un jour porte les heures
    // sup. qu'il fait franchir au cumul de la semaine (seuil 35 h, congés comptés, chômé exclu).
    const semX = {};
    rows.forEach((ds) => {
      const st = presenceDay(pointages[ds]); if (!st || st.invalid) return;
      const d = new Date(ds + "T00:00:00");
      const jour = d.toLocaleDateString("fr-FR", { weekday: "short" });
      const dateFr = d.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" });
      const mot = st.motif && st.motif !== "presence" ? PRESENCE_MOTIFS[st.motif] : null;
      const ar = !mot;
      const frais = ar ? coutJour : 0;
      const mo = new Date(d); mo.setDate(d.getDate() - ((d.getDay() + 6) % 7)); const k = isoLocal(mo);
      const w = semX[k] = semX[k] || { cpt: 0 };
      let sup = 0;
      if (!MOTIFS_CHOMES.has(st.motif)) { const avant = Math.max(0, w.cpt - SAL_SEUIL_HEBDO); w.cpt += st.worked; sup = Math.max(0, w.cpt - SAL_SEUIL_HEBDO) - avant; }
      totMin += st.worked; totSup += sup; if (ar) { totFrais += frais; totAR++; }
      L.push("| " + [dateFr, jour, mot ? mot.label : "Présence", mot ? "" : st.arrivee, mot ? "" : st.depart, mot ? "" : ((st.pause || 0) + " min"), hd(st.worked), hd(sup), ar ? "A/R" : "—", ar ? eur2(frais) : "—"].join(" | ") + " |");
    });
    L.push("| **Total** |  |  |  |  |  | **" + hd(totMin) + "** | **" + hd(totSup) + "** | **" + totAR + " A/R** | **" + eur2(totFrais) + "** |");
    return L.join("\n");
  };

  return (<div className="fade">
    {/* Bandeau gamifié : niveau, XP, série, badges */}
    <div className="card glass glass-tint" style={{ marginBottom: 14, "--glass-tint": "linear-gradient(135deg, rgba(63,96,170,.18), rgba(124,92,240,.18))" }}>
      <div style={{ display: "flex", gap: 18, flexWrap: "wrap", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
          <div className="pu-display" style={{ width: 54, height: 54, borderRadius: 14, background: "var(--blue)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 900, fontSize: 22, boxShadow: "0 6px 16px rgba(63,96,170,.3)", flexShrink: 0 }}>{level}</div>
          <div>
            <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 800, textTransform: "uppercase", letterSpacing: .4 }}>Niveau {level}</div>
            <div className="pu-display" style={{ fontSize: 18 }}>{levelName}</div>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
              <div style={{ width: 160, maxWidth: "40vw", height: 8, background: "var(--line)", borderRadius: 6, overflow: "hidden" }}><div style={{ width: xpInLevel + "%", height: "100%", background: "linear-gradient(90deg,#3F60AA,#7c5cf0)", borderRadius: 6, transition: "width .4s" }} /></div>
              <span style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700 }}>{xpInLevel}/100 XP</span>
            </div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 22, flexWrap: "wrap" }}>
          <div style={{ textAlign: "center" }}><div style={{ display: "flex", alignItems: "center", gap: 5, justifyContent: "center", color: streak > 0 ? "#FF5A45" : "var(--muted)" }}><Flame size={20} /><span className="pu-display tnum" style={{ fontSize: 24 }}>{streak}</span></div><div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700 }}>jours d'affilée (mois)</div></div>
          <div style={{ textAlign: "center" }}><div style={{ display: "flex", alignItems: "center", gap: 5, justifyContent: "center", color: "#2bb673" }}><Trophy size={19} /><span className="pu-display tnum" style={{ fontSize: 24 }}>{fmtDur(supMois)}</span></div><div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700 }}>heures sup. du mois</div></div>
          <div style={{ textAlign: "center" }}><div className="pu-display tnum" style={{ fontSize: 24 }}>{daysLogged}</div><div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700 }}>jours pointés ce mois</div></div>
        </div>
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 14, paddingTop: 14, borderTop: "1px solid var(--line)", alignItems: "center" }}>
        <span style={{ fontSize: 12, fontWeight: 800, color: "var(--muted)", marginRight: 2 }}>Badges {gotBadges}/{badges.length}</span>
        {badges.map((b) => { const Ic = b.icon; return (<div key={b.id} title={b.desc + (b.got ? " — débloqué" : " — à débloquer")} style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "5px 10px", borderRadius: 20, fontSize: 12, fontWeight: 700, border: "1px solid", borderColor: b.got ? b.color : "var(--line)", color: b.got ? "#fff" : "var(--muted)", background: b.got ? b.color : "transparent", opacity: b.got ? 1 : .5 }}><Ic size={13} />{b.label}</div>); })}
      </div>
    </div>

    {/* Navigation mois */}
    <div className="card" style={{ marginBottom: 14, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <button className="btn btn-ghost btn-s" onClick={() => setCursor((c) => ({ y: c.m === 0 ? c.y - 1 : c.y, m: c.m === 0 ? 11 : c.m - 1 }))}><ChevronLeft size={15} /></button>
        <h3 className="pu-display cal-month" style={{ margin: 0, textTransform: "capitalize" }}>{monthName}</h3>
        <button className="btn btn-ghost btn-s" onClick={() => setCursor((c) => ({ y: c.m === 11 ? c.y + 1 : c.y, m: c.m === 11 ? 0 : c.m + 1 }))}><ChevronRight size={15} /></button>
        <button className="btn btn-ghost btn-s" onClick={() => { const d = new Date(); setCursor({ y: d.getFullYear(), m: d.getMonth() }); }}>Aujourd'hui</button>
      </div>
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
        <button className="btn btn-g btn-s" onClick={() => { setCopied(false); setExportOpen(true); }} title="Exporter les heures et trajets du mois (à coller dans Notion)"><FileDown size={14} /> Exporter</button>
        <button className="btn btn-p btn-s" onClick={() => setEditDs(todayStr)}><Clock size={14} /> Pointer aujourd'hui</button>
      </div>
    </div>

    {/* Calendrier */}
    <div className="card">
      <div className="cal-grid">
        {["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"].map((d) => <div key={d} className="cal-head">{d}</div>)}
        {cells.map((c, i) => {
          const ds = fmtDate(c.y, c.m, c.day);
          const st = presenceDay(pointages[ds]);
          const isToday = ds === todayStr;
          const we = isWeekendDs(ds);
          const mot = st && !st.invalid && st.motif && st.motif !== "presence" ? PRESENCE_MOTIFS[st.motif] : null;
          const over = st && !st.invalid ? st.worked - targetOf(ds) : null;
          const col = over == null ? null : (over >= 0 ? "#2bb673" : "#F8B133");
          const dot = mot ? mot.color : col;
          return (
            <div key={i} className={cx("cal-cell", c.out && "cal-out", isToday && "cal-today")} onClick={() => setEditDs(ds)} style={{ cursor: "pointer", background: we ? "var(--bg)" : undefined }} title={we ? "Week-end — saisie possible (heures comptées en supplément)" : "Cliquer pour saisir la journée"}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div className="cal-num">{c.day}</div>
                {st && !st.invalid && <span style={{ width: 8, height: 8, borderRadius: "50%", background: dot }} />}
                {st && st.invalid && <AlertTriangle size={12} style={{ color: "var(--red)" }} />}
              </div>
              {st && !st.invalid ? (mot ? (<>
                <div style={{ fontSize: 11.5, fontWeight: 800, color: mot.color, lineHeight: 1.1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{mot.emoji} {mot.label}</div>
                <div className="tnum" style={{ fontSize: 11, color: "var(--muted)" }}>{fmtDur(st.worked)}{isChronoMotif(st.motif) && st.arrivee && st.depart ? " · " + st.arrivee + "–" + st.depart : ""}</div>
                {isChronoMotif(st.motif) && over !== 0 && <span style={{ alignSelf: "flex-start", fontSize: 10, fontWeight: 800, color: col, background: col + "22", borderRadius: 6, padding: "1px 5px" }}>{fmtDur(over, { plus: true })}</span>}
              </>) : (<>
                <div className="pu-display tnum" style={{ fontSize: 15, lineHeight: 1.05 }}>{fmtDur(st.worked)}</div>
                <div style={{ fontSize: 10, color: "var(--muted)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{st.arrivee}–{st.depart}{st.pause ? " · 🍽" : ""}</div>
                {over !== 0 && <span style={{ alignSelf: "flex-start", fontSize: 10, fontWeight: 800, color: col, background: col + "22", borderRadius: 6, padding: "1px 5px" }}>{fmtDur(over, { plus: true })}</span>}
              </>)) : (!we && !c.out && <div style={{ fontSize: 10, color: "var(--muted)", opacity: .7 }}>à saisir</div>)}
            </div>
          );
        })}
      </div>
      <div style={{ marginTop: 10, fontSize: 11, color: "var(--muted)", textAlign: "center" }}>Base 7 h/jour du lundi au vendredi. Cliquez un jour pour saisir vos horaires, ou choisir un motif (journée de cours, congés, télétravail… comptés forfaitairement 7 h). Point vert = heures sup, orange = en deçà de l'objectif.</div>
    </div>

    {/* Décompte du mois */}
    <div className="card" style={{ marginTop: 14 }}>
      <div className="sec-h"><h3 className="pu-display" style={{ textTransform: "capitalize" }}>Décompte — {monthName}</h3></div>
      <div className="grid" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(150px,1fr))", gap: 12 }}>
        <div className="calc-out"><span className="l">Jours pointés</span><span className="b pu-display tnum">{mDays}</span></div>
        <div className="calc-out"><span className="l">Total travaillé</span><span className="b pu-display tnum">{fmtDur(mWorked)}</span></div>
        <div className="calc-out"><span className="l">Objectif (7 h × {mDays})</span><span className="b pu-display tnum">{fmtDur(mTarget)}</span></div>
        <div className="calc-out" style={{ background: (mSup > 0 ? "#2bb673" : "#9aa6bd") + "18" }}><span className="l">Heures supplémentaires (semaine &gt; 35 h){mSalaire.mNorm > 0 ? " · + " + fmtDur(mSalaire.mNorm) + " normales (férié/chômé)" : ""}</span><span className="b pu-display tnum" style={{ color: "var(--green)" }}>{fmtDur(mSup)}</span></div>
        <div className="calc-out" style={{ background: (mBalance >= 0 ? "#2bb673" : "#FF5A45") + "18" }}><span className="l">Solde du mois</span><span className="b pu-display tnum" style={{ color: mBalance >= 0 ? "var(--green)" : "var(--red)" }}>{fmtDur(mBalance, { plus: true })}</span></div>
      </div>
      {mDef > 0 && <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 8 }}>Dont {fmtDur(mDef)} en deçà de l'objectif sur certains jours (déduits du solde).</div>}
      {weeks.length > 0 && <div style={{ marginTop: 16 }}>
        <div style={{ fontSize: 12, fontWeight: 800, color: "var(--muted)", marginBottom: 8 }}>Par semaine (objectif 35 h)</div>
        {weeks.map((w) => { const pct = w.target > 0 ? w.worked / w.target * 100 : (w.worked > 0 ? 100 : 0); const bal = w.worked - w.target; const wEnd = new Date(new Date(w.start + "T00:00:00").getTime() + 4 * 86400000); const lbl = new Date(w.start + "T00:00:00").toLocaleDateString("fr-FR", { day: "2-digit", month: "short" }) + " – " + wEnd.toLocaleDateString("fr-FR", { day: "2-digit", month: "short" }); return (
          <div key={w.start} style={{ display: "flex", alignItems: "center", gap: 12, padding: "6px 0" }}>
            <div style={{ width: 128, fontSize: 12, color: "var(--muted)", fontWeight: 700, flexShrink: 0 }}>{lbl}</div>
            <div style={{ flex: 1, height: 12, background: "var(--line)", borderRadius: 7, overflow: "hidden", minWidth: 60 }}><div style={{ width: Math.min(100, pct) + "%", height: "100%", background: bal >= 0 ? "linear-gradient(90deg,#2bb673,#3F60AA)" : "var(--amber)", borderRadius: 7 }} /></div>
            <div className="tnum" style={{ width: 84, textAlign: "right", fontSize: 12.5, fontWeight: 700, flexShrink: 0 }}>{fmtDur(w.worked)}</div>
            <div className="tnum" style={{ width: 66, textAlign: "right", fontSize: 12, fontWeight: 800, color: bal >= 0 ? "var(--green)" : "var(--amber)", flexShrink: 0 }}>{fmtDur(bal, { plus: true })}</div>
          </div>
        ); })}
      </div>}
    </div>

    {editDs && <PointageEditor ds={editDs} rec={pointages[editDs]} onClose={() => setEditDs(null)} onSave={(rec) => { save(editDs, rec); setEditDs(null); }} onDelete={() => { remove(editDs); setEditDs(null); }} />}
    {exportOpen && (() => { const txt = buildExport(); const copy = async () => { try { await navigator.clipboard.writeText(txt); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch (e) { const ta = document.getElementById("pointage-export-ta"); if (ta) { ta.focus(); ta.select(); try { document.execCommand("copy"); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch (e2) {} } } }; return (<Modal title={"Exporter — " + monthName} onClose={() => setExportOpen(false)}>
      <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 10, lineHeight: 1.5 }}>Une ligne par jour pointé du mois (heures travaillées + trajet domicile-travail). Cliquez sur <strong>Copier</strong>, puis collez dans Notion : le tableau se convertit automatiquement.</div>
      <textarea id="pointage-export-ta" readOnly value={txt} onFocus={(e) => e.target.select()} rows={Math.min(22, txt.split("\n").length + 1)} style={{ width: "100%", fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12, lineHeight: 1.5, whiteSpace: "pre", overflowX: "auto" }} />
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 12 }}><button className="btn btn-p" onClick={copy}>{copied ? <><CheckCircle2 size={15} /> Copié !</> : <><Copy size={15} /> Copier</>}</button></div>
    </Modal>); })()}
  </div>);
}
function Agenda({ data, persist, go }) {
  const [cursor, setCursor] = useState(() => { const d = new Date(); return { y: d.getFullYear(), m: d.getMonth() }; });
  const [edit, setEdit] = useState(null);
  const [view, setView] = useState(null);
  const [icsOpen, setIcsOpen] = useState(false);
  // Vue « journée » : la cellule du mois n'affiche que 4 événements ; un clic sur le jour ou sur le
  // « +N » ouvre la liste COMPLÈTE du jour, chaque ligne menant à la même cible que dans la grille.
  const [dayOpen, setDayOpen] = useState(null);
  const monthName = new Date(cursor.y, cursor.m, 1).toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
  const first = new Date(cursor.y, cursor.m, 1);
  const offset = (first.getDay() + 6) % 7; // lundi = 0
  const daysInMonth = new Date(cursor.y, cursor.m + 1, 0).getDate();
  const daysPrev = new Date(cursor.y, cursor.m, 0).getDate();
  const cells = [];
  for (let i = 0; i < offset; i++) cells.push({ day: daysPrev - offset + 1 + i, out: true, y: cursor.m === 0 ? cursor.y - 1 : cursor.y, m: cursor.m === 0 ? 11 : cursor.m - 1 });
  for (let i = 1; i <= daysInMonth; i++) cells.push({ day: i, out: false, y: cursor.y, m: cursor.m });
  while (cells.length % 7 !== 0 || cells.length < 42) { const next = cells.length - offset - daysInMonth + 1; cells.push({ day: next, out: true, y: cursor.m === 11 ? cursor.y + 1 : cursor.y, m: cursor.m === 11 ? 0 : cursor.m + 1 }); if (cells.length >= 42) break; }
  const todayStr = new Date().toISOString().slice(0, 10);
  const saveEvent = (ev) => persist((p) => { const ex = (p.events || []).some((x) => x.id === ev.id); return { ...p, events: ex ? p.events.map((x) => x.id === ev.id ? ev : x) : [...(p.events || []), ev] }; });
  const delEvent = (id) => persist((p) => ({ ...p, events: (p.events || []).filter((x) => x.id !== id) }));
  const eventsByDate = useMemo(() => {
    const map = {};
    data.accounts.filter((a) => a.dateAction && !a.archived).forEach((a) => { (map[a.dateAction] = map[a.dateAction] || []).push({ kind: "action", color: "#3F60AA", label: a.prochaineAction || "Action", sub: a.enseigne, target: { tab: "accounts", id: a.id } }); });
    data.deals.filter((d) => d.date).forEach((d) => { const acc = data.accounts.find((a) => a.id === d.accountId); (map[d.date] = map[d.date] || []).push({ kind: "deal", color: "#F8B133", label: d.ref || d.type, sub: acc ? acc.enseigne : "", target: { tab: "deals", id: d.id } }); });
    data.interactions.filter((i) => i.date).forEach((i) => { const acc = data.accounts.find((a) => a.id === i.accountId); (map[i.date] = map[i.date] || []).push({ kind: "int", color: "#7c5cf0", label: i.sujet || i.type, sub: acc ? acc.enseigne : "", target: { tab: "repertoire", id: i.contactId } }); });
    (data.events || []).filter((e) => !evAncreArchivee(e, data)).forEach((e) => { const site = e.siteId ? (data.sites || []).find((s) => s.id === e.siteId) : null; const acc = e.accountId ? data.accounts.find((a) => a.id === e.accountId) : null; (map[e.date] = map[e.date] || []).push({ kind: "custom", color: e.color || "#2bb673", label: (e.heure ? e.heure + " " : "") + e.titre, sub: (site && (site.label || site.adresse)) || (acc ? acc.enseigne : (e.notes ? e.notes.slice(0, 30) : "")), ev: e }); });
    const yNow = new Date().getFullYear();
    (data.contacts || []).filter((c) => c.naissance && /^\d{4}-\d{2}-\d{2}$/.test(c.naissance)).forEach((c) => { const md = c.naissance.slice(5); const acc = data.accounts.find((a) => a.id === c.accountId); [yNow, yNow + 1].forEach((yy) => { const ds = yy + "-" + md; (map[ds] = map[ds] || []).push({ kind: "anniv", color: "#e0567b", label: "🎂 " + fullName(c), sub: acc ? acc.enseigne : "anniversaire", target: { tab: "repertoire", id: c.id } }); }); });
    return map;
  }, [data]);
  const fmtDate = (y, m, d) => `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  const newEvent = (date) => ({ id: "ev_" + Date.now(), date, heure: "", titre: "", notes: "", type: "rdv", color: EVENT_TYPES.rdv.color, accountId: "" });

  // ====== Glisser-déposer : replanifier un événement d'un jour à l'autre ======
  // Déplaçables : les événements du calendrier (verts) et la prochaine action d'un compte (bleu) —
  // ce sont les seules dates que l'on « planifie ». Un devis, un échange déjà eu ou un anniversaire
  // sont des faits datés : on ne les fait pas glisser, on les corrige dans leur fiche.
  // Souris/stylet : glissé direct dès quelques pixels. Tactile : appui long (~320 ms) puis glissé,
  // pour que le simple défilement de la page reste possible depuis une pastille.
  const gridRef = useRef(null);
  const dragRef = useRef(null);
  const clickGuard = useRef(0);
  const [drag, setDrag] = useState(null);   // { key, label, color, from, over, x, y }
  const [moved, setMoved] = useState(null); // confirmation fugace après un déplacement
  useEffect(() => { if (!moved) return; const t = setTimeout(() => setMoved(null), 2800); return () => clearTimeout(t); }, [moved]);
  useEffect(() => () => { if (dragRef.current && dragRef.current.timer) clearTimeout(dragRef.current.timer); }, []);
  // Pendant un glissé tactile, on bloque le défilement (écouteur non passif : impossible via React).
  useEffect(() => {
    const el = gridRef.current; if (!el) return;
    const stop = (e) => { const d = dragRef.current; if (d && d.started) e.preventDefault(); };
    el.addEventListener("touchmove", stop, { passive: false });
    return () => el.removeEventListener("touchmove", stop);
  }, []);

  const movableOf = (it) => (it.kind === "custom" && it.ev) ? { type: "event", id: it.ev.id, key: "ev:" + it.ev.id } : ((it.kind === "action" && it.target) ? { type: "account", id: it.target.id, key: "ac:" + it.target.id } : null);
  const applyMove = (it, ds) => {
    const mv = movableOf(it); if (!mv || !ds) return;
    if (mv.type === "event") {
      if (it.ev.date === ds) return;
      persist((p) => ({ ...p, events: (p.events || []).map((x) => x.id === mv.id ? { ...x, date: ds } : x) }));
    } else {
      const acc = data.accounts.find((a) => a.id === mv.id);
      if (!acc || acc.dateAction === ds) return;
      persist((p) => ({ ...p, accounts: p.accounts.map((a) => a.id === mv.id ? { ...a, dateAction: ds } : a) }));
    }
    setMoved({ label: it.label, ds });
  };
  const beginDrag = (d, x, y) => { d.started = true; setDrag({ key: movableOf(d.item).key, label: d.item.label, color: d.item.color, from: d.ds, over: d.ds, x, y }); };
  const evDown = (e, it, ds) => {
    if (!movableOf(it)) return;
    if (e.pointerType === "mouse" && e.button !== 0) return;
    const touch = e.pointerType !== "mouse";
    const d = { item: it, ds, x0: e.clientX, y0: e.clientY, started: false, touch, over: ds, timer: null };
    dragRef.current = d;
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* navigateur sans capture */ }
    if (touch) d.timer = setTimeout(() => { if (dragRef.current === d) { beginDrag(d, d.x0, d.y0); try { if (navigator.vibrate) navigator.vibrate(12); } catch { /* ignoré */ } } }, 320);
  };
  const evMove = (e) => {
    const d = dragRef.current; if (!d) return;
    const dx = Math.abs(e.clientX - d.x0), dy = Math.abs(e.clientY - d.y0);
    if (!d.started) {
      if (dx + dy < (d.touch ? 14 : 5)) return;
      // Tactile : un mouvement avant la fin de l'appui long = l'utilisateur veut défiler.
      if (d.touch) { clearTimeout(d.timer); dragRef.current = null; return; }
      beginDrag(d, e.clientX, e.clientY);
    }
    const el = document.elementFromPoint(e.clientX, e.clientY);
    const cell = (el && el.closest) ? el.closest("[data-cal-day]") : null;
    const over = cell ? cell.getAttribute("data-cal-day") : null;
    d.over = over;
    setDrag((c) => c ? { ...c, x: e.clientX, y: e.clientY, over } : c);
  };
  const evUp = () => {
    const d = dragRef.current; if (!d) return;
    if (d.timer) clearTimeout(d.timer);
    dragRef.current = null;
    if (!d.started) return;
    clickGuard.current = Date.now(); // le clic qui suit le glissé ne doit rien ouvrir
    setDrag(null);
    if (d.over && d.over !== d.ds) applyMove(d.item, d.over);
  };
  const evCancel = () => {
    const d = dragRef.current; if (!d) return;
    if (d.timer) clearTimeout(d.timer);
    dragRef.current = null;
    if (d.started) { clickGuard.current = Date.now(); setDrag(null); }
  };
  const justDragged = () => Date.now() - clickGuard.current < 350;

  return (<div className="fade">
    <div className="card" style={{ marginBottom: 14, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <button className="btn btn-ghost btn-s" onClick={() => setCursor((c) => ({ y: c.m === 0 ? c.y - 1 : c.y, m: c.m === 0 ? 11 : c.m - 1 }))}><ChevronLeft size={15} /></button>
        <h3 className="pu-display cal-month" style={{ margin: 0, textTransform: "capitalize" }}>{monthName}</h3>
        <button className="btn btn-ghost btn-s" onClick={() => setCursor((c) => ({ y: c.m === 11 ? c.y + 1 : c.y, m: c.m === 11 ? 0 : c.m + 1 }))}><ChevronRight size={15} /></button>
        <button className="btn btn-ghost btn-s" onClick={() => { const d = new Date(); setCursor({ y: d.getFullYear(), m: d.getMonth() }); }}>Aujourd'hui</button>
      </div>
      <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
        <div style={{ display: "flex", gap: 12, fontSize: 12, color: "var(--muted)", flexWrap: "wrap" }}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><i className="dot" style={{ background: "#3F60AA" }} />Action compte</span>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><i className="dot" style={{ background: "#F8B133" }} />Devis/commande</span>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><i className="dot" style={{ background: "#7c5cf0" }} />Échange</span>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><i className="dot" style={{ background: "#2bb673" }} />Perso</span>
        </div>
        <button className="btn btn-g btn-s" onClick={() => setIcsOpen(true)} title="Connecter ou exporter le calendrier (Google Agenda, Samsung Calendar…)"><CalendarDays size={14} /> Connecter le calendrier</button>
        <button className="btn btn-p btn-s" onClick={() => setEdit(newEvent(todayStr))}><Plus size={14} /> Nouvel événement</button>
      </div>
    </div>
    <div className="card">
      <div className="cal-grid" ref={gridRef}>
        {["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"].map((d) => <div key={d} className="cal-head">{d}</div>)}
        {cells.map((c, i) => { const ds = fmtDate(c.y, c.m, c.day); const evs = eventsByDate[ds] || []; const isToday = ds === todayStr; const isDrop = !!drag && drag.over === ds && drag.from !== ds; return (
          <div key={i} data-cal-day={ds} className={cx("cal-cell", c.out && "cal-out", isToday && "cal-today", isDrop && "cal-drop")} onClick={() => { if (justDragged()) return; if (evs.length) setDayOpen(ds); }} onDoubleClick={() => setEdit(newEvent(ds))} style={{ cursor: "pointer" }} title={evs.length ? "Clic : voir les " + evs.length + " événement(s) du jour · double-clic : ajouter" : "Double-clic pour ajouter un événement à cette date"}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><div className="cal-num">{c.day}</div><button className="iconbtn" style={{ width: 18, height: 18, opacity: .5 }} onClick={(e) => { e.stopPropagation(); setEdit(newEvent(ds)); }} title="Ajouter un événement ce jour"><Plus size={11} /></button></div>
            {evs.slice(0, 4).map((e, j) => { const evDone = e.kind === "custom" && e.ev && e.ev.done; const mv = movableOf(e); const isDragged = !!drag && !!mv && drag.key === mv.key; return (<div key={j} className={cx("cal-ev", mv && "cal-mv", isDragged && "cal-dragging")} style={{ borderLeftColor: e.color, ...(evDone ? { opacity: .5, textDecoration: "line-through" } : {}) }} title={e.label + (e.sub ? " — " + e.sub : "") + (mv ? " — glissez-le sur un autre jour pour le déplacer" : "")} onPointerDown={mv ? ((ee) => evDown(ee, e, ds)) : undefined} onPointerMove={mv ? evMove : undefined} onPointerUp={mv ? evUp : undefined} onPointerCancel={mv ? evCancel : undefined} onClick={(ee) => { ee.stopPropagation(); if (justDragged()) return; if (e.kind === "custom") setView(e.ev); else if (e.target) go(e.target.tab, e.target.id); }}>{evDone ? "✓ " : ""}{e.label}{e.sub && <span className="cal-ev-sub"> · {e.sub}</span>}</div>); })}
            {evs.length > 4 && <button onClick={(e) => { e.stopPropagation(); setDayOpen(ds); }} title={"Voir les " + evs.length + " événements de ce jour"} style={{ fontSize: 10.5, fontWeight: 800, color: "var(--blue)", background: "transparent", border: "none", cursor: "pointer", width: "100%", textAlign: "center", padding: "2px 0", fontFamily: "inherit" }}>+{evs.length - 4} · tout voir</button>}
          </div>
        ); })}
      </div>
      {moved ? <div style={{ marginTop: 10, fontSize: 12, fontWeight: 700, color: "var(--green)", textAlign: "center" }}>« {moved.label} » déplacé au {new Date(moved.ds + "T00:00:00").toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" })}.</div>
      : <div style={{ marginTop: 10, fontSize: 11, color: "var(--muted)", textAlign: "center" }}>Astuce : glissez un événement sur un autre jour pour le replanifier (sur mobile, appui long puis glissé). Cliquez sur un jour pour voir tous ses événements, double-cliquez pour en ajouter un.</div>}
    </div>
    {drag && createPortal(<div className="cal-drag-ghost" style={{ left: drag.x, top: drag.y, borderLeftColor: drag.color }}>{drag.label}</div>, document.body)}
    <div className="card" style={{ marginTop: 14 }}>
      <h3 className="pu-display" style={{ margin: "0 0 10px", fontSize: 16 }}>À venir, 14 prochains jours</h3>
      {(() => {
        const now = new Date(); const limit = new Date(now.getTime() + 14 * 86400000).toISOString().slice(0, 10);
        const items = Object.entries(eventsByDate).filter(([d]) => d >= todayStr && d <= limit).sort((a, b) => a[0].localeCompare(b[0]));
        if (!items.length) return <div className="empty">Pas d'événement programmé.</div>;
        return items.map(([d, evs]) => (<div key={d} style={{ display: "flex", gap: 14, padding: "9px 0", borderBottom: "1px solid var(--line)" }}>
          <div style={{ width: 110, fontSize: 12, color: "var(--muted)", fontWeight: 700 }}>{new Date(d + "T00:00:00").toLocaleDateString("fr-FR", { weekday: "short", day: "2-digit", month: "short" })}</div>
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 4 }}>{evs.map((e, i) => { const evDone = e.kind === "custom" && e.ev && e.ev.done; return (<div key={i} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, flexWrap: "wrap" }}><div onClick={() => { if (e.kind === "custom") setView(e.ev); else if (e.target) go(e.target.tab, e.target.id); }} style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 8, flex: 1, minWidth: 0, textDecoration: evDone ? "line-through" : "none", opacity: evDone ? .6 : 1 }}><i className="dot" style={{ background: e.color }} />{e.label}{e.sub && <span style={{ color: "var(--muted)", fontSize: 12 }}>· {e.sub}</span>}</div>{e.kind === "custom" && e.ev && <EventQuickActions ev={e.ev} onSave={saveEvent} onDelete={() => delEvent(e.ev.id)} />}</div>); })}</div>
        </div>));
      })()}
    </div>
    {edit && <Modal title={(data.events || []).some((e) => e.id === edit.id) ? "Modifier l'événement" : "Nouvel événement"} onClose={() => setEdit(null)}><EventForm event={edit} accounts={data.accounts} onSave={(ev) => { saveEvent(ev); setEdit(null); }} onDelete={() => { delEvent(edit.id); setEdit(null); }} isExisting={(data.events || []).some((e) => e.id === edit.id)} /></Modal>}
    {view && <Modal title="Événement" onClose={() => setView(null)}><EventView event={view} data={data} go={go} onSave={saveEvent} onClose={() => setView(null)} onEdit={() => { const ev = view; setView(null); setEdit(ev); }} onDelete={() => { delEvent(view.id); setView(null); }} /></Modal>}
    {icsOpen && <CalendarExportModal data={data} persist={persist} onClose={() => setIcsOpen(false)} />}
    {dayOpen && (() => { const evs = eventsByDate[dayOpen] || []; return (<Modal title={new Date(dayOpen + "T00:00:00").toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long", year: "numeric" })} onClose={() => setDayOpen(null)}>
      {evs.length === 0 ? <div className="empty">Aucun événement ce jour.</div> : <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 440, overflowY: "auto" }}>{evs.map((e, i) => { const evDone = e.kind === "custom" && e.ev && e.ev.done; return (<div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <div onClick={() => { setDayOpen(null); if (e.kind === "custom") setView(e.ev); else if (e.target) go(e.target.tab, e.target.id); }} style={{ cursor: "pointer", flex: 1, minWidth: 0, display: "flex", alignItems: "center", gap: 9, padding: "8px 10px", border: "1px solid var(--line)", borderLeft: "3px solid " + e.color, borderRadius: 10, background: "#fff", textDecoration: evDone ? "line-through" : "none", opacity: evDone ? .6 : 1 }}>
          <span style={{ fontWeight: 700, fontSize: 13, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{evDone ? "✓ " : ""}{e.label}</span>
          {e.sub && <span style={{ color: "var(--muted)", fontSize: 12, flexShrink: 0 }}>· {e.sub}</span>}
        </div>
        {e.kind === "custom" && e.ev && <EventQuickActions ev={e.ev} onSave={saveEvent} onDelete={() => delEvent(e.ev.id)} />}
      </div>); })}</div>}
      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 12 }}><button className="btn btn-p btn-s" onClick={() => { const d = dayOpen; setDayOpen(null); setEdit(newEvent(d)); }}><Plus size={14} /> Ajouter un événement ce jour</button></div>
    </Modal>); })()}
  </div>);
}
function EventForm({ event, accounts, onSave, onDelete, isExisting }) {
  const [f, setF] = useState({ type: "rdv", ...event });
  const up = (k, v) => setF((p) => ({ ...p, [k]: v }));
  const setType = (t) => { const meta = EVENT_TYPES[t] || EVENT_TYPES.autre; setF((p) => ({ ...p, type: t, color: meta.color })); };
  return (<>
    <div className="fld"><label>Type d'événement</label><div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 6 }}>{Object.entries(EVENT_TYPES).map(([k, v]) => (<button key={k} type="button" onClick={() => setType(k)} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", border: f.type === k ? `2px solid ${v.color}` : "1px solid var(--line)", borderRadius: 10, background: f.type === k ? v.color + "18" : "transparent", color: "var(--ink)", cursor: "pointer", fontFamily: "inherit", fontSize: 12.5, fontWeight: 600, textAlign: "left" }}><span style={{ fontSize: 14 }}>{v.icon}</span><span style={{ flex: 1 }}>{v.label}</span><i className="dot" style={{ background: v.color }} /></button>))}</div></div>
    <div className="fld"><label>Titre</label><input value={f.titre} onChange={(e) => up("titre", e.target.value)} placeholder="Ex : Relancer Cultura, Salon du jouet, Préparer pitch…" autoFocus /><RecentChips champ="event.titre" onPick={(v) => up("titre", v)} /></div>
    <div className="row2"><div className="fld"><label>Date</label><input type="date" value={f.date} onChange={(e) => up("date", e.target.value)} /></div><div className="fld"><label>Heure (optionnel)</label><input type="time" value={f.heure} onChange={(e) => up("heure", e.target.value)} /></div></div>
    <div className="fld"><label>Groupe / établissement lié (optionnel)</label><SearchSelect value={f.accountId || ""} onChange={(v) => up("accountId", v)} options={accountOptionList(accounts, [{ value: "", label: "Aucune" }])} placeholder="Aucune" emptyLabel="Aucune enseigne ne correspond" /></div>
    <div className="fld"><label>Couleur (par défaut selon le type, modifiable)</label><div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>{["#22C55E", "#3F60AA", "#0EA5A4", "#2563EB", "#F59E0B", "#A855F7", "#0891B2", "#EC4899", "#EF4444", "#475569", "#94A3B8"].map((c) => <button key={c} type="button" onClick={() => up("color", c)} style={{ width: 28, height: 28, borderRadius: 8, background: c, border: f.color === c ? "3px solid var(--ink)" : "1px solid var(--line)", cursor: "pointer" }} />)}</div></div>
    <div className="fld"><label style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>Notes <MicDictate title="Dicter une note au micro" onText={(t) => up("notes", ((f.notes || "").trim() + (f.notes && f.notes.trim() ? " " : "") + t))} /></label><textarea rows={3} value={f.notes} onChange={(e) => up("notes", e.target.value)} placeholder="Détails, points à préparer, lien de visio…" /></div>
    <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>{isExisting ? <button className="btn btn-r btn-s" onClick={onDelete}><Trash2 size={14} /> Supprimer</button> : <span />}<button className="btn btn-p" onClick={() => { pousserRecent("event.titre", f.titre); onSave(f); }} disabled={!f.titre || !f.date}>Enregistrer</button></div>
  </>);
}
// Retrouve les fiches liées à un événement : établissement (site ou groupe), personne et échanges rattachés.
function eventRelated(event, data) {
  const site = event.siteId ? (data.sites || []).find((s) => s.id === event.siteId) : null;
  const account = event.accountId ? (data.accounts || []).find((a) => a.id === event.accountId) : null;
  const contact = event.contactId ? (data.contacts || []).find((c) => c.id === event.contactId) : null;
  const ints = (data.interactions || []).filter((it) =>
    (event.fromInteraction && it.id === event.fromInteraction) ||
    (event.contactId && it.contactId === event.contactId) ||
    (event.siteId && it.siteId === event.siteId) ||
    (event.accountId && !event.contactId && !event.siteId && it.accountId === event.accountId)
  ).sort((x, y) => (y.date || "").localeCompare(x.date || ""));
  return { site, account, contact, ints };
}
// Coche « fait / atteint » d'un événement, sinon report rapide (1, 3, 5, 10, 15, 30 j, ou date personnalisée).
function EventQuickActions({ ev, onSave, onAfter, onDelete }) {
  const [openR, setOpenR] = useState(false);
  const [custom, setCustom] = useState("");
  const todayStr = TODAY();
  const addDays = (iso, n) => { const d = new Date((iso || todayStr) + "T00:00:00"); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
  const base = (ev.date && ev.date > todayStr) ? ev.date : todayStr;
  const done = (nv) => { onSave(nv); if (onAfter) onAfter(); };
  if (ev.done) return (<span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
    <span style={{ fontSize: 11.5, fontWeight: 800, color: "var(--green)", display: "inline-flex", alignItems: "center", gap: 4 }}><CheckCircle2 size={13} /> Fait{ev.doneDate ? " · " + ev.doneDate : ""}</span>
    <button className="btn btn-g btn-s" title="Annuler la validation" onClick={(e) => { e.stopPropagation(); onSave({ ...ev, done: false, doneDate: "" }); }}><Undo2 size={12} /></button>
  </span>);
  if (openR) return (<span style={{ display: "inline-flex", alignItems: "center", gap: 4, flexWrap: "wrap" }} onClick={(e) => e.stopPropagation()}>
    <span style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700 }}>Reporter :</span>
    {[1, 3, 5, 10, 15, 30].map((n) => <button key={n} className="btn btn-g btn-s" onClick={() => done({ ...ev, date: addDays(base, n), done: false, doneDate: "" })}>+{n} j</button>)}
    <input type="date" value={custom} min={todayStr} onChange={(e) => setCustom(e.target.value)} style={{ fontSize: 12, maxWidth: 145 }} />
    <button className="btn btn-p btn-s" disabled={!custom} onClick={() => done({ ...ev, date: custom, done: false, doneDate: "" })}>OK</button>
    <button className="btn btn-ghost btn-s" onClick={() => setOpenR(false)}><X size={12} /></button>
  </span>);
  return (<span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
    <button className="btn btn-g btn-s" title="Valider : événement atteint / fait" onClick={(e) => { e.stopPropagation(); done({ ...ev, done: true, doneDate: todayStr }); }}><Check size={13} /> Valider</button>
    <button className="btn btn-g btn-s" title="Reporter l'événement" onClick={(e) => { e.stopPropagation(); setOpenR(true); }}><Clock size={13} /> Reporter</button>
    {onDelete && <button className="iconbtn" title="Supprimer l'événement" style={{ width: 26, height: 26, color: "var(--red)" }} onClick={(e) => { e.stopPropagation(); appConfirm("Supprimer définitivement « " + (ev.titre || "cet événement") + " » ? L'événement disparaîtra aussi du calendrier.", { title: "Supprimer l'événement", confirmLabel: "Supprimer", skipKey: "delEvent" }).then((ok) => { if (ok) { onDelete(); if (onAfter) onAfter(); } }); }}><Trash2 size={13} /></button>}
  </span>);
}
// Vue « Voir » d'un événement : détail + liens cliquables vers l'établissement, la personne et les échanges.
function EventView({ event, data, go, onClose, onEdit, onDelete, onSave }) {
  const m = EVENT_TYPES[event.type] || EVENT_TYPES.autre;
  const { site, account, contact, ints } = eventRelated(event, data);
  const col = event.color || m.color;
  const nav = (fn) => { if (!fn) return; onClose && onClose(); fn(); };
  let dt; try { dt = new Date(event.date).toLocaleDateString("fr-FR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" }); } catch { dt = event.date; }
  const estabLabel = site ? (site.label || site.adresse || "Établissement") : (account ? account.enseigne : null);
  const estabGo = site ? () => go("accounts", null, site.id) : (account ? () => go("accounts", account.id) : null);
  const echGo = contact ? () => go("repertoire", contact.id) : (site ? () => go("accounts", null, site.id) : (account ? () => go("accounts", account.id) : null));
  const Row = ({ icon, k, v, onClick }) => onClick
    ? (<button className="ev-link" onClick={onClick}>{icon}<div><div className="ev-link-k">{k}</div><div className="ev-link-v">{v}</div></div><ChevronRight size={16} /></button>)
    : (<div className="ev-link ev-link-off">{icon}<div><div className="ev-link-k">{k}</div><div className="ev-link-v">{v}</div></div></div>);
  return (<div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
    <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", borderRadius: 14, background: col + "12", borderLeft: "4px solid " + col }}>
      <span style={{ fontSize: 26, flexShrink: 0 }}>{m.icon}</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontWeight: 800, fontSize: 16 }}>{event.titre || m.label}</div>
        <div style={{ color: "var(--muted)", fontSize: 12.5, marginTop: 2, textTransform: "capitalize" }}>{dt}{event.heure ? " · " + event.heure : ""} · {m.label}</div>
      </div>
      {relDate(event.date) && <Badge color={col}>{relDate(event.date)}</Badge>}
    </div>
    {onSave && <div style={{ display: "flex", justifyContent: "flex-end" }}><EventQuickActions ev={event} onSave={onSave} onAfter={onClose} /></div>}
    {event.notes && <div style={{ fontSize: 13, lineHeight: 1.55, whiteSpace: "pre-wrap" }}>{event.notes}</div>}
    {(event.type === "rdv" || event.type === "visio") && (() => {
      // Brief de préparation de RDV : synthèse de l'historique et des enjeux commerciaux du compte concerné.
      const accId = account ? account.id : (site ? site.accountId : null); if (!accId && !ints.length) return null;
      const accDeals = accId ? (data.deals || []).filter((d) => d.accountId === accId) : [];
      const enAttente = accDeals.filter(isDevisEnAttente); const signed = accDeals.filter(isCaSigne); const lastInt = ints[0];
      return (<div style={{ border: "1px solid var(--line)", borderRadius: 12, padding: "12px 14px", background: "var(--blue-l)" }}>
        <div className="pu-display" style={{ fontWeight: 800, marginBottom: 6 }}>📋 Brief de préparation</div>
        <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12.5, lineHeight: 1.7 }}>
          <li>Dernier échange : {lastInt ? (lastInt.date + " — " + (lastInt.sujet || (INT_META[lastInt.type] || INT_META.note).label) + (lastInt.resume ? " : " + lastInt.resume.slice(0, 90) : "")) : "aucun échange enregistré"}</li>
          <li>Devis en attente : {enAttente.length ? (enAttente.length + " · " + eur(sumMontant(enAttente)) + " HT") : "aucun"}</li>
          <li>Historique : {ints.length} échange{ints.length > 1 ? "s" : ""}{accId ? " · CA HT signé " + eur(sumMontant(signed)) + " · " + signed.length + " facture(s)" : ""}</li>
        </ul>
      </div>);
    })()}
    <div>
      <div style={{ fontSize: 11, fontWeight: 700, color: "var(--muted)", textTransform: "uppercase", letterSpacing: ".04em", marginBottom: 8 }}>Fiches liées</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        <Row icon={<Building2 size={17} />} k="Établissement" v={estabLabel || "Aucun rattaché"} onClick={estabGo && (() => nav(estabGo))} />
        <Row icon={<User size={17} />} k="Personne concernée" v={contact ? (fullName(contact) + (contact.fonction ? " · " + contact.fonction : "")) : "Aucune précisée"} onClick={contact && (() => nav(() => go("repertoire", contact.id)))} />
        <Row icon={<MessageSquare size={17} />} k="Échanges" v={ints.length ? (ints.length + " échange" + (ints.length > 1 ? "s" : "") + (ints[0].date ? " · dernier le " + ints[0].date : "")) : (echGo ? "Voir le fil de discussion" : "Aucun échange lié")} onClick={(echGo && (ints.length || contact || site || account)) ? (() => nav(echGo)) : null} />
      </div>
    </div>
    <div style={{ display: "flex", justifyContent: "space-between", gap: 8, borderTop: "1px solid var(--line)", paddingTop: 12 }}>
      {onDelete ? <button className="btn btn-r btn-s" onClick={onDelete}><Trash2 size={14} /> Supprimer</button> : <span />}
      {onEdit && <button className="btn btn-p" onClick={onEdit}><Pencil size={14} /> Modifier</button>}
    </div>
  </div>);
}
// Vue « Voir » d'un échange : présenté comme un message, avec liens vers la personne et l'établissement.
function InteractionView({ interaction: it, data, go, onClose, onEdit }) {
  const m = INT_META[it.type] || INT_META.note; const Ic = m.icon;
  const ct = it.contactId ? (data.contacts || []).find((c) => c.id === it.contactId) : null;
  const site = it.siteId ? (data.sites || []).find((s) => s.id === it.siteId) : null;
  const account = it.accountId ? (data.accounts || []).find((a) => a.id === it.accountId) : null;
  const nav = (fn) => { if (!fn) return; onClose && onClose(); fn(); };
  let dt; try { dt = new Date(it.date).toLocaleDateString("fr-FR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" }); } catch { dt = it.date; }
  const rejected = it.direction === "sortant_rejete";
  const dm = DIRECTIONS[it.direction]; const DIc = dm ? dm.icon : null;
  // Appel rejeté : badge rouge avec combiné barré (PhoneOff) ; le sens séparé devient redondant.
  const badgeColor = rejected ? "var(--red)" : m.color; const BIc = rejected ? PhoneOff : Ic;
  const lnkStyle = { background: "none", border: 0, padding: 0, font: "inherit", cursor: "pointer" };
  return (<div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
      <span className="badge" style={{ background: badgeColor + "18", color: darkenHex(badgeColor) }}><BIc size={12} />{m.label}</span>
      {dm && !rejected && <span style={{ fontSize: 12, color: "var(--muted)", display: "inline-flex", alignItems: "center", gap: 4 }}><DIc size={13} color={dm.color} />{dm.label}</span>}
      {it.source === "gmail" && <span className="gtag">Gmail</span>}{it.source === "journal-appels" && <span className="ctag" title="Importé du journal d'appels du téléphone (SMS Backup & Restore)">Journal d'appels</span>}{it.sourced && <span className="srctag" title={it.source === "journal-appels" ? "Importé automatiquement du journal d'appels du téléphone (trace fidèle)" : "Importé automatiquement depuis la boîte Gmail connectée (trace fidèle)"}>sourcé</span>}
      <span className="tnum" style={{ fontSize: 12, color: "var(--muted)", marginLeft: "auto", textTransform: "capitalize" }}>{dt}{it.heure ? " · " + it.heure : ""}</span>
    </div>
    {it.email && <div style={{ fontSize: 12.5, color: "var(--muted)", display: "inline-flex", alignItems: "center", gap: 5, marginTop: -6 }}><Mail size={13} /> {it.email}</div>}
    <div style={{ background: "#f5f7fb", border: "1px solid var(--line)", borderRadius: 16, borderTopLeftRadius: 5, padding: "14px 16px" }}>
      <div style={{ fontWeight: 800, fontSize: 15 }}>{(it.source === "gmail" ? decodeEntities(it.sujet) : it.sujet) || "Échange"}</div>
      {it.resume ? (() => { const wa = it.type === "whatsapp" ? parseWaResume(it.resume) : null; return <div style={{ fontSize: 13.5, lineHeight: 1.6, marginTop: 8, whiteSpace: wa ? "normal" : "pre-wrap", maxHeight: 360, overflowY: "auto", overflowWrap: "anywhere", wordBreak: "break-word", minWidth: 0 }}>{wa ? <WaBubbles p={wa} who={ct ? fullName(ct) : (it.interlocuteur || "")} /> : (it.source === "gmail" ? decodeEntities(it.resume) : it.resume)}</div>; })() : <div className="empty" style={{ padding: 14 }}>Aucun compte rendu saisi.</div>}
    </div>
    {(ct || it.interlocuteur || site || account) && <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "center" }}>
      {ct ? <button className="lnk" style={lnkStyle} onClick={() => nav(() => go("repertoire", ct.id))}><User size={14} /> {fullName(ct)}</button> : (it.interlocuteur ? <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 13, color: "var(--muted)" }}><User size={14} /> {it.interlocuteur}</span> : null)}
      {site && <button className="lnk" style={lnkStyle} onClick={() => nav(() => go("accounts", null, site.id))}><Store size={14} /> {site.label || site.adresse || "Établissement"}</button>}
      {!site && account && <button className="lnk" style={lnkStyle} onClick={() => nav(() => go("accounts", account.id))}><Building2 size={14} /> {account.enseigne}</button>}
    </div>}
    {(onEdit || (it.email && it.direction === "entrant")) && <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, borderTop: "1px solid var(--line)", paddingTop: 12 }}>{it.email && it.direction === "entrant" && <a className="btn btn-g" href={"mailto:" + it.email + "?subject=" + encodeURIComponent("Re: " + (it.sujet || ""))} style={{ textDecoration: "none" }} title="Répondre à ce courriel (objet pré-rempli)"><Mail size={14} /> Répondre</a>}{onEdit && <button className="btn btn-p" onClick={onEdit}><Pencil size={14} /> Modifier</button>}</div>}
  </div>);
}
// Liste d'échanges présentée comme un fil de discussion (entrant à gauche, sortant à droite), avec Voir / Modifier / Supprimer.
function InteractionThread({ interactions, data, onView, onEdit, onDelete, showContact }) {
  if (!interactions || interactions.length === 0) return <div className="empty">Aucun échange.</div>;
  // Fil trié du plus RÉCENT (en haut) au plus ancien (en bas), en tenant compte de l'heure.
  const ordered = interactions.slice().sort((a, b) => (b.date || "").localeCompare(a.date || "") || (b.heure || "").localeCompare(a.heure || ""));
  return (<div className="thread">{ordered.map((it) => {
    const m = INT_META[it.type] || INT_META.note;
    const ct = showContact && it.contactId ? (data.contacts || []).find((c) => c.id === it.contactId) : null;
    const inbound = it.direction === "entrant";
    const rejected = it.direction === "sortant_rejete";
    // Appel rejeté : un seul symbole rouge barré (combiné) + libellé en rouge ; pas d'indicateur « rejeté »
    // séparé (redondant). Sinon : icône du type + flèche de sens (entrant vert / sortant bleu).
    const Ic = rejected ? PhoneOff : m.icon; const typeColor = rejected ? "var(--red)" : m.color;
    return (<div key={it.id} id={"int-" + it.id} className={cx("msg", inbound ? "msg-in" : "msg-out")}>
      <div className={cx("msg-bubble", it.source === "journal-appels" && "msg-appel")}>
        <div className="msg-head">
          <span title={rejected ? "Appel sortant rejeté / sans réponse" : undefined} style={{ fontWeight: 700, color: typeColor, display: "inline-flex", alignItems: "center", gap: 4 }}><Ic size={12} />{m.label}</span>
          {!rejected && (inbound ? <ArrowDownLeft size={12} color="var(--green)" /> : <ArrowUpRight size={12} color="var(--blue)" />)}
          {it.source === "gmail" && <span className="gtag">Gmail</span>}{it.source === "journal-appels" && <span className="ctag" title="Importé du journal d'appels du téléphone (SMS Backup & Restore)">Journal d'appels</span>}{it.sourced && <span className="srctag" title={it.source === "journal-appels" ? "Importé automatiquement du journal d'appels du téléphone (trace fidèle)" : "Importé automatiquement depuis la boîte Gmail connectée (trace fidèle)"}>sourcé</span>}
          <span className="tnum" style={{ color: "var(--muted)" }}>{it.date}{it.heure ? " · " + it.heure : ""}</span>
          {(ct || it.interlocuteur) && <span style={{ color: "var(--muted)" }}>· {ct ? fullName(ct) : it.interlocuteur}</span>}
          {it.email && <span className="crow-email" style={{ color: "var(--muted)", display: "inline-flex", alignItems: "center", gap: 3, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} title={it.email}><Mail size={11} style={{ flexShrink: 0 }} />{it.email}</span>}
          <span className="msg-actions">
            <button className="iconbtn" onClick={() => onView(it)} title="Voir l'échange"><Eye size={13} /></button>
            <button className="iconbtn" onClick={() => onEdit(it)} title="Modifier l'échange"><Pencil size={12} /></button>
            <button className="iconbtn" onClick={() => onDelete(it.id)} title="Supprimer"><X size={13} /></button>
          </span>
        </div>
        <div className="msg-subj">{it.source === "gmail" ? decodeEntities(it.sujet) : it.sujet}</div>
        {it.resume && (() => { const wa = it.type === "whatsapp" ? parseWaResume(it.resume) : null; const waCt = wa && it.contactId ? (data.contacts || []).find((c) => c.id === it.contactId) : null; return <div className="msg-body" style={{ maxHeight: 220, overflowY: "auto", ...(wa ? { whiteSpace: "normal" } : {}) }}>{wa ? <WaBubbles p={wa} who={waCt ? fullName(waCt) : (it.interlocuteur || "")} /> : (it.source === "gmail" ? decodeEntities(it.resume) : it.resume)}</div>; })()}
      </div>
    </div>);
  })}</div>);
}

// ============== RECHERCHE GLOBALE (Cmd+K) ==============
function SearchPalette({ data, onClose, onPick }) {
  const [q, setQ] = useState("");
  const [sel, setSel] = useState(0);
  const inputRef = useRef(null);
  useEffect(() => { if (inputRef.current) inputRef.current.focus(); }, []);
  const ACTIONS = [
    { label: "Créer un devis", sub: "Documents commerciaux", tab: "deals", kw: "devis document nouveau creer" },
    { label: "Nouvelle commande", sub: "Documents commerciaux", tab: "deals", kw: "commande document creer" },
    { label: "Ajouter un contact", sub: "Répertoire", tab: "repertoire", kw: "contact ajouter nouveau repertoire" },
    { label: "Nouvel établissement / groupe", sub: "Groupes & établissements", tab: "accounts", kw: "etablissement groupe nouveau compte enseigne" },
    { label: "Ajouter un événement", sub: "Calendrier", tab: "agenda", kw: "evenement rdv agenda calendrier rappel action" },
    { label: "Recherche IA de prospects", sub: "Prospection", tab: "prospection", kw: "prospect prospection recherche ia" },
    { label: "Ouvrir la carte", sub: "Carte", tab: "carte", kw: "carte map tournee itineraire" },
  ];
  const results = useMemo(() => {
    const nq = normStr(q);
    if (!nq) return { Actions: [], Enseignes: [], Contacts: [], Deals: [], Sites: [], Produits: [] };
    const acts = ACTIONS.filter((a) => normStr(a.label + " " + a.kw).includes(nq)).slice(0, 6).map((a) => ({ label: a.label, sub: a.sub, tab: a.tab, action: true }));
    const accs = data.accounts.filter((a) => normStr(a.enseigne).includes(nq) || normStr(a.ville).includes(nq) || normStr(a.notes).includes(nq)).slice(0, 5).map((a) => ({ id: a.id, label: a.enseigne, sub: a.ville || a.typeSurface || "", tab: "accounts" }));
    const cts = data.contacts.filter((c) => normStr(c.prenom + c.nom).includes(nq) || normStr(c.email).includes(nq) || normStr(c.fonction).includes(nq)).slice(0, 5).map((c) => { const acc = data.accounts.find((a) => a.id === c.accountId); return { id: c.id, label: fullName(c), sub: (c.fonction || "") + (acc ? " · " + acc.enseigne : ""), tab: "repertoire" }; });
    const dls = data.deals.filter((d) => normStr(d.ref).includes(nq) || normStr(d.type).includes(nq)).slice(0, 5).map((d) => { const acc = data.accounts.find((a) => a.id === d.accountId); return { id: d.id, label: d.ref || d.type, sub: (acc ? acc.enseigne + " · " : "") + eur(d.montant), tab: "deals" }; });
    const sts = data.sites.filter((s) => normStr(s.label).includes(nq) || normStr(s.adresse).includes(nq) || normStr(s.ville).includes(nq)).slice(0, 5).map((s) => ({ id: s.id, label: s.label, sub: s.adresse || "", tab: "carte" }));
    const prods = data.products.filter((p) => normStr(p.designation).includes(nq) || normStr(p.code).includes(nq)).slice(0, 5).map((p) => ({ id: p.code, label: p.designation, sub: p.code + " · " + p.famille, tab: "stock" }));
    return { Actions: acts, Enseignes: accs, Contacts: cts, Deals: dls, Sites: sts, Produits: prods };
  }, [q, data]);
  const flat = useMemo(() => { const f = []; Object.entries(results).forEach(([k, v]) => v.forEach((it) => f.push({ ...it, cat: k }))); return f; }, [results]);
  useEffect(() => { setSel(0); }, [q]);
  const onKey = (e) => {
    if (e.key === "ArrowDown") { e.preventDefault(); setSel((s) => Math.min(flat.length - 1, s + 1)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setSel((s) => Math.max(0, s - 1)); }
    else if (e.key === "Enter" && flat[sel]) { e.preventDefault(); onPick(flat[sel]); }
  };
  return (<div className="cmdk-ov" onClick={onClose}>
    <div className="cmdk" onClick={(e) => e.stopPropagation()}>
      <input ref={inputRef} value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={onKey} placeholder="Rechercher dans tout le CRM : groupes, établissements, contacts, devis, sites, produits…" />
      <div className="cmdk-list">
        {!q && <div style={{ padding: "30px 16px", textAlign: "center", color: "var(--muted)", fontSize: 13 }}>Tapez pour rechercher partout. ↑↓ pour naviguer, Entrée pour ouvrir, Esc pour fermer.</div>}
        {q && flat.length === 0 && <div style={{ padding: "26px 16px", textAlign: "center", color: "var(--muted)", fontSize: 13 }}>Aucun résultat.</div>}
        {q && Object.entries(results).map(([cat, items]) => items.length > 0 && (<div key={cat}>
          <div className="cmdk-cat">{cat}</div>
          {items.map((it) => { const idx = flat.findIndex((f) => f.id === it.id && f.cat === cat); return (
            <div key={cat + it.id} className={cx("cmdk-item", idx === sel && "sel")} onClick={() => onPick(it)} onMouseEnter={() => setSel(idx)}>
              <ChevronRight size={14} color="var(--muted)" />
              <span style={{ fontWeight: 600 }}>{it.label}</span>
              {it.sub && <span className="meta">{it.sub}</span>}
            </div>
          ); })}
        </div>))}
      </div>
      <div className="cmdk-foot"><span>↑↓ Naviguer</span><span>↵ Ouvrir</span><span>Esc Fermer</span></div>
    </div>
  </div>);
}

function assistantAnswer(qRaw, data) {
  const q = normStr(qRaw || "");
  const has = (...ws) => ws.some((w) => q.includes(normStr(w)));
  const openDeals = data.deals.filter((d) => !DEAL_LIVRE(d.statut) && d.statut !== "refuse");
  if (!q.trim()) return { text: "Posez-moi une question sur vos groupes et établissements, votre pipeline, votre stock ou l'agenda." };
  // Aide / capacités
  if (has("aide", "help", "que sais-tu", "que peux-tu", "capacite", "comment ca marche", "?aide")) {
    return { text: "Je lis les données du cockpit pour vous répondre. Essayez : « valeur du pipeline », « à faire cette semaine », « ruptures de stock », « combien d'établissements », « règle du franco de port », « infos sur Cultura », ou « cherche le contact Carine »." };
  }
  // Salutations
  if (has("bonjour", "salut", "coucou", "hello", "bonsoir", "hey", "yo ")) {
    return { text: "Bonjour. Je suis l'assistant du cockpit PEN'UP 3D. Je peux résumer votre pipeline, vos actions à venir, l'état du stock, ou retrouver un groupe, un établissement ou un contact. Que voulez-vous savoir ?" };
  }
  // Franco de port
  if (has("franco", "frais de port", "livraison gratuite", "port offert", "participation port")) {
    return { text: `Franco de port selon la zone de livraison : France métropolitaine dès ${FRANCO_ZONES.metropole.seuil} € HT (sinon participation ${FRANCO_ZONES.metropole.part} € HT), Monaco dès ${FRANCO_ZONES.monaco.seuil} € HT (sinon ${FRANCO_ZONES.monaco.part} € HT), Corse dès ${FRANCO_ZONES.corse.seuil} € HT (sinon ${FRANCO_ZONES.corse.part} € HT). La zone est déduite automatiquement de l'adresse de livraison (modifiable dans le devis) et applique le bon franco.` };
  }
  // Pipeline / valeur
  if (has("pipeline", "entonnoir", "portefeuille", "valeur", "potentiel")) {
    const total = openDeals.reduce((s, d) => s + d.montant, 0);
    const caAttente = sumMontant(data.deals.filter(isDevisEnAttente));
    const caSigne = sumMontant(data.deals.filter(isCaSigne));
    return { text: `Documents commerciaux actifs : ${openDeals.length} pour ${eur(total)}.\nCA HT en attente (devis) : ${eur(caAttente)}.\nCA HT signé : ${eur(caSigne)}.`, actions: [{ label: "Ouvrir le pipeline", tab: "pipeline" }, { label: "Voir les devis", tab: "deals" }] };
  }
  // CA signé
  if (has("ca ", "chiffre", "signe", "signé", "vendu", "facture accepte")) {
    const ca = data.deals.filter((d) => d.statut === "accepte" || DEAL_LIVRE(d.statut)).reduce((s, d) => s + d.montant, 0);
    return { text: `Chiffre d'affaires signé (devis acceptés + livrés) : ${eur(ca)}.`, actions: [{ label: "Voir les documents", tab: "deals" }] };
  }
  // Stock / ruptures
  if (has("rupture", "stock", "inventaire", "dispo")) {
    const rup = data.products.filter((p) => statusOf(p) === "rupture");
    const bas = data.products.filter((p) => statusOf(p) === "bas");
    if (!rup.length && !bas.length) return { text: "Aucune alerte de stock : toutes les références sont au-dessus de leur seuil.", actions: [{ label: "Voir le stock", tab: "stock" }] };
    const top = [...rup, ...bas].slice(0, 6).map((p) => `• ${p.designation} (${p.dispo} en stock)`).join("\n");
    return { text: `${rup.length} rupture(s) et ${bas.length} stock(s) bas.\n${top}${(rup.length + bas.length) > 6 ? "\n…" : ""}`, actions: [{ label: "Voir le stock", tab: "stock" }, { label: "Réassort", tab: "reassort" }] };
  }
  // Réassort
  if (has("reassort", "réassort", "recommande", "à commander")) {
    const f = pdvForecast(data).filter((x) => x.daysLeft != null && x.daysLeft <= 21);
    return { text: f.length ? `${f.length} situation(s) de réassort à surveiller (couverture ≤ 21 jours).` : "Pas de réassort urgent détecté.", actions: [{ label: "Ouvrir le réassort", tab: "reassort" }] };
  }
  // Agenda / actions
  if (has("a faire", "à faire", "action", "agenda", "relance", "semaine", "prochaine", "rendez", "rdv", "planning", "aujourd")) {
    const today = new Date().toISOString().slice(0, 10);
    const horizon = new Date(Date.now() + 14 * 864e5).toISOString().slice(0, 10);
    const acts = data.accounts.filter((a) => a.dateAction && a.dateAction <= horizon).sort((x, y) => (x.dateAction || "").localeCompare(y.dateAction || ""));
    if (!acts.length) return { text: "Aucune action planifiée dans les 14 prochains jours.", actions: [{ label: "Ouvrir l'agenda", tab: "agenda" }] };
    const lines = acts.slice(0, 6).map((a) => `• ${a.dateAction}${a.dateAction < today ? " (en retard)" : ""} — ${a.enseigne} : ${a.prochaineAction || "à préciser"}`).join("\n");
    return { text: `Prochaines actions :\n${lines}`, actions: [{ label: "Ouvrir l'agenda", tab: "agenda" }] };
  }
  // Établissements / PDV
  if (has("établissement", "point de vente", "pdv", "boutique")) {
    const pdv = data.sites.filter((s) => s.type === "pdv");
    const parEns = {};
    pdv.forEach((s) => { const a = data.accounts.find((x) => x.id === s.accountId); const k = a ? a.enseigne : "Sans rattachement"; parEns[k] = (parEns[k] || 0) + 1; });
    const detail = Object.entries(parEns).map(([k, v]) => `• ${k} : ${v}`).join("\n");
    return { text: `${pdv.length} établissement(s) suivi(s) au total.\n${detail}`, actions: [{ label: "Voir la carte", tab: "carte" }, { label: "Voir les groupes & établissements", tab: "accounts" }] };
  }
  // JER / usine / fournisseur
  if (has("jer", "usine", "chine", "fournisseur", "fabricant", "guangzhou")) {
    return { text: "JER Education Technology (Guangzhou, Chine) est l'usine partenaire pour le stylo hybride. Elle figure sur la carte comme ancrage stratégique (hexagone rouge).", actions: [{ label: "Voir sur la carte", tab: "carte" }] };
  }
  // SAV / tickets
  if (has("sav", "ticket", "reclamation", "réclamation", "litige", "incident")) {
    const open = data.tickets.filter((t) => t.statut === "ouvert" || t.statut === "en_cours");
    return { text: open.length ? `${open.length} ticket(s) SAV actif(s).` : "Aucun ticket SAV ouvert.", actions: [{ label: "Ouvrir le SAV", tab: "sav" }] };
  }
  // Devis / commandes / factures
  if (has("devis", "commande", "facture", "document commercial")) {
    const nb = (t) => data.deals.filter((d) => d.type === t).length;
    return { text: `Documents : ${nb("Devis")} devis, ${nb("Commande")} bon(s) de commande, ${nb("Facture")} facture(s).`, actions: [{ label: "Voir les documents", tab: "deals" }] };
  }
  // Calculateur / marge / prix / coefficient
  if (has("marge", "coefficient", "coef", "prix", "tarif", "cession", "calcul")) {
    return { text: `Pour simuler une marge ou un prix, utilisez le calculateur. Rappel : coefficient cible ×${(data.settings.coefTarget || 2.2).toFixed(2)}, plafond ×${((data.settings.coefMax != null ? data.settings.coefMax : data.settings.coefMin) || 2.0).toFixed(2)}.`, actions: [{ label: "Ouvrir le calculateur", tab: "calc" }] };
  }
  // Recherche d'un contact
  const contactHit = data.contacts.find((c) => { const full = normStr((c.prenom || "") + " " + (c.nom || "")); return full.trim() && (q.includes(normStr(c.nom || "")) && (c.nom || "").length > 2 || q.includes(normStr(c.prenom || "")) && (c.prenom || "").length > 2); });
  if (contactHit && has("contact", "qui est", "joindre", "telephone", "téléphone", "mail", "appel", "cherche")) {
    const a = data.accounts.find((x) => x.id === contactHit.accountId);
    return { text: `${[contactHit.prenom, contactHit.nom].filter(Boolean).join(" ")}${contactHit.fonction ? " — " + contactHit.fonction : ""}${a ? " (" + a.enseigne + ")" : ""}.${contactHit.email ? "\nCourriel : " + contactHit.email : ""}${contactHit.mobile || contactHit.fixe ? "\nTél : " + (contactHit.mobile || contactHit.fixe) : ""}`, actions: [{ label: "Ouvrir la fiche", tab: "repertoire", id: contactHit.id }] };
  }
  // Recherche d'une enseigne nommée
  const accHit = data.accounts.find((a) => a.enseigne && q.includes(normStr(a.enseigne)) && a.enseigne.length > 2);
  if (accHit) {
    const st = STAGES.find((s) => s.id === accHit.stage);
    const pdv = data.sites.filter((s) => s.accountId === accHit.id && s.type === "pdv").length;
    const nbC = data.contacts.filter((c) => c.accountId === accHit.id).length;
    return { text: `${accHit.enseigne} — étape : ${st ? st.label : accHit.stage}. ${pdv} établissement(s) suivi(s), ${nbC} contact(s).${accHit.prochaineAction ? "\nProchaine action : " + accHit.prochaineAction + (accHit.dateAction ? " (" + accHit.dateAction + ")" : "") : ""}`, actions: [{ label: "Ouvrir la fiche", tab: "accounts", id: accHit.id }] };
  }
  // Liste enseignes / clients
  if (has("enseigne", "client", "compte", "prospect", "qui sont", "liste")) {
    const parStage = STAGES.map((s) => { const n = data.accounts.filter((a) => a.stage === s.id).length; return n ? `• ${s.label} : ${n}` : null; }).filter(Boolean).join("\n");
    return { text: `${data.accounts.length} compte(s) au total.\n${parStage}`, actions: [{ label: "Voir les groupes & établissements", tab: "accounts" }] };
  }
  // Combien (générique)
  if (has("combien")) {
    return { text: `En résumé : ${data.accounts.length} enseignes, ${data.contacts.length} contacts, ${data.sites.filter((s) => s.type === "pdv").length} établissements, ${data.deals.length} documents commerciaux, ${data.products.length} références produit.` };
  }
  return { text: "Je n'ai pas saisi la demande. Essayez par exemple : « valeur du pipeline », « à faire cette semaine », « ruptures de stock », « combien d'établissements », « franco de port », « infos sur Cultura », « cherche le contact Carine ». Tapez « aide » pour la liste." };
}

function assistantContext(data) {
  const P = (data.products || []).map((p) => ({ code: p.code, nom: p.designation, dispo: p.dispo, resa: p.resa, encmd: p.encmd, pvc: p.pvc, cessionHT: p.cessionHT, seuil: p.seuil, cout: p.cout, vendable: p.vendable, poidsG: p.poidsG, ventesMois: p.ventesMois }));
  const A = (data.accounts || []).map((a) => ({ id: a.id, enseigne: a.enseigne, nature: a.nature, stage: a.stage, ville: a.ville }));
  const C = (data.contacts || []).map((c) => ({ id: c.id, accountId: c.accountId, nom: ((c.prenom || "") + " " + (c.nom || "")).trim(), fonction: c.fonction }));
  const D = (data.deals || []).map((d) => ({ id: d.id, ref: d.ref, type: d.type, statut: d.statut, date: d.date, accountId: d.accountId, montant: d.montant, note: d.note, lignes: (d.lines || []).map((l) => ({ code: l.code, qte: l.qte, pu: l.pu })) }));
  const E = (data.events || []).map((e) => ({ id: e.id, date: e.date, titre: e.titre, type: e.type, accountId: e.accountId }));
  const S = data.settings || {};
  return { today: new Date().toISOString().slice(0, 10), produits: P, comptes: A, contacts: C, devisEtCommandes: D, agenda: E, reglages: { coefTarget: S.coefTarget, coefMax: S.coefMax, tva: S.tva, fxSpot: S.fxSpot, fxMargin: S.fxMargin } };
}
async function assistantAI(text, history, data) {
  const ctx = assistantContext(data);
  const sys = "Tu es l'assistant interne du cockpit CRM de PEN'UP 3D (PME française, stylos d'impression 3D créatifs pour enfants, distribution B2B en établissements spécialisés). Tu aides à piloter l'activité commerciale : groupes et établissements, contacts, pipeline, devis et commandes, stock, agenda, marges, logistique, produits PEN'UP.\n\nPERIMETRE STRICT : tu ne traites QUE ces sujets metier. Toute demande hors perimetre (cuisine, culture generale, code informatique, bavardage, etc.) renvoie inScope=false, actions vide, et un reply poli rappelant que tu es limite au cockpit PEN'UP 3D.\n\nTu reponds TOUJOURS en JSON strict valide, sans aucun texte autour ni balise Markdown, selon ce schema :\n{\"inScope\":bool,\"reply\":\"texte en francais, concis\",\"actions\":[ ... ]}\n\nActions possibles (n'en propose que si l'utilisateur le demande) :\n- {\"type\":\"navigate\",\"label\":\"Ouvrir la fiche ...\",\"tab\":\"accounts|repertoire|deals|stock|agenda|pipeline|carte|performance|stats|prospection|presto|reassort|sav|calc|conn|dash\",\"id\":\"identifiant de la fiche\"} : ouvre une fiche. tab \"accounts\" + id=accountId ouvre la fiche du compte (qui contient ses contacts) ; tab \"repertoire\" + id=contactId ouvre la fiche contact ; tab \"deals\" + id=dealId ouvre le devis/commande ; tab \"stock\" ouvre le stock (sans id). Mets TOUJOURS un label clair en francais.\n- {\"type\":\"add_event\",\"date\":\"AAAA-MM-JJ\",\"heure\":\"HH:MM optionnel\",\"titre\":\"...\",\"eventType\":\"rdv|relance|salon|preparation|tache|echeance|livraison\",\"accountId\":\"id ou null\",\"notes\":\"optionnel\"}\n- {\"type\":\"update_product\",\"code\":\"code produit\",\"set\":{\"dispo\":int,\"resa\":int,\"encmd\":int,\"pvc\":number,\"seuil\":int,\"cout\":number,\"poidsG\":int,\"vendable\":bool}}\n- {\"type\":\"add_interaction\",\"accountId\":\"id\",\"contactId\":\"id ou null\",\"intType\":\"rdv|email|appel|note\",\"date\":\"AAAA-MM-JJ\",\"sujet\":\"...\",\"resume\":\"optionnel\"}\n- {\"type\":\"create_deal\",\"accountId\":\"id\",\"dealType\":\"Devis|Commande\",\"date\":\"AAAA-MM-JJ\",\"lines\":[{\"code\":\"code\",\"qte\":int,\"pu\":number}],\"note\":\"optionnel\"}\n\nREGLES :\n- Pour repondre a une question, mets la reponse dans reply. Si ta reponse cite un ou des enregistrements precis (un groupe ou établissement, un contact, un devis/commande, un produit), AJOUTE pour chacun une action navigate vers sa fiche, avec un label clair (ex: \"Ouvrir la fiche Cultura\", \"Voir le devis DV-2026-008\", \"Voir le stock du stylo\"). Pour un contact, renvoie vers la fiche client (tab \"accounts\", id=accountId). N'ajoute navigate que pour les enregistrements reellement cites, 3 au maximum.\n- Resous les noms en identifiants a partir des donnees (ex: \"Cultura\" -> accountId, \"pack complet\" -> code produit).\n- N'invente JAMAIS une valeur manquante (prix, quantite non precisee). Si une info indispensable manque, demande-la dans reply au lieu d'agir.\n- Pour create_deal, omets \"pu\" si l'utilisateur ne donne pas de prix : la ligne sera valorisee au prix de cession HT du produit (cessionHT). N'inscris JAMAIS de coefficient ni de marge dans une note de devis ou de commande : ces documents sont destines aux distributeurs et ne doivent contenir que des prix de cession HT.\n- Convertis les dates relatives (\"demain\", \"vendredi\") en AAAA-MM-JJ avec la date du jour fournie.\n- Une seule demande peut produire plusieurs actions.\n\nDONNEES ACTUELLES DU COCKPIT (JSON) :\n" + JSON.stringify(ctx);
  const res = await relais(CLAUDE_URL, { method: "POST", headers: await claudeHeaders(), body: JSON.stringify({ model: "claude-haiku-4-5", max_tokens: 1500, system: sys, messages: [...history, { role: "user", content: text }] }) });
  if (!res.ok) throw new Error("HTTP " + res.status);
  const j = await res.json();
  const raw = (j.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
  let parsed; const clean = raw.replace(/```json/g, "").replace(/```/g, "").trim();
  try { parsed = JSON.parse(clean); } catch (e) { const m = clean.match(/\{[\s\S]*\}/); try { parsed = JSON.parse(m ? m[0] : "{}"); } catch (e2) { parsed = { inScope: true, reply: raw || "Je n'ai pas pu structurer ma réponse.", actions: [] }; } }
  return { inScope: parsed.inScope !== false, reply: parsed.reply || "", actions: Array.isArray(parsed.actions) ? parsed.actions : [], usage: j.usage || null };
}
// ===== Garde-fous IA : conformite metier imposee en dur sur les sorties du modele =====
// Regles non negociables : le filament se dit "non toxique", jamais "biocompatible" (terme medical
// inexact) ni "biodegradable" / "compostable" / "biosource" (allegation environnementale non etayee,
// interdite par la loi AGEC, et d'autant plus risquee sur un produit destine aux enfants) ;
// pas d'"agrement Education nationale" (formuler "appui du Reseau Canope") ;
// jamais de marge / coefficient / prix de cession dans un texte destine au client.
function sanitizeAIText(s) {
  if (typeof s !== "string" || !s) return s;
  let t = s;
  t = t.replace(/bio-?compatibles?|biod[ée]gradables?|compostables?|bio-?sourc[ée]e?s?/gi, "non toxique");
  t = t.replace(/\bagr[ée]ment\b[^.\n]*?[ée]ducation nationale/gi, "supports pédagogiques développés avec l'appui du Réseau Canopé");
  t = t.replace(/\bagr[ée]{1,2}[^.\n]*?[ée]ducation nationale/gi, "développé avec l'appui du Réseau Canopé");
  return t;
}
// Retire d'un texte CLIENT (note de devis/commande) toute clause citant marge, coefficient ou prix de cession.
function stripInternalPricing(s) {
  if (typeof s !== "string" || !s) return s;
  const segs = s.split(/([.;\n]+)/); let out = "";
  for (let i = 0; i < segs.length; i += 2) { const clause = segs[i] || ""; const sep = segs[i + 1] || ""; if (!/(marge|coefficient|\bcoef\b|prix de cession|cession\s*ht)/i.test(clause)) out += clause + sep; }
  return out.trim();
}
// Anti-invention : refuse une action IA referencant un enregistrement inexistant. Renvoie un message ou null si OK.
function validateAIAction(act, p) {
  const acc = (id) => !id || (p.accounts || []).some((a) => a.id === id);
  const prod = (code) => (p.products || []).some((x) => x.code === code);
  if (act.type === "create_deal") { if (!acc(act.accountId)) return "compte introuvable"; const bad = (act.lines || []).filter((l) => !prod(l.code)).map((l) => l.code); if (bad.length) return "produit(s) inconnu(s) : " + bad.join(", "); }
  if (act.type === "add_interaction" && !acc(act.accountId)) return "compte introuvable";
  if (act.type === "update_product" && !prod(act.code)) return "produit introuvable : " + act.code;
  if (act.type === "add_event" && !acc(act.accountId)) return "compte introuvable";
  return null;
}
