    if (!SR) { setMsgs((m) => [...m, { role: "bot", text: "La dictée vocale n'est pas supportée par ce navigateur (essayez Chrome ou Edge)." }]); return; }
    if (listening && recRef.current) { recRef.current.stop(); return; }
