    const hist = msgs.filter((m, i) => !(i === 0 && m.role === "bot")).map((m) => ({ role: m.role === "user" ? "user" : "assistant", content: m.text })).filter((m) => m.content);
    while (hist.length && hist[0].role !== "user") hist.shift();
